text:
:where(html[dir='ltr']),
:where([data-sonner-toaster][dir='ltr']) {
  --toast-icon-margin-start: -3px;
  --toast-icon-margin-end: 4px;
  --toast-svg-margin-start: -1px;
  --toast-svg-margin-end: 0px;
  --toast-button-margin-start: auto;
  --toast-button-margin-end: 0;
  --toast-close-button-start: 0;
  --toast-close-button-end: unset;
  --toast-close-button-transform: translate(-35%, -35%);
}

:where(html[dir='rtl']),
:where([data-sonner-toaster][dir='rtl']) {
  --toast-icon-margin-start: 4px;
  --toast-icon-margin-end: -3px;
  --toast-svg-margin-start: 0px;
  --toast-svg-margin-end: -1px;
  --toast-button-margin-start: 0;
  --toast-button-margin-end: auto;
  --toast-close-button-start: unset;
  --toast-close-button-end: 0;
  --toast-close-button-transform: translate(35%, -35%);
}

:where([data-sonner-toaster]) {
  position: fixed;
  width: var(--width);
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial,
    Noto Sans, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol, Noto Color Emoji;
  --gray1: hsl(0, 0%, 99%);
  --gray2: hsl(0, 0%, 97.3%);
  --gray3: hsl(0, 0%, 95.1%);
  --gray4: hsl(0, 0%, 93%);
  --gray5: hsl(0, 0%, 90.9%);
  --gray6: hsl(0, 0%, 88.7%);
  --gray7: hsl(0, 0%, 85.8%);
  --gray8: hsl(0, 0%, 78%);
  --gray9: hsl(0, 0%, 56.1%);
  --gray10: hsl(0, 0%, 52.3%);
  --gray11: hsl(0, 0%, 43.5%);
  --gray12: hsl(0, 0%, 9%);
  --border-radius: 8px;
  box-sizing: border-box;
  padding: 0;
  margin: 0;
  list-style: none;
  outline: none;
  z-index: 999999999;
  transition: transform 400ms ease;
}

:where([data-sonner-toaster][data-lifted='true']) {
  transform: translateY(-10px);
}

@media (hover: none) and (pointer: coarse) {
  :where([data-sonner-toaster][data-lifted='true']) {
    transform: none;
  }
}

:where([data-sonner-toaster][data-x-position='right']) {
  right: var(--offset-right);
}

:where([data-sonner-toaster][data-x-position='left']) {
  left: var(--offset-left);
}

:where([data-sonner-toaster][data-x-position='center']) {
  left: 50%;
  transform: translateX(-50%);
}

:where([data-sonner-toaster][data-y-position='top']) {
  top: var(--offset-top);
}

:where([data-sonner-toaster][data-y-position='bottom']) {
  bottom: var(--offset-bottom);
}

:where([data-sonner-toast]) {
  --y: translateY(100%);
  --lift-amount: calc(var(--lift) * var(--gap));
  z-index: var(--z-index);
  position: absolute;
  opacity: 0;
  transform: var(--y);
  filter: blur(0);
  /* https://stackoverflow.com/questions/48124372/pointermove-event-not-working-with-touch-why-not */
  touch-action: none;
  transition: transform 400ms, opacity 400ms, height 400ms, box-shadow 200ms;
  box-sizing: border-box;
  outline: none;
  overflow-wrap: anywhere;
}

:where([data-sonner-toast][data-styled='true']) {
  padding: 16px;
  background: var(--normal-bg);
  border: 1px solid var(--normal-border);
  color: var(--normal-text);
  border-radius: var(--border-radius);
  box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1);
  width: var(--width);
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 6px;
}

:where([data-sonner-toast]:focus-visible) {
  box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1), 0 0 0 2px rgba(0, 0, 0, 0.2);
}

:where([data-sonner-toast][data-y-position='top']) {
  top: 0;
  --y: translateY(-100%);
  --lift: 1;
  --lift-amount: calc(1 * var(--gap));
}

:where([data-sonner-toast][data-y-position='bottom']) {
  bottom: 0;
  --y: translateY(100%);
  --lift: -1;
  --lift-amount: calc(var(--lift) * var(--gap));
}

:where([data-sonner-toast]) :where([data-description]) {
  font-weight: 400;
  line-height: 1.4;
  color: inherit;
}

:where([data-sonner-toast]) :where([data-title]) {
  font-weight: 500;
  line-height: 1.5;
  color: inherit;
}

:where([data-sonner-toast]) :where([data-icon]) {
  display: flex;
  height: 16px;
  width: 16px;
  position: relative;
  justify-content: flex-start;
  align-items: center;
  flex-shrink: 0;
  margin-left: var(--toast-icon-margin-start);
  margin-right: var(--toast-icon-margin-end);
}

:where([data-sonner-toast][data-promise='true']) :where([data-icon]) > svg {
  opacity: 0;
  transform: scale(0.8);
  transform-origin: center;
  animation: sonner-fade-in 300ms ease forwards;
}

:where([data-sonner-toast]) :where([data-icon]) > * {
  flex-shrink: 0;
}

:where([data-sonner-toast]) :where([data-icon]) svg {
  margin-left: var(--toast-svg-margin-start);
  margin-right: var(--toast-svg-margin-end);
}

:where([data-sonner-toast]) :where([data-content]) {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

[data-sonner-toast][data-styled='true'] [data-button] {
  border-radius: 4px;
  padding-left: 8px;
  padding-right: 8px;
  height: 24px;
  font-size: 12px;
  color: var(--normal-bg);
  background: var(--normal-text);
  margin-left: var(--toast-button-margin-start);
  margin-right: var(--toast-button-margin-end);
  border: none;
  cursor: pointer;
  outline: none;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  transition: opacity 400ms, box-shadow 200ms;
}

:where([data-sonner-toast]) :where([data-button]):focus-visible {
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.4);
}

:where([data-sonner-toast]) :where([data-button]):first-of-type {
  margin-left: var(--toast-button-margin-start);
  margin-right: var(--toast-button-margin-end);
}

:where([data-sonner-toast]) :where([data-cancel]) {
  color: var(--normal-text);
  background: rgba(0, 0, 0, 0.08);
}

:where([data-sonner-toast][data-theme='dark']) :where([data-cancel]) {
  background: rgba(255, 255, 255, 0.3);
}

:where([data-sonner-toast]) :where([data-close-button]) {
  position: absolute;
  left: var(--toast-close-button-start);
  right: var(--toast-close-button-end);
  top: 0;
  height: 20px;
  width: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  color: var(--gray12);
  border: 1px solid var(--gray4);
  transform: var(--toast-close-button-transform);
  border-radius: 50%;
  cursor: pointer;
  z-index: 1;
  transition: opacity 100ms, background 200ms, border-color 200ms;
}

[data-sonner-toast] [data-close-button] {
  background: var(--gray1);
}

:where([data-sonner-toast]) :where([data-close-button]):focus-visible {
  box-shadow: 0px 4px 12px rgba(0, 0, 0, 0.1), 0 0 0 2px rgba(0, 0, 0, 0.2);
}

:where([data-sonner-toast]) :where([data-disabled='true']) {
  cursor: not-allowed;
}

:where([data-sonner-toast]):hover :where([data-close-button]):hover {
  background: var(--gray2);
  border-color: var(--gray5);
}

/* Leave a ghost div to avoid setting hover to false when swiping out */
:where([data-sonner-toast][data-swiping='true'])::before {
  content: '';
  position: absolute;
  left: -50%;
  right: -50%;
  height: 100%;
  z-index: -1;
}

:where([data-sonner-toast][data-y-position='top'][data-swiping='true'])::before {
  /* y 50% needed to distribute height additional height evenly */
  bottom: 50%;
  transform: scaleY(3) translateY(50%);
}

:where([data-sonner-toast][data-y-position='bottom'][data-swiping='true'])::before {
  /* y -50% needed to distribute height additional height evenly */
  top: 50%;
  transform: scaleY(3) translateY(-50%);
}

/* Leave a ghost div to avoid setting hover to false when transitioning out */
:where([data-sonner-toast][data-swiping='false'][data-removed='true'])::before {
  content: '';
  position: absolute;
  inset: 0;
  transform: scaleY(2);
}

/* Needed to avoid setting hover to false when inbetween toasts */
:where([data-sonner-toast])::after {
  content: '';
  position: absolute;
  left: 0;
  height: calc(var(--gap) + 1px);
  bottom: 100%;
  width: 100%;
}

:where([data-sonner-toast][data-mounted='true']) {
  --y: translateY(0);
  opacity: 1;
}

:where([data-sonner-toast][data-expanded='false'][data-front='false']) {
  --scale: var(--toasts-before) * 0.05 + 1;
  --y: translateY(calc(var(--lift-amount) * var(--toasts-before))) scale(calc(-1 * var(--scale)));
  height: var(--front-toast-height);
}

:where([data-sonner-toast]) > * {
  transition: opacity 400ms;
}

:where([data-sonner-toast][data-expanded='false'][data-front='false'][data-styled='true']) > * {
  opacity: 0;
}

:where([data-sonner-toast][data-visible='false']) {
  opacity: 0;
  pointer-events: none;
}

:where([data-sonner-toast][data-mounted='true'][data-expanded='true']) {
  --y: translateY(calc(var(--lift) * var(--offset)));
  height: var(--initial-height);
}

:where([data-sonner-toast][data-removed='true'][data-front='true'][data-swipe-out='false']) {
  --y: translateY(calc(var(--lift) * -100%));
  opacity: 0;
}

:where([data-sonner-toast][data-removed='true'][data-front='false'][data-swipe-out='false'][data-expanded='true']) {
  --y: translateY(calc(var(--lift) * var(--offset) + var(--lift) * -100%));
  opacity: 0;
}

:where([data-sonner-toast][data-removed='true'][data-front='false'][data-swipe-out='false'][data-expanded='false']) {
  --y: translateY(40%);
  opacity: 0;
  transition: transform 500ms, opacity 200ms;
}

/* Bump up the height to make sure hover state doesn't get set to false */
:where([data-sonner-toast][data-removed='true'][data-front='false'])::before {
  height: calc(var(--initial-height) + 20%);
}

[data-sonner-toast][data-swiping='true'] {
  transform: var(--y) translateY(var(--swipe-amount-y, 0px)) translateX(var(--swipe-amount-x, 0px));
  transition: none;
}

[data-sonner-toast][data-swiped='true'] {
  user-select: none;
}

[data-sonner-toast][data-swipe-out='true'][data-y-position='bottom'],
[data-sonner-toast][data-swipe-out='true'][data-y-position='top'] {
  animation-duration: 200ms;
  animation-timing-function: ease-out;
  animation-fill-mode: forwards;
}

[data-sonner-toast][data-swipe-out='true'][data-swipe-direction='left'] {
  animation-name: swipe-out-left;
}

[data-sonner-toast][data-swipe-out='true'][data-swipe-direction='right'] {
  animation-name: swipe-out-right;
}

[data-sonner-toast][data-swipe-out='true'][data-swipe-direction='up'] {
  animation-name: swipe-out-up;
}

[data-sonner-toast][data-swipe-out='true'][data-swipe-direction='down'] {
  animation-name: swipe-out-down;
}

@keyframes swipe-out-left {
  from {
    transform: var(--y) translateX(var(--swipe-amount-x));
    opacity: 1;
  }

  to {
    transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-right {
  from {
    transform: var(--y) translateX(var(--swipe-amount-x));
    opacity: 1;
  }

  to {
    transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-up {
  from {
    transform: var(--y) translateY(var(--swipe-amount-y));
    opacity: 1;
  }

  to {
    transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%));
    opacity: 0;
  }
}

@keyframes swipe-out-down {
  from {
    transform: var(--y) translateY(var(--swipe-amount-y));
    opacity: 1;
  }

  to {
    transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%));
    opacity: 0;
  }
}

@media (max-width: 600px) {
  [data-sonner-toaster] {
    position: fixed;
    right: var(--mobile-offset-right);
    left: var(--mobile-offset-left);
    width: 100%;
  }

  [data-sonner-toaster][dir='rtl'] {
    left: calc(var(--mobile-offset-left) * -1);
  }

  [data-sonner-toaster] [data-sonner-toast] {
    left: 0;
    right: 0;
    width: calc(100% - var(--mobile-offset-left) * 2);
  }

  [data-sonner-toaster][data-x-position='left'] {
    left: var(--mobile-offset-left);
  }

  [data-sonner-toaster][data-y-position='bottom'] {
    bottom: var(--mobile-offset-bottom);
  }

  [data-sonner-toaster][data-y-position='top'] {
    top: var(--mobile-offset-top);
  }

  [data-sonner-toaster][data-x-position='center'] {
    left: var(--mobile-offset-left);
    right: var(--mobile-offset-right);
    transform: none;
  }
}

[data-sonner-toaster][data-theme='light'] {
  --normal-bg: #fff;
  --normal-border: var(--gray4);
  --normal-text: var(--gray12);

  --success-bg: hsl(143, 85%, 96%);
  --success-border: hsl(145, 92%, 91%);
  --success-text: hsl(140, 100%, 27%);

  --info-bg: hsl(208, 100%, 97%);
  --info-border: hsl(221, 91%, 91%);
  --info-text: hsl(210, 92%, 45%);

  --warning-bg: hsl(49, 100%, 97%);
  --warning-border: hsl(49, 91%, 91%);
  --warning-text: hsl(31, 92%, 45%);

  --error-bg: hsl(359, 100%, 97%);
  --error-border: hsl(359, 100%, 94%);
  --error-text: hsl(360, 100%, 45%);
}

[data-sonner-toaster][data-theme='light'] [data-sonner-toast][data-invert='true'] {
  --normal-bg: #000;
  --normal-border: hsl(0, 0%, 20%);
  --normal-text: var(--gray1);
}

[data-sonner-toaster][data-theme='dark'] [data-sonner-toast][data-invert='true'] {
  --normal-bg: #fff;
  --normal-border: var(--gray3);
  --normal-text: var(--gray12);
}

[data-sonner-toaster][data-theme='dark'] {
  --normal-bg: #000;
  --normal-bg-hover: hsl(0, 0%, 12%);
  --normal-border: hsl(0, 0%, 20%);
  --normal-border-hover: hsl(0, 0%, 25%);
  --normal-text: var(--gray1);

  --success-bg: hsl(150, 100%, 6%);
  --success-border: hsl(147, 100%, 12%);
  --success-text: hsl(150, 86%, 65%);

  --info-bg: hsl(215, 100%, 6%);
  --info-border: hsl(223, 100%, 12%);
  --info-text: hsl(216, 87%, 65%);

  --warning-bg: hsl(64, 100%, 6%);
  --warning-border: hsl(60, 100%, 12%);
  --warning-text: hsl(46, 87%, 65%);

  --error-bg: hsl(358, 76%, 10%);
  --error-border: hsl(357, 89%, 16%);
  --error-text: hsl(358, 100%, 81%);
}

[data-sonner-toaster][data-theme='dark'] [data-sonner-toast] [data-close-button] {
  background: var(--normal-bg);
  border-color: var(--normal-border);
  color: var(--normal-text);
}

[data-sonner-toaster][data-theme='dark'] [data-sonner-toast] [data-close-button]:hover {
  background: var(--normal-bg-hover);
  border-color: var(--normal-border-hover);
}

[data-rich-colors='true'][data-sonner-toast][data-type='success'] {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--success-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='success'] [data-close-button] {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--success-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='info'] {
  background: var(--info-bg);
  border-color: var(--info-border);
  color: var(--info-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='info'] [data-close-button] {
  background: var(--info-bg);
  border-color: var(--info-border);
  color: var(--info-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='warning'] {
  background: var(--warning-bg);
  border-color: var(--warning-border);
  color: var(--warning-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='warning'] [data-close-button] {
  background: var(--warning-bg);
  border-color: var(--warning-border);
  color: var(--warning-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='error'] {
  background: var(--error-bg);
  border-color: var(--error-border);
  color: var(--error-text);
}

[data-rich-colors='true'][data-sonner-toast][data-type='error'] [data-close-button] {
  background: var(--error-bg);
  border-color: var(--error-border);
  color: var(--error-text);
}

.sonner-loading-wrapper {
  --size: 16px;
  height: var(--size);
  width: var(--size);
  position: absolute;
  inset: 0;
  z-index: 10;
}

.sonner-loading-wrapper[data-visible='false'] {
  transform-origin: center;
  animation: sonner-fade-out 0.2s ease forwards;
}

.sonner-spinner {
  position: relative;
  top: 50%;
  left: 50%;
  height: var(--size);
  width: var(--size);
}

.sonner-loading-bar {
  animation: sonner-spin 1.2s linear infinite;
  background: var(--gray11);
  border-radius: 6px;
  height: 8%;
  left: -10%;
  position: absolute;
  top: -3.9%;
  width: 24%;
}

.sonner-loading-bar:nth-child(1) {
  animation-delay: -1.2s;
  transform: rotate(0.0001deg) translate(146%);
}

.sonner-loading-bar:nth-child(2) {
  animation-delay: -1.1s;
  transform: rotate(30deg) translate(146%);
}

.sonner-loading-bar:nth-child(3) {
  animation-delay: -1s;
  transform: rotate(60deg) translate(146%);
}

.sonner-loading-bar:nth-child(4) {
  animation-delay: -0.9s;
  transform: rotate(90deg) translate(146%);
}

.sonner-loading-bar:nth-child(5) {
  animation-delay: -0.8s;
  transform: rotate(120deg) translate(146%);
}

.sonner-loading-bar:nth-child(6) {
  animation-delay: -0.7s;
  transform: rotate(150deg) translate(146%);
}

.sonner-loading-bar:nth-child(7) {
  animation-delay: -0.6s;
  transform: rotate(180deg) translate(146%);
}

.sonner-loading-bar:nth-child(8) {
  animation-delay: -0.5s;
  transform: rotate(210deg) translate(146%);
}

.sonner-loading-bar:nth-child(9) {
  animation-delay: -0.4s;
  transform: rotate(240deg) translate(146%);
}

.sonner-loading-bar:nth-child(10) {
  animation-delay: -0.3s;
  transform: rotate(270deg) translate(146%);
}

.sonner-loading-bar:nth-child(11) {
  animation-delay: -0.2s;
  transform: rotate(300deg) translate(146%);
}

.sonner-loading-bar:nth-child(12) {
  animation-delay: -0.1s;
  transform: rotate(330deg) translate(146%);
}

@keyframes sonner-fade-in {
  0% {
    opacity: 0;
    transform: scale(0.8);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes sonner-fade-out {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(0.8);
  }
}

@keyframes sonner-spin {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion) {
  [data-sonner-toast],
  [data-sonner-toast] > *,
  .sonner-loading-bar {
    transition: none !important;
    animation: none !important;
  }
}

.sonner-loader {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  transform-origin: center;
  transition: opacity 200ms, transform 200ms;
}

.sonner-loader[data-visible='false'] {
  opacity: 0;
  transform: scale(0.8) translate(-50%, -50%);
}

/* UI-PRE-001 kit: every screen an account sees before it is linked to a business.
   Light tokens only. Button selectors double the class (`.pb-btn.pb-btn-*`) so
   they match outside the frame too and tie the global `.nf-button:hover` on
   specificity; this file loads after styles.css, so the tie goes to the kit.
   The global button rules stay untouched (THEME-005 owns that cascade). */

.pb {
  display: grid;
  min-height: 100vh;
  grid-template-columns: 280px minmax(0, 1fr);
  /* The side panel carries the tint, so the stage stays white to read as separate. */
  background: var(--theme-surface);
  color: var(--theme-text-body);
}

.pb-brand {
  color: var(--theme-accent-strong);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

/* The gate frame: a bar across the top, the stage centred on the page under it.
   Wizards keep `.pb` below, because their panel actually carries the steps. */
.pb-gate {
  display: flex;
  min-height: 100vh;
  flex-direction: column;
  background: var(--theme-surface);
  color: var(--theme-text-body);
}
.pb-topbar {
  display: flex;
  min-height: 62px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 32px;
  border-bottom: 1px solid var(--theme-border);
  background: var(--theme-surface);
}
/* The account block stacks in the side panel; in the bar it reads as one row. */
.pb-topbar .pb-account {
  flex-direction: row;
  align-items: center;
  gap: 12px;
}

.pb-side {
  position: sticky;
  top: 0;
  display: flex;
  height: 100vh;
  flex-direction: column;
  justify-content: space-between;
  /* A wizard fills the panel: on a short screen it scrolls instead of hiding the ways out. */
  gap: 18px;
  overflow-y: auto;
  padding: 28px 22px;
  border-right: 1px solid var(--theme-border);
  background: var(--theme-surface-muted);
}
/* One column of fields: heading, form and the legal row share one centre line. */
.pb-stage.pb-stage-narrow {
  width: min(100% - 48px, 420px);
  text-align: center;
}
.pb-stage-narrow .onboarding-field {
  /* A label read over its field, so those stay left even when the page is centred. */
  text-align: left;
}
.pb-stage {
  width: min(100% - 48px, 600px);
  margin: 0 auto;
  padding: 96px 0;
}

.pb-account {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}
.pb-account-id {
  display: grid;
  min-width: 0;
  color: var(--theme-muted);
  font-size: 12px;
  line-height: 1.35;
}
.pb-account-id strong {
  color: var(--theme-text);
  font-size: 13px;
}
.pb-account-id span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pb-stage h1 {
  margin: 0 0 10px;
  color: var(--theme-text);
  font-size: 30px;
  line-height: 1.2;
}
.pb-description {
  margin: 0;
  color: var(--theme-muted);
  font-size: 15px;
  line-height: 1.55;
  /* An e-mail address is one unbreakable word. */
  overflow-wrap: anywhere;
}
/* A stage-level alert follows the heading; the global rule is spaced and sized
   for a form field, so here it sat tight under the title in small print. */
.pb-stage > .form-error {
  margin: 18px 0 0;
  color: var(--theme-danger);
  font-size: 14px;
  line-height: 1.5;
}

.pb-section {
  margin-top: 32px;
}
.pb-section h2 {
  margin: 0 0 10px;
  color: var(--theme-muted-strong);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.pb-list {
  overflow: hidden;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--theme-surface);
}

.pb-row {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--theme-border-subtle);
}
.pb-row:last-child {
  border-bottom: 0;
}
.pb-row[aria-current="true"] {
  background: var(--theme-selected);
}
/* The tint is the success badge's own green, so on that row the badge turns
   white or it would read as loose text beside the role. */
.pb-row[aria-current="true"] .pb-badge-success {
  background: var(--theme-surface);
}
.pb-row-text {
  display: grid;
  min-width: 0;
  gap: 5px;
}
.pb-row-text strong {
  overflow: hidden;
  color: var(--theme-text);
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pb-row-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  color: var(--theme-muted);
  font-size: 13px;
}
.pb-row-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
}

.pb-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--theme-surface-muted);
  color: var(--theme-muted-strong);
  font-size: 12px;
  font-weight: 600;
}
.pb-badge-progress {
  background: var(--theme-warning-soft);
  color: var(--theme-warning);
}
.pb-badge-success {
  background: var(--theme-success-soft);
  color: var(--theme-success);
}
.pb-badge-danger {
  background: var(--theme-danger-soft);
  color: var(--theme-danger);
}

/* Buttons: green acts, white steps back, red only once armed. */
.pb-btn.pb-btn {
  display: inline-flex;
  width: auto;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 7px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
}
.pb-btn.pb-btn:focus-visible {
  outline: 2px solid var(--theme-focus);
  outline-offset: 2px;
}
.pb-btn.pb-btn:disabled {
  cursor: default;
  opacity: 0.55;
}
.pb-btn.pb-btn-primary {
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
.pb-btn.pb-btn-primary:hover:not(:disabled) {
  background: var(--theme-accent-strong);
}
.pb-btn.pb-btn-secondary,
.pb-btn.pb-btn-danger {
  border-color: var(--theme-border-strong);
  background: var(--theme-surface);
  color: var(--theme-text);
}
.pb-btn.pb-btn-secondary:hover:not(:disabled),
.pb-btn.pb-btn-danger:hover:not(:disabled) {
  background: var(--theme-surface-soft);
}
.pb-btn.pb-btn-danger.is-armed,
.pb-btn.pb-btn-danger.is-armed:hover:not(:disabled) {
  border-color: var(--theme-danger);
  background: var(--theme-danger);
  color: var(--theme-on-accent);
}
.pb-btn.pb-btn-block {
  width: 100%;
  min-height: 44px;
  font-size: 14px;
}

.pb-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-top: 28px;
}
.pb-stack {
  display: grid;
  gap: 10px;
  margin-top: 28px;
}

/* A text link on a form screen ("Forgot password?", "Back to sign in"). 24px
   touch target like the trust links (WCAG 2.5.8); focus ring from `a:focus-visible`. */
.pb-link {
  display: inline-flex;
  min-height: 24px;
  align-items: center;
  color: var(--theme-accent-strong);
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}
/* The way back is sometimes a button (same page, other state), not a route. */
button.pb-link {
  padding: 0;
  border: 0;
  background: none;
  font-family: inherit;
  cursor: pointer;
}
/* Focus lands on the heading only by script, to say where the person is. */
.pb-stage h1:focus {
  outline: none;
}
.pb-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}
/* Under a field it sits at the field's right edge, clear of the label column. */
.onboarding-field > .pb-link {
  justify-self: end;
}
/* The way back sits centred under the form or the answer. */
.pb-stage > .pb-link {
  margin-top: 20px;
}
/* Form and stage messages read like the stage alert above: danger colour,
   left under the fields they are about; the answer to a request, centred. */
.pb-stage-narrow .sign-in-form > .form-error {
  margin: 0;
  color: var(--theme-danger);
  font-size: 14px;
  line-height: 1.5;
  text-align: left;
}
.pb-stage > .form-success {
  margin: 18px 0 0;
  font-size: 14px;
  line-height: 1.5;
}

/* Wizard: the same frame, the side panel also says where you are. */
.pb-side-group {
  display: grid;
  min-width: 0;
  gap: 18px;
}
.pb-context {
  display: grid;
  min-width: 0;
  gap: 2px;
  margin-top: 10px;
  color: var(--theme-muted);
  font-size: 13px;
}
.pb-context strong {
  overflow: hidden;
  color: var(--theme-text);
  font-size: 17px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pb-progress {
  display: grid;
  gap: 8px;
  color: var(--theme-muted);
  font-size: 12px;
}
.pb-progress [role="progressbar"] {
  overflow: hidden;
  height: 4px;
  border-radius: 2px;
  background: var(--theme-border);
}
.pb-progress [role="progressbar"] span {
  display: block;
  height: 100%;
  background: var(--theme-accent);
}
.pb-progress p {
  margin: 0;
}
.pb-steps {
  display: grid;
  gap: 4px;
}
.pb-step {
  display: flex;
  width: 100%;
  min-height: 44px;
  align-items: center;
  gap: 12px;
  padding: 0 10px;
  border: 0;
  border-radius: 7px;
  background: none;
  color: var(--theme-muted-strong);
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
}
.pb-step:hover {
  background: var(--theme-surface);
}
.pb-step-number {
  display: grid;
  width: 24px;
  height: 24px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--theme-border-strong);
  border-radius: 50%;
  background: var(--theme-surface);
  font-size: 11px;
  font-weight: 700;
}
.pb-step.is-done .pb-step-number {
  border-color: var(--theme-success);
  color: var(--theme-success);
}
.pb-step.is-active {
  background: var(--theme-selected);
  color: var(--theme-accent-strong);
  font-weight: 700;
}
.pb-step.is-active .pb-step-number {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
.pb-step-label {
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* A wizard step is a form, not a notice: wider, and it starts higher. */
.pb-stage-wide {
  width: min(100% - 48px, 760px);
  padding: 48px 0 72px;
}
/* The step heading spaces itself with its own grid gap. */
.pb-stage-wide h1 {
  margin: 0;
}
/* Grid children stretch by default; these keep their own width. */
.pb-stage-wide .onboarding-step > .pb-btn,
.pb-stage-wide .onboarding-step > .pb-badge {
  justify-self: start;
}
/* A document page's blocks carry their own spacing inside the step grid. */
.pb-doc-block {
  display: grid;
  gap: 14px;
}
.pb-doc-block > .pb-btn {
  justify-self: start;
}

/* The step's action bar. Sticky, so on a form taller than the screen the way
   forward stays in reach; it settles into place at the end of the form. */
.pb-bar {
  position: sticky;
  bottom: 0;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  padding: 16px 0;
  border-top: 1px solid var(--theme-border);
  background: var(--theme-surface);
}
.pb-bar-end {
  display: flex;
  /* Whatever comes before it, the green button keeps the right edge. */
  margin-left: auto;
  gap: 10px;
}
.pb-bar .form-error {
  max-width: 380px;
  margin: 0;
  font-size: 13px;
  line-height: 1.45;
}
.pb-bar .pb-btn-primary {
  min-height: 42px;
  padding: 0 20px;
  font-size: 14px;
}

@media (max-width: 720px) {
  .pb {
    grid-template-columns: 1fr;
    /* Without this the two auto rows split the free height and the bar balloons. */
    align-content: start;
  }
  .pb-side {
    position: static;
    height: auto;
    flex-direction: row;
    /* At 320px the two exits do not fit beside the brand; they drop to a second row. */
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    border-right: 0;
    border-bottom: 1px solid var(--theme-border);
  }
  .pb-account {
    flex-direction: row;
    align-items: center;
  }
  /* The e-mail stays: it says which account an invitation must match. */
  .pb-account-id strong {
    display: none;
  }
  .pb-stage {
    padding: 40px 0 64px;
  }
  .pb-stage h1 {
    font-size: 24px;
  }
  .pb-row {
    flex-direction: column;
    align-items: stretch;
  }
  .pb-row-actions .pb-btn {
    flex: 1;
  }
  /* The wizard bar keeps brand, progress, the account e-mail and the two ways out. */
  .pb-context,
  .pb-steps {
    display: none;
  }
  .pb-side-group:last-child {
    display: flex;
    align-items: center;
    gap: 8px;
  }
}

/* KARARLAR "Schedule telefonda tamamen kapalı": the one line a phone sees instead of the screen. */
.desktop-only-route {
  margin: 0;
  padding: 32px 16px;
  text-align: center;
  color: var(--theme-text-secondary);
}

/* Phone navigation for owner, admin and manager (BL-192): a bottom bar in the
   shape of the Employee Hub bar (.eh-mobile-nav). Above 720px the sidebar
   stays and none of this draws. */
.mm-bar,
.mm-sheet {
  display: none;
}

@media (max-width: 720px) {
  .app-shell[data-employee-shell="false"],
  .app-shell[data-employee-shell="false"][data-sidebar-collapsed="true"] {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
  }
  /* The page scrolls above the bar, so nothing sits underneath it. */
  .app-shell[data-employee-shell="false"] > .app-main {
    grid-row: 1;
  }

  .mm-bar {
    display: grid;
    grid-row: 2;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    z-index: 30;
    padding: 7px 10px max(7px, env(safe-area-inset-bottom));
    border-top: 1px solid var(--theme-border);
    background: var(--theme-surface);
  }
  /* The on-screen keyboard needs the room while a field is being typed in. */
  .app-shell[data-employee-shell="false"]:has(input:focus, textarea:focus, select:focus)
    .mm-bar {
    display: none;
  }
  .mm-bar a,
  .mm-bar button {
    display: flex;
    min-width: 0;
    min-height: 51px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    border: 0;
    border-radius: 11px;
    background: transparent;
    color: var(--theme-muted);
    font: inherit;
    font-size: 10px;
    text-decoration: none;
    cursor: pointer;
  }
  .mm-bar span {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .mm-bar .active,
  .mm-sheet nav .active {
    background: var(--theme-selected);
    color: var(--theme-accent-strong);
    font-weight: 650;
  }
  .mm-bar :focus-visible,
  .mm-sheet :focus-visible {
    outline: 3px solid var(--theme-focus);
    outline-offset: 2px;
  }

  .mm-icon-button {
    display: grid;
    width: 44px;
    height: 44px;
    place-items: center;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--theme-text);
    cursor: pointer;
  }

  /* More rises from the bottom as a sheet. */
  .mm-sheet[open] {
    display: block;
    inset: auto 0 0;
    width: 100%;
    max-width: none;
    max-height: none;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
  }
  .mm-sheet::backdrop {
    /* Same scrim as the Account confirmation dialog; no backdrop token exists yet. */
    background: rgb(15 28 22 / 45%);
  }
  .mm-sheet-body {
    display: grid;
    gap: 4px;
    padding: 8px 12px max(16px, env(safe-area-inset-bottom));
    border-radius: 16px 16px 0 0;
    background: var(--theme-surface);
  }
  .mm-sheet-body header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-left: 8px;
    color: var(--theme-text);
    font-size: 16px;
  }
  .mm-sheet nav {
    display: grid;
    gap: 2px;
  }
  .mm-sheet nav a,
  .mm-sheet nav button {
    display: flex;
    min-height: 48px;
    align-items: center;
    gap: 12px;
    padding: 0 12px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--theme-text-body);
    font: inherit;
    font-size: 15px;
    font-weight: 600;
    text-align: left;
    text-decoration: none;
    cursor: pointer;
  }
}

.eh-dashboard,
.eh-more,
.eh-mobile-nav,
.eh-sheet {
  --eh-ink: #243a32;
  --eh-muted: var(--theme-muted);
  --eh-paper: #fff;
  --eh-wash: #f5f7f3;
  --eh-green: #25624d;
  color: var(--eh-ink);
}
/* The page container owns width, gutters and top spacing. */
.eh-dashboard {
  min-width: 0;
}
.eh-dashboard *,
.eh-sheet *,
.eh-more * {
  box-sizing: border-box;
}
.eh-dashboard a,
.eh-sheet a,
.eh-more a {
  color: inherit;
  text-decoration: none;
}
.eh-dashboard button,
.eh-sheet button,
.eh-more button {
  font: inherit;
  cursor: pointer;
}
.eh-dashboard a:focus-visible,
.eh-dashboard button:focus-visible,
.eh-dashboard input:focus-visible,
.eh-mobile-nav a:focus-visible,
.eh-sheet :focus-visible,
.eh-more :focus-visible {
  outline: 3px solid var(--theme-focus);
  outline-offset: 4px;
}
/* Both phone bars share one focus ring: 2px out stays inside the bar's padding. */
.eh-mobile-nav a:focus-visible {
  outline-offset: 2px;
}
.eh-dashboard p,
.eh-dashboard h1,
.eh-dashboard h2,
.eh-dashboard h3 {
  margin: 0;
}
.eh-context-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 76px;
  border-bottom: 1px solid var(--theme-border);
}
.eh-workspace-link,
.eh-context-actions,
.eh-private {
  display: flex;
  align-items: center;
  gap: 10px;
}
.eh-workspace-link {
  min-width: 0;
  font-size: 13px;
  font-weight: 650;
  min-height: 44px;
}
.eh-workspace-link > span:nth-child(2) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.eh-workspace-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border: 1px solid #d1ddd3;
  border-radius: 9px;
  font-family: Georgia, serif;
  color: var(--eh-green);
  background: #eaf0e7;
  font-size: 19px;
}
.eh-private {
  font-size: 11px;
  color: var(--eh-muted);
  margin-right: 10px;
}
.eh-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  padding: 6px;
  background: transparent;
  color: inherit;
  border: 0;
  border-radius: 12px;
  flex-shrink: 0;
}
.eh-icon-button:hover {
  background: var(--eh-wash);
}
.eh-avatar {
  display: grid;
  place-items: center;
  background: #e8ede3;
  border: 2px solid var(--eh-paper);
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 13px;
}
.eh-bell {
  position: relative;
}
.eh-bell > span {
  position: absolute;
  right: 0;
  top: 0;
  background: #ac5035;
  color: #fff;
  min-width: 19px;
  padding: 2px 4px;
  border: 2px solid var(--eh-wash);
  border-radius: 12px;
  font-size: 10px;
  line-height: 13px;
  text-align: center;
}
.eh-eyebrow {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 1.6px;
  line-height: 1.5;
}
.eh-date {
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: right;
  flex-shrink: 0;
}
.eh-date > span {
  font-size: 12px;
  color: var(--eh-muted);
}
.eh-date time {
  font-size: 25px;
  font-weight: 450;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.6px;
}
.eh-date small {
  color: var(--eh-muted);
  font-size: 10px;
}
.eh-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(290px, 1fr);
  gap: 20px;
  align-items: start;
}
.eh-hero {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  padding: 27px 30px;
  border-radius: 20px;
  background: #244d3c;
  color: var(--theme-on-accent);
  min-height: 277px;
  box-shadow: 0 7px 22px #244d3c0d;
}
.eh-hero::after {
  content: "";
  position: absolute;
  z-index: -1;
  width: 275px;
  height: 275px;
  border: 1px solid #ffffff12;
  border-radius: 50%;
  right: -80px;
  top: -85px;
  box-shadow:
    0 0 0 35px #ffffff04,
    0 0 0 70px #ffffff03,
    0 0 0 105px #ffffff02;
  pointer-events: none;
}
.eh-hero-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}
.eh-hero .eh-eyebrow {
  color: #e0ecda;
}
.eh-status-dot {
  width: 6px;
  height: 6px;
  background: #c8e2a9;
  border-radius: 50%;
}
.eh-hero-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid #ffffff26;
  border-radius: 12px;
  color: #d6e5c5;
}
.eh-hero h2 {
  font-size: 31px;
  line-height: 1.25;
  font-weight: 500;
  letter-spacing: -0.8px;
}
.eh-hero .eh-shift-time {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: clamp(29px, 3.1vw, 45px);
  font-weight: 500;
  letter-spacing: -1.5px;
  margin: 5px 0 13px;
  font-variant-numeric: tabular-nums;
}
.eh-shift-time > span {
  font-weight: 300;
  color: #afc5b7;
}
.eh-hero-date {
  font-size: 12px;
  color: #d4e1d8;
}
.eh-shift-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 18px;
  font-size: 13px;
}
.eh-shift-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.eh-hero .eh-hero-sub {
  font-size: 14px;
  margin-top: 12px;
  line-height: 1.6;
}
.eh-hero .eh-hero-note {
  font-size: 11px;
  color: #d0dfd4;
  line-height: 1.6;
  margin-top: 12px;
  max-width: 52ch;
}
.eh-hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px 20px;
}
.eh-hero .eh-hero-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 44px;
  padding: 11px 17px;
  margin-top: 20px;
  background: #e4edcc;
  color: #24452f;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 650;
}
.eh-hero .eh-hero-button:hover {
  background: #f0f5e4;
}
.eh-card {
  padding: 24px;
  border: 1px solid var(--theme-border);
  border-radius: 18px;
  background: var(--eh-paper);
  min-width: 0;
}
.eh-card-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 28px;
}
.eh-card-heading h2 {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.25px;
}
.eh-card-heading h2 > svg {
  color: var(--eh-muted);
  flex-shrink: 0;
}
.eh-card-heading > a {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--eh-muted);
  white-space: nowrap;
  min-height: 32px;
}
.eh-dashboard .eh-section-description {
  font-size: 11px;
  line-height: 1.6;
  color: var(--eh-muted);
  margin-top: 5px;
}
.eh-attention {
  align-self: stretch;
  display: flex;
  flex-direction: column;
}
.eh-attention-lead {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 27px 0 20px;
}
.eh-attention-number {
  color: #72936c;
  font-size: 43px;
  font-weight: 400;
  letter-spacing: -2px;
}
.eh-attention-number.has-actions {
  color: #a37029;
}
.eh-attention-lead strong {
  font-size: 14px;
  font-weight: 600;
}
.eh-attention-lead p {
  font-size: 11px;
  line-height: 1.7;
  color: var(--eh-muted);
  margin-top: 5px;
}
.eh-waiting {
  display: flex;
  align-items: center;
  gap: 9px;
  border-top: 1px solid var(--theme-border);
  padding-top: 14px;
  margin-top: auto;
  min-height: 44px;
  font-size: 11px;
  color: var(--eh-muted) !important;
}
.eh-waiting > span {
  flex: 1;
}
.eh-shortcuts {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.eh-shortcuts > a {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 84px;
  border: 1px solid var(--theme-border);
  border-radius: 14px;
  padding: 14px;
  background: var(--eh-paper);
  transition:
    border-color 150ms,
    background 150ms;
}
.eh-shortcuts > a:hover {
  background: #eff4eb;
  border-color: #b7cbb8;
}
.eh-shortcut-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  flex-shrink: 0;
  color: #466b51;
  background: #f0f3e9;
}
.eh-shortcuts strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
}
.eh-shortcuts small {
  display: block;
  margin-top: 5px;
  font-size: 10px;
  color: var(--eh-muted);
  line-height: 1.5;
}
.eh-shortcut-arrow {
  margin-left: auto;
  color: var(--eh-muted);
  flex-shrink: 0;
}
.eh-week {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 5px;
  margin: 21px 0 10px;
}
.eh-week a {
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 7px;
  padding: 12px 2px 9px;
  border-radius: 12px;
}
.eh-week a:hover {
  background: var(--eh-wash);
}
.eh-week span {
  font-size: 10px;
  color: var(--eh-muted);
}
.eh-week strong {
  font-size: 17px;
  font-weight: 550;
}
.eh-week i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
}
.eh-week i.has-shift {
  background: #658d55;
}
.eh-week a.is-today {
  background: #eaf0e2;
  color: #325c37;
}
.eh-week a.is-today span {
  color: var(--theme-muted-strong);
}
.eh-upcoming-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px 0;
  border-bottom: 1px solid var(--theme-border);
}
.eh-upcoming-row:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.eh-date-tile {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  width: 43px;
  min-height: 48px;
  flex-shrink: 0;
  border: 1px solid var(--theme-border);
  border-radius: 9px;
  background: var(--eh-wash);
}
.eh-date-tile > small {
  font-size: 9px;
  text-transform: uppercase;
  color: var(--eh-muted);
}
.eh-date-tile > strong {
  font-size: 18px;
  font-weight: 550;
}
.eh-upcoming-row > span:nth-child(2) {
  flex: 1;
  min-width: 0;
}
.eh-upcoming-row > span:nth-child(2) strong {
  font-size: 13px;
  font-weight: 600;
}
.eh-upcoming-row > span:nth-child(2) small {
  display: block;
  font-size: 11px;
  line-height: 1.6;
  color: var(--eh-muted);
  margin-top: 4px;
}
.eh-upcoming-row > svg {
  color: var(--eh-muted);
}
.eh-list-link {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 68px;
  padding: 15px 0;
  border-bottom: 1px solid var(--theme-border);
}
.eh-list-link:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.eh-list-link > span:not(.eh-update-dot) {
  min-width: 0;
  flex: 1;
}
.eh-list-link strong {
  display: block;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.6;
  overflow-wrap: anywhere;
}
.eh-list-link small {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.6;
  color: var(--eh-muted);
  margin-top: 4px;
  overflow-wrap: anywhere;
}
.eh-list-link > svg {
  flex-shrink: 0;
  color: var(--eh-muted);
}
.eh-update-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #659361;
  flex-shrink: 0;
}
.eh-update-dot.is-read {
  background: var(--theme-border);
}
.eh-notice-category {
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 9px !important;
  margin: 0 0 4px !important;
}
.eh-task-form {
  margin: 20px 0 6px;
  display: flex;
  align-items: center;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--eh-wash);
  padding-left: 12px;
}
.eh-task-form input {
  background: transparent;
  border: 0;
  font: inherit;
  font-size: 12px;
  color: var(--eh-ink);
  min-width: 0;
  flex: 1;
  min-height: 44px;
}
.eh-task-form input::placeholder {
  color: var(--eh-muted);
}
.eh-task-form button {
  color: var(--eh-green);
}
.eh-dashboard button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.eh-task-list > div {
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--theme-border);
}
.eh-task-list label {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 52px;
  flex: 1;
  cursor: pointer;
  font-size: 12px;
  line-height: 1.6;
  padding: 8px 0;
}
.eh-task-list label span {
  overflow-wrap: anywhere;
  min-width: 0;
}
.eh-task-list input {
  width: 18px;
  height: 18px;
  accent-color: #47754f;
  flex-shrink: 0;
}
.eh-task-list .is-completed label span {
  text-decoration: line-through;
  color: var(--eh-muted);
}
.eh-tasks-empty {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 0;
  color: var(--eh-muted);
}
.eh-tasks-empty svg {
  flex-shrink: 0;
  color: #91a88a;
}
.eh-tasks-empty p {
  font-size: 12px;
  line-height: 1.7;
}
.eh-task-tools {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}
.eh-task-tools button {
  background: transparent;
  border: 0;
  padding: 0;
  min-height: 44px;
  font-size: 11px;
  color: var(--eh-muted);
}
.eh-team-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px 10px;
  margin: 20px 0;
}
.eh-team-list > div {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.eh-team-avatar {
  display: grid;
  place-items: center;
  background: #eceee5;
  border-radius: 50%;
  min-width: 34px;
  height: 34px;
  font-size: 10px;
  color: #5b6a46;
}
.eh-team-list strong {
  font-size: 11px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.eh-team-list small {
  display: block;
  font-size: 10px;
  color: var(--eh-muted);
  margin-top: 4px;
}
.eh-dashboard .eh-empty {
  font-size: 12px;
  line-height: 1.8;
  color: var(--eh-muted);
  padding: 22px 0 8px;
}
.eh-panel-error {
  font-size: 12px;
  padding: 20px 0;
  color: var(--eh-muted);
}
.eh-panel-error button {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  color: var(--eh-green);
  padding: 0;
  border: 0;
  background: transparent;
}
.eh-error {
  color: #a34b32;
  font-size: 12px;
  line-height: 1.6;
  padding-top: 8px;
}
.eh-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  background: #fcf2df;
  border: 1px solid #ebd9b3;
  border-radius: 12px;
  padding: 12px 16px;
  margin-bottom: 20px;
  color: #74562b;
  font-size: 12px;
}
.eh-notice button {
  background: none;
  border: 0;
  text-decoration: underline;
  color: inherit;
  min-height: 44px;
}
.eh-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 25px 2px 0;
  font-size: 10px;
  color: var(--eh-muted);
}
.eh-footer > * {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
}
.eh-mobile-nav {
  display: none;
}
.eh-more {
  max-width: 680px;
  margin: 0 auto;
}
.eh-more > div {
  margin-top: 20px;
  background: var(--eh-paper);
  border: 1px solid var(--theme-border);
  border-radius: 16px;
  overflow: hidden;
}
.eh-more > div > a {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px;
  border-bottom: 1px solid var(--theme-border);
}
.eh-more a:hover {
  background: var(--eh-wash);
}
.eh-more a span {
  flex: 1;
}
.eh-more strong {
  display: block;
  font-size: 14px;
}
.eh-more small {
  display: block;
  color: var(--eh-muted);
  margin-top: 5px;
  font-size: 12px;
}
.eh-sign-out {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 15px 0;
  background: none;
  border: 0;
  color: #9c4e3d;
  margin-top: 20px;
}
.eh-sheet {
  border: 1px solid var(--theme-border);
  background: var(--eh-paper);
  border-radius: 22px;
  padding: 28px;
  width: min(480px, calc(100vw - 32px));
  max-height: calc(100dvh - 32px);
  overflow: auto;
  box-shadow: 0 24px 90px #102c2833;
}
.eh-sheet::backdrop {
  background: #17292360;
  backdrop-filter: blur(3px);
}
.eh-sheet-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
}
.eh-sheet-heading h2 {
  margin: 0;
  font-size: 20px;
}
.eh-sheet-time {
  font-size: 34px;
  margin: 16px 0;
  font-weight: 500;
  letter-spacing: -1px;
}
.eh-sheet-location {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
}
.eh-sheet .eh-section-description {
  color: var(--eh-muted);
  font-size: 12px;
  line-height: 1.7;
}
.eh-primary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding: 12px;
  background: #28583f;
  color: var(--theme-on-accent) !important;
  border-radius: 10px;
  font-size: 14px;
  margin-top: 24px;
}
.eh-sheet-link {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  font-size: 13px;
  margin-top: 8px;
}
.eh-shift-note {
  padding: 16px;
  background: var(--eh-wash);
  border-radius: 12px;
  margin-top: 22px;
}
.eh-shift-note h3 {
  font-size: 12px;
  margin: 0 0 8px;
}
.eh-shift-note p {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 13px;
  line-height: 1.7;
  margin: 0;
}
.hub-action-list > div:target,
.hub-panel:target {
  outline: 2px solid #749a76;
  outline-offset: 5px;
  scroll-margin: 25px;
}
.eh-loading {
  padding: 36px;
  min-height: 400px;
}
.eh-loading-bar {
  height: 28px;
  max-width: 300px;
  border-radius: 10px;
  background: #e7ece4;
  margin: 24px 0;
}
.eh-loading-block {
  height: 260px;
  border-radius: 20px;
  background: #e7ece4;
}
@media (max-width: 1180px) {
  .eh-dashboard {
    padding-inline: 24px;
  }
  .eh-dashboard-grid {
    grid-template-columns: minmax(0, 1.2fr) minmax(270px, 1fr);
    gap: 16px;
  }
  .eh-shortcuts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .eh-shortcuts > a {
    min-height: 74px;
  }
  .eh-hero {
    padding: 24px;
  }
  .eh-date > span {
    max-width: 150px;
    line-height: 1.5;
  }
}
@media (max-width: 980px) {
  .eh-dashboard-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .eh-attention-lead {
    padding: 15px 0;
  }
  .eh-attention {
    padding: 20px 24px;
  }
  .eh-private {
    display: none;
  }
  .eh-shortcuts {
    grid-row: 3;
  }
}
@media (max-width: 720px) {
  body:has(.app-shell[data-employee-shell="true"]) {
    min-width: 0;
  }
  .app-shell[data-employee-shell="true"],
  .app-shell[data-employee-shell="true"][data-sidebar-collapsed="true"] {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 1fr) auto;
  }
  .app-shell[data-employee-shell="true"] > .app-sidebar {
    display: none;
  }
  .app-shell[data-employee-shell="true"] > .app-main {
    grid-row: 1;
    scrollbar-gutter: auto;
  }
  .eh-mobile-nav {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-row: 2;
    padding: 7px 10px max(7px, env(safe-area-inset-bottom));
    border-top: 1px solid var(--theme-border);
    background: var(--eh-paper);
    z-index: 30;
  }
  .eh-mobile-nav a {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    color: var(--eh-muted);
    text-decoration: none;
    min-height: 51px;
    font-size: 10px;
    border-radius: 11px;
  }
  .eh-mobile-nav a.active {
    background: var(--theme-selected);
    color: var(--theme-accent-strong);
    font-weight: 650;
  }
  .app-shell[data-employee-shell="true"]:has(
      input:focus,
      textarea:focus,
      select:focus
    )
    .eh-mobile-nav {
    display: none;
  }
  .employee-hub-page {
    min-width: 0;
  }
  .eh-dashboard {
    padding: 0 18px 20px;
  }
  .eh-context-bar {
    min-height: 66px;
  }
  .eh-context-actions {
    gap: 1px;
  }
  .eh-date {
    display: flex;
    align-items: center;
    flex-direction: row;
    gap: 9px;
    margin-top: 13px;
    text-align: left;
  }
  .eh-date > span {
    max-width: none;
    font-size: 11px;
  }
  .eh-date time {
    font-size: 11px;
    color: var(--eh-muted);
    letter-spacing: 0;
  }
  .eh-date time::before {
    content: "·";
    padding-right: 9px;
  }
  .eh-date small {
    display: none;
  }
  .eh-dashboard-grid {
    gap: 16px;
  }
  .eh-hero {
    border-radius: 18px;
    min-height: 0;
    padding: 22px;
  }
  .eh-hero-top {
    margin-bottom: 14px;
  }
  .eh-hero .eh-shift-time {
    font-size: 36px;
    gap: 10px;
  }
  .eh-hero .eh-hero-note {
    font-size: 10px;
  }
  .eh-hero .eh-hero-button {
    min-height: 46px;
    flex: 1;
  }
  .eh-attention {
    padding: 18px;
  }
  .eh-attention .eh-card-heading {
    min-height: 22px;
  }
  .eh-attention-lead {
    gap: 14px;
    padding: 14px 0;
  }
  .eh-attention-number {
    font-size: 31px;
  }
  .eh-attention-number svg {
    width: 28px;
    height: 28px;
  }
  .eh-shortcuts {
    gap: 10px;
  }
  .eh-shortcuts > a {
    gap: 9px;
    padding: 13px 10px;
    min-height: 74px;
  }
  .eh-shortcut-icon {
    width: 30px;
    height: 34px;
    background: transparent;
  }
  .eh-shortcuts strong {
    font-size: 11px;
    line-height: 1.6;
  }
  .eh-shortcuts small,
  .eh-shortcut-arrow {
    display: none;
  }
  .eh-card {
    padding: 20px;
    border-radius: 16px;
  }
  .eh-card-heading h2 {
    font-size: 14px;
  }
  .eh-card-heading > a {
    min-height: 44px;
  }
  .eh-week {
    margin-top: 12px;
    gap: 2px;
  }
  .eh-week span {
    font-size: 9px;
  }
  .eh-week strong {
    font-size: 16px;
  }
  .eh-task-form input {
    font-size: 16px;
  }
  .eh-task-form input::placeholder {
    font-size: 12px;
  }
  .eh-footer {
    flex-wrap: wrap;
    gap: 0;
    padding-top: 14px;
  }
  .eh-sheet {
    width: 100%;
    max-width: none;
    max-height: calc(100dvh - 24px);
    margin: auto 0 0;
    border-radius: 22px 22px 0 0;
    padding: 24px 22px max(24px, env(safe-area-inset-bottom));
  }
  .eh-sheet-time {
    font-size: 30px;
  }
  .employee-hub-page .hub-panel input,
  .employee-hub-page .hub-panel select,
  .employee-hub-page .hub-panel textarea {
    font-size: 16px;
    min-height: 44px;
  }
}
@media (max-width: 350px) {
  .eh-hero {
    padding: 19px;
  }
  .eh-hero .eh-shift-time {
    font-size: 30px;
    gap: 8px;
  }
  .eh-card {
    padding: 17px;
  }
  .eh-team-list {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 760px) {
  .eh-attention.is-clear {
    padding: 13px 18px;
  }
  .eh-attention.is-clear .eh-card-heading,
  .eh-attention.is-clear .eh-attention-lead p {
    display: none;
  }
