/* Inter, the brand typeface (Mert, 2026-10-04). Self-hosted Google Fonts v20
   subsets, SIL OFL 1.1 (public/fonts/inter-OFL.txt); latin-ext loads only for
   names such as "José Peña". */
@font-face {
  font-family: Inter;
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url("/fonts/inter-latin-ext.woff2") format("woff2");
  unicode-range:
    U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304,
    U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB,
    U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF;
}
@font-face {
  font-family: Inter;
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url("/fonts/inter-latin.woff2") format("woff2");
  unicode-range:
    U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC,
    U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212,
    U+2215, U+FEFF, U+FFFD;
}
:root {
  /* Light theme tokens (THEME-002). New UI uses these instead of raw hex. */
  --theme-font-sans:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  --theme-page: #f4f5f3;
  --theme-surface: #ffffff;
  --theme-surface-soft: #f7f9f8;
  --theme-surface-muted: #f0f3f1;
  --theme-text: #17221e;
  --theme-text-body: #1d2525;
  --theme-muted: #66716c;
  /* Secondary text on tinted surfaces where --theme-muted misses AA. */
  --theme-muted-strong: #5f6b66;
  --theme-border: #dce3df;
  --theme-border-subtle: #e2e6e4;
  --theme-border-strong: #cbd4d0;
  --theme-accent: #176954;
  --theme-accent-strong: #12624f;
  --theme-selected: #e7f1ed;
  --theme-focus: #177a64;
  --theme-action: #111827;
  --theme-action-hover: #1f2937;
  --theme-danger: #b84234;
  --theme-danger-soft: #fff0ee;
  --theme-warning: #8a5a00;
  --theme-warning-soft: #fff7e2;
  --theme-success: #176b4e;
  --theme-success-soft: #e7f1ed;
  --theme-current: #b7791f;
  --theme-on-accent: #ffffff;
  /* Account screens (BL-148): kept at their exact values, no nearer token fits. */
  --theme-text-secondary: #50605a;
  --theme-text-menu: #26352f;
  --theme-accent-soft: #dbece5;
  --theme-accent-deep: #244c3d;
  --theme-focus-halo: #c9eadf;
  --theme-border-hover: #95aaa1;
  --theme-warning-surface: #fbf6ec;
  --theme-warning-border: #bf872d;
  --theme-warning-text: #5f491f;
  --theme-danger-surface: #fff8f6;
  --theme-danger-border: #ad3f36;
  --theme-danger-text: #653b36;
  --theme-danger-strong: #a43830;
  /* Schedule availability (G14, Mert 2026-10-01): orange is a preference the
     manager may still schedule over, red is approved time off (a block). */
  --theme-availability: #d9730d;
  --theme-availability-soft: #fff1e2;
  --theme-time-off: #d4162a;
  --theme-time-off-soft: #ffe2e5;
  --theme-accent-focus: #236844;
  /* Schedule publication state (BL-312): green when the whole week is live,
     amber when only some locations are. Kept at their exact values. */
  --theme-published: #087f5b;
  --theme-published-hover: #0b6f53;
  --theme-published-partial: #b45309;
  --theme-published-partial-hover: #92400e;
  /* The edge every Schedule top bar control shares (G14); value unchanged. */
  --theme-border-control: #aeb9b4;
  /* The dot of a location, or the chip of a person, that has no colour of its own. */
  --theme-swatch-fallback: #64748b;
  --theme-swatch-fallback-soft: #cbd5e1;
  /* A manager's note on a Schedule shift (BL-199): its own ink, so a note
     never reads as a status, a warning or a selection. 7.6:1 on white. */
  --theme-note: #2f4fa3;
  /* List pages (DOC-TABLE, KARARLAR Genel → "Liste sayfalarının ortak dili"):
     table frame, column-heading row, body cell ink, the line between
     Availability day headings, and the faint "—" / disabled ink. */
  --theme-list-frame: #d7dcda;
  --theme-list-head: #e6ece8;
  --theme-list-head-border: #d3dbd6;
  --theme-list-head-text: #4f5d57;
  --theme-list-cell-text: #46514d;
  --theme-list-col-line: #dce1de;
  --theme-text-faint: var(--theme-border-control);
  --theme-availability-text: #8a4a06;
  --schedule-action: var(--theme-action);
  --schedule-action-hover: var(--theme-action-hover);
  --schedule-grid-line-color: #dce2df;
  --schedule-grid-line-width: 1px;
  --schedule-section-line-color: #8fa098;
  --schedule-unassigned-row-background: #fef3c7;
  --schedule-unassigned-line-color: #d6a23a;
  --schedule-unassigned-line-width: 2px;
  --schedule-badge-radius: 4px;
  --schedule-cell-edit-inset: 4px;
  --schedule-cell-preview-inset: 1px;
  --schedule-location-boundary-width: 3px;
  --schedule-badge-edit-gap: 2px;
  --schedule-badge-preview-gap: 1px;
  --schedule-add-shift-lane-height: 28px;
  --schedule-focus-ring-color: var(--theme-focus);
  --schedule-current-ring-color: var(--theme-current);
  /* Ghost shift card: switched-off gray, shared by every ghost. */
  --schedule-ghost-edge: #d3d9d6;
  --schedule-ghost-text: #56615c;
  --schedule-motion-fast: 120ms;
  --schedule-motion-state: 150ms;
  color: var(--theme-text-body);
  background: var(--theme-page);
  font-family: var(--theme-font-sans);
  font-synthesis: none;
}

.schedule-design-surface {
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  background: #eef1ed;
  color: #17201d;
}

.schedule-design-toolbar {
  position: sticky;
  top: 0;
  z-index: 40;
  min-width: 0;
  padding: 14px 18px;
  border-bottom: 1px solid #cfd8d1;
  background: #f8faf7;
  display: grid;
  grid-template-columns: minmax(240px, 1fr) auto auto;
  align-items: center;
  gap: 16px;
}

.schedule-design-toolbar h1,
.schedule-design-toolbar p,
.schedule-design-log p {
  margin: 0;
}

.schedule-design-toolbar h1 {
  font-size: 18px;
  line-height: 1.2;
}

.schedule-design-toolbar p {
  margin-top: 3px;
  color: #607169;
  font-size: 12px;
}

.schedule-design-actions,
.schedule-design-toggles {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.schedule-design-actions button,
.schedule-design-toggles button {
  min-height: 34px;
  border: 1px solid #bdcac1;
  border-radius: 6px;
  padding: 0 10px;
  background: var(--theme-surface);
  color: #1f2a26;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.schedule-design-actions button:hover,
.schedule-design-toggles button:hover,
.schedule-design-toggles button[aria-pressed="true"] {
  border-color: #7ea08d;
  background: #e8f4ee;
}

.schedule-design-toggles label {
  min-height: 34px;
  border: 1px solid #bdcac1;
  border-radius: 6px;
  padding: 0 10px;
  background: var(--theme-surface);
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #314039;
  font-size: 12px;
  font-weight: 700;
}

.schedule-design-grid {
  min-width: 0;
  min-height: 0;
  padding: 14px;
  overflow: hidden;
}

.schedule-design-log {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 60;
  width: min(340px, calc(100vw - 36px));
  border: 1px solid #c8d1ca;
  border-radius: 8px;
  padding: 10px 12px;
  background: rgb(255 255 255 / 94%);
  box-shadow: 0 16px 40px rgb(18 38 28 / 14%);
  display: grid;
  gap: 5px;
  color: #42524a;
  font-size: 12px;
}

.schedule-badge-lab-clone {
  display: contents;
}

