  .schedule-badge-lab-clone[data-lab-mode="edit"]
    :where(.schedule-grid-scroll) {
    --schedule-location-header-height: var(--lab-location-header-height-edit);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-grid-exact > * {
    border-right-width: var(--lab-grid-line-width-edit);
    border-bottom-width: var(--lab-grid-line-width-edit);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-grid-sticky {
    box-shadow: var(--lab-sticky-separator-width-edit) 0 0 #c9d3cd;
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-grid-exact
    > [data-location-boundary="start"] {
    box-shadow: inset var(--lab-location-boundary-width-edit) 0 0 #91a29a;
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-unassigned-row-cell {
    border-bottom-width: var(--lab-unassigned-border-width-edit);
    box-shadow: inset 0 calc(-1 * var(--lab-unassigned-border-offset-edit)) 0
      var(--lab-unassigned-border-width-edit) rgb(210 145 62 / 72%);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-employee-cell[data-unassigned="true"]
    strong,
  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-unassigned-row-cell
    strong {
    font-size: var(--lab-unassigned-text-size-edit);
    transform: translate(
      var(--lab-unassigned-text-offset-x-edit),
      var(--lab-unassigned-text-offset-y-edit)
    );
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-grid-logo-frame,
  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-logo-header {
    min-height: var(--lab-logo-frame-height-edit);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-logo-image,
  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-generated-logo {
    transform: translate(
        var(--lab-logo-offset-x-edit),
        var(--lab-logo-offset-y-edit)
      )
      scale(var(--lab-logo-scale-edit));
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-location-header,
  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-total-header {
    min-height: var(--lab-location-header-height-edit);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"] .schedule-location-header {
    justify-content: var(--lab-location-header-text-align-edit);
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-location-header
    span,
  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-location-header
    strong {
    font-size: var(--lab-location-header-font-size-edit);
    transform: translate(
      var(--lab-location-header-text-offset-x-edit),
      var(--lab-location-header-text-offset-y-edit)
    );
  }

  .schedule-badge-lab-clone[data-lab-mode="edit"]
    .schedule-location-status-dot {
    width: var(--lab-location-status-dot-size-edit);
    height: var(--lab-location-status-dot-size-edit);
  }

  @media (max-width: 760px) {
    .schedule-badge-lab-control-grid {
      grid-template-columns: 1fr;
    }

    .schedule-badge-lab-tabs {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }
}

@media (max-width: 920px) {
  .schedule-design-toolbar {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .schedule-design-actions,
  .schedule-design-toggles {
    justify-content: flex-start;
  }
}

/* Employee onboarding steps. The frame around them is the prebiz kit. */
.onboarding-step {
  width: min(760px, 100%);
  margin: 0 auto;
  display: grid;
  gap: 28px;
}

.onboarding-step-icon {
  width: 48px;
  height: 48px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  color: #146c4d;
  background: #dff5ec;
}

.onboarding-eyebrow {
  margin: 0;
  color: #557169;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.onboarding-step h1,
.onboarding-step-heading h1 {
  margin: 0;
  max-width: 680px;
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.08;
  letter-spacing: 0;
}

.onboarding-lead,
.onboarding-step-heading > div {
  margin: 0;
  max-width: 620px;
  color: #596672;
  font-size: 16px;
  line-height: 1.6;
}

.onboarding-step-heading {
  display: grid;
  gap: 10px;
}

.onboarding-assignment-summary {
  width: 100%;
  margin: 0;
  padding: 18px 0;
  border-block: 1px solid #d9dfe4;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.onboarding-assignment-summary div {
  display: grid;
  gap: 5px;
}
.onboarding-assignment-summary dt {
  color: #687581;
  font-size: 12px;
  font-weight: 700;
}
.onboarding-assignment-summary dd {
  margin: 0;
  font-weight: 650;
}

.onboarding-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  /* Without this a taller cell (one with help text) stretches its neighbour and
     the two inputs in the row stop lining up. */
  align-items: start;
}

.onboarding-field {
  min-width: 0;
  display: grid;
  /* Same reason: the field's own rows keep their height instead of spreading. */
  align-content: start;
  gap: 7px;
  color: var(--theme-text-body);
  font-size: 13px;
  font-weight: 700;
}
.onboarding-field small {
  color: var(--theme-muted);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.45;
}
.onboarding-field input[readonly] {
  border-style: dashed;
  background: var(--theme-surface-muted);
  color: var(--theme-muted);
}

.onboarding-field.wide {
  grid-column: 1 / -1;
}
.onboarding-field input,
.onboarding-field select {
  width: 100%;
  height: 42px;
  /* WCAG 1.4.11: the field edge reads at >=3:1 on white (BL-136). */
  border: 1px solid var(--theme-muted);
  border-radius: 5px;
  padding: 0 11px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font: inherit;
}

.onboarding-field input:focus,
.onboarding-field select:focus {
  outline: 2px solid var(--theme-focus);
  outline-offset: 1px;
  border-color: var(--theme-focus);
}

.onboarding-privacy-options {
  margin: 0;
  padding: 18px;
  border: 1px solid #d5dce1;
  border-radius: 6px;
  display: grid;
  gap: 14px;
}

.onboarding-privacy-options legend {
  padding: 0 6px;
  font-size: 13px;
  font-weight: 750;
}
.onboarding-toggle {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  cursor: pointer;
}
.onboarding-toggle > input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.onboarding-toggle > span {
  width: 36px;
  height: 20px;
  border-radius: 10px;
  padding: 2px;
  background: #b8c2ca;
  transition: background 150ms ease;
}
.onboarding-toggle > span i {
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--theme-surface);
  transition: transform 150ms ease;
}
.onboarding-toggle > input:checked + span {
  background: #248663;
}
.onboarding-toggle > input:checked + span i {
  transform: translateX(16px);
}
.onboarding-toggle > input:focus-visible + span {
  outline: 2px solid #248663;
  outline-offset: 2px;
}
.onboarding-toggle strong {
  font-size: 13px;
}

.onboarding-upload {
  min-height: 190px;
  border: 1px dashed #9ba8b2;
  border-radius: 6px;
  background: var(--theme-surface);
  display: grid;
  place-items: center;
  align-content: center;
  gap: 7px;
  text-align: center;
  cursor: pointer;
}

.onboarding-upload:hover {
  border-color: #248663;
  background: #f5fbf8;
}
.onboarding-upload svg {
  color: #248663;
}
.onboarding-upload span {
  color: #687581;
  font-size: 12px;
}
.onboarding-upload input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.onboarding-attention {
  margin: 0;
  padding: 12px 14px;
  border-left: 3px solid #c54d42;
  background: var(--theme-danger-soft);
  color: #8d3028;
  display: flex;
  gap: 9px;
  align-items: center;
}

/* Onboarding reads the whole policy in the page flow: a box that scrolls inside
   a page that also scrolls hides how much is left to read. */
.onboarding-policy-text {
  max-height: none;
  overflow: visible;
}
/* A quiet line of context: a deadline, a signature, a note from the manager. */
.onboarding-note {
  margin: 0;
  color: #687581;
  font-size: 13px;
  line-height: 1.55;
}
.onboarding-file-list {
  margin: 14px 0 0;
  padding: 0;
  display: grid;
  gap: 8px;
  list-style: none;
}
.onboarding-file-list li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.onboarding-document-content {
  max-height: 390px;
  overflow: auto;
  padding: 24px;
  border: 1px solid #d5dce1;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #26333e;
  line-height: 1.65;
  white-space: pre-wrap;
}

.onboarding-intent {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  color: #35414c;
  line-height: 1.5;
}

.manager-onboarding-review {
  display: grid;
  gap: 14px;
}
.manager-onboarding-summary {
  padding: 14px;
  border: 1px solid #d7dde2;
  border-radius: 6px;
  background: #f7f9fa;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
}
.manager-onboarding-summary > span:last-child {
  color: #687581;
  font-size: 12px;
}
.manager-onboarding-item {
  padding: 14px 0;
  border-bottom: 1px solid #d7dde2;
  display: grid;
  gap: 10px;
}
.manager-onboarding-item > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.manager-onboarding-item > div:first-child span {
  color: #687581;
  font-size: 12px;
  text-transform: capitalize;
}
.manager-onboarding-item > p {
  margin: 0;
  color: #9a3931;
  font-size: 13px;
}
.manager-onboarding-item > div:last-child {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

@media (max-width: 760px) {
  .onboarding-step {
    gap: 22px;
  }
  .onboarding-step h1,
  .onboarding-step-heading h1 {
    font-size: 30px;
  }
  .onboarding-form-grid,
  .onboarding-assignment-summary {
    grid-template-columns: 1fr;
  }
  .onboarding-field.wide {
    grid-column: auto;
  }
}

/* Phase 4A employee directory */
.employees-page {
  box-sizing: border-box;
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  overflow: hidden;
  padding: 30px clamp(22px, 4vw, 54px) 48px;
  background: #f6f7f5;
}
.employees-header {
  display: flex;
  max-width: 1320px;
  width: 100%;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin: 0 auto 18px;
}
.employees-header h1 {
  margin: 0;
}
.employees-header p {
  margin: 6px 0 0;
}
.employees-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  max-width: 1320px;
  width: 100%;
  align-items: start;
  gap: 10px;
  margin: 0 auto 14px;
}
.catalog-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  width: 100%;
  margin: 0 0 16px;
}
.catalog-toolbar-status-row,
.catalog-toolbar-filter-row {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
}
.catalog-toolbar-status-row .employee-column-picker,
.catalog-toolbar-status-row .weekly-team-count {
  margin-left: auto;
}
.catalog-toolbar-filter-row .toolbar-filter-select {
  width: 200px;
  max-width: 220px;
  flex: 0 0 200px;
}
.catalog-toolbar .toolbar-search {
  display: flex;
  width: auto;
  min-width: 0;
  max-width: none;
  min-height: 36px;
  height: 36px;
  flex: 1 1 auto;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border: 1px solid var(--job-border, var(--wt-line, #cdd3d0));
  border-radius: 6px;
  background: var(--job-bg, var(--wt-surface, #fff));
  color: var(--job-muted, var(--wt-muted, #6b7571));
}
.catalog-toolbar .toolbar-search input {
  width: 100%;
  min-width: 0;
  height: 34px;
  padding: 0;
  border: 0;
  outline: 0;
  box-shadow: none;
  background: transparent;
  color: var(--job-text, var(--wt-text, #1d2525));
  font: inherit;
  font-size: 12px;
}
.catalog-toolbar .toolbar-search:focus-within {
  border-color: var(--job-accent, var(--wt-accent, #177a64));
  box-shadow: 0 0 0 2px rgb(23 122 100 / 12%);
}
.employee-toolbar-controls {
  display: flex;
  min-width: 0;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}
.employee-search {
  display: grid;
  width: 100%;
  height: 40px;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid #cdd3d0;
  border-radius: 6px;
  background: var(--theme-surface);
  color: #6b7571;
}
.employee-search:focus-within {
  border-color: var(--theme-focus);
  box-shadow: 0 0 0 2px rgb(23 122 100 / 12%);
}
.employee-search input {
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--theme-text-body);
}
.catalog-status-tabs,
.employee-status-tabs {
  display: flex;
  flex-wrap: wrap;
  min-width: 0;
  gap: 2px;
  overflow: visible;
  padding: 3px;
  border: 1px solid #d5dad7;
  border-radius: 6px;
  background: #ecefed;
}
.catalog-status-tabs button,
.employee-status-tabs button {
  display: inline-flex;
  height: 32px;
  flex: 0 1 auto;
  align-items: center;
  gap: 6px;
  border: 0;
  border-radius: 4px;
  padding: 0 11px;
  background: transparent;
  color: #5a6560;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
  line-height: 1;
  transition:
    background-color 120ms ease,
    color 120ms ease,
    box-shadow 120ms ease;
}
.catalog-toolbar .catalog-status-tabs button {
  font-family: inherit;
  font-size: 12px;
  font-style: normal;
  font-weight: 750;
  line-height: 1;
}
.catalog-status-tabs button.active,
.employee-status-tabs button.active {
  background: var(--theme-surface);
  color: #1e2925;
  box-shadow: 0 1px 2px rgb(22 35 30 / 12%);
}
.toolbar-filter-select {
  height: 36px;
  min-height: 36px;
  max-width: 220px;
  border: 1px solid #d5dad7;
  border-radius: 6px;
  padding: 7px 10px;
  background: var(--theme-surface);
  color: var(--theme-text-body);
  font: inherit;
  font-size: 12px;
}
.catalog-column-headings {
  min-height: 40px;
  height: 40px;
  padding: 0 14px;
  background: #f3f5f3;
  color: #68726e;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}
.catalog-column-headings > * {
  min-width: 0;
}
.catalog-sort-button {
  display: inline-flex;
  max-width: 100%;
  align-items: center;
  gap: 6px;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  line-height: 1;
  text-align: left;
  text-transform: inherit;
}
.catalog-sort-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.catalog-sort-icon {
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 120ms ease;
}
.catalog-sort-button:hover .catalog-sort-icon,
.catalog-sort-button:focus-visible .catalog-sort-icon {
  opacity: 1;
}
.employee-table th:hover .catalog-sort-icon,
.catalog-column-headings > *:hover .catalog-sort-icon,
.weekly-team-table th:hover .catalog-sort-icon {
  opacity: 1;
}
/* An empty catalog table keeps its heading row; the space under it is the
   soft ground (Settings → Documents, KARARLAR "Ekran kararları → Settings"). */
.catalog-table-empty {
  display: flex;
  min-height: 260px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 40px 20px;
  background: var(--theme-surface-soft);
  color: var(--theme-muted);
  text-align: center;
}
.job-catalog > .catalog-table-empty {
  border-radius: 0 0 7px 7px;
}
.catalog-table-empty-icon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 50%;
  background: var(--theme-accent-soft);
  color: var(--theme-accent);
}
.catalog-table-empty h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 15px;
  font-weight: 600;
}
.catalog-table-empty p {
  margin: 0;
  font-size: 13px;
}
.catalog-table-empty button {
  margin-top: 4px;
}
.catalog-sort-button:focus-visible {
  border-radius: 4px;
  outline: 2px solid var(--job-accent, #177a64);
  outline-offset: 2px;
}
.catalog-toolbar .toolbar-filter-select:focus-visible {
  border-color: var(--job-accent, var(--wt-accent, #177a64));
  box-shadow: inset 0 0 0 1px var(--job-accent, var(--wt-accent, #177a64));
  outline: 0;
}
@media (max-width: 720px) {
  .catalog-page-header {
    min-height: 0;
    align-items: flex-start;
    flex-direction: column;
    gap: 16px;
    padding: 24px 0 18px;
  }
  .catalog-page-header h1 {
    font-size: 32px;
  }
  .catalog-page-actions {
    width: 100%;
    justify-content: flex-start;
  }
  .catalog-toolbar-filter-row {
    align-items: stretch;
    flex-wrap: wrap;
  }
  .catalog-toolbar-filter-row .toolbar-filter-select,
  .catalog-toolbar-filter-row .toolbar-search {
    width: 100%;
    max-width: none;
    flex-basis: 100%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .catalog-status-tabs button,
  .employee-status-tabs button {
    transition: none;
  }
}
.employee-table-wrap {
  align-self: stretch;
  max-width: 1320px;
  width: 100%;
  min-height: 0;
  margin: 0 auto;
  overflow: auto;
  border: 1px solid #d7dcda;
  border-radius: 7px;
  background: var(--theme-surface);
}
.employee-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.employee-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  height: 40px;
  padding: 0 14px;
  border-bottom: 1px solid #dce1de;
  background: #f3f5f3;
  color: #68726e;
  font-size: 11px;
  font-weight: 800;
  text-align: left;
  text-transform: uppercase;
}
.employee-table tbody tr {
  height: 58px;
  border-bottom: 1px solid #e7eae8;
  cursor: pointer;
}
.employee-table tbody tr:hover,
.employee-table tbody tr:focus-visible {
  background: #f3f7f5;
  outline: 0;
}
.employee-table td {
  overflow: hidden;
  padding: 8px 14px;
  color: #46514d;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.employee-cell-identity,
.employee-cell-with-icon {
  display: flex;
  align-items: center;
  gap: 8px;
}
.employee-cell-identity > span:last-child {
  display: grid;
  min-width: 0;
}
.employee-table td strong {
  overflow: hidden;
  color: #202a27;
  text-overflow: ellipsis;
}
.employee-table td small {
  color: var(--theme-muted);
  font-size: 11px;
}
.employee-table-avatar,
.employee-avatar {
  display: grid;
  border: 1px solid #c6d4ce;
  border-radius: 50%;
  place-items: center;
  background: #dfe9e5;
  color: #31594e;
  font-weight: 800;
}
.employee-table-avatar {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  font-size: 12px;
}
.employee-column-picker {
  position: relative;
  flex: 0 0 auto;
}
.employee-column-trigger {
  width: 40px;
  height: 40px;
  padding: 0;
}
.employee-column-popover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 8px);
  right: 0;
  width: 278px;
  border: 1px solid #d2d8d5;
  border-radius: 7px;
  background: var(--theme-surface);
  box-shadow: 0 18px 42px rgb(19 31 27 / 16%);
}
.employee-column-popover header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 12px 8px;
  border-bottom: 1px solid #e3e8e5;
}
.employee-column-popover header strong {
  color: #202a27;
  font-size: 13px;
}
.employee-column-popover header span {
