  gap: 8px;
  padding: 8px;
  border-top: 1px solid #e3e8e5;
}
.employee-column-popover footer button {
  height: 32px;
  flex: 1;
}
.employee-state {
  display: inline-flex;
  width: fit-content;
  min-height: 24px;
  align-items: center;
  border-radius: 999px;
  padding: 3px 8px;
  background: #e8edeb;
  color: #53605b;
  font-size: 11px;
  font-weight: 800;
  text-transform: capitalize;
}
.state-active {
  background: #dcede5;
  color: #176048;
}
.state-invited,
.state-onboarding {
  background: #fff0cf;
  color: #805915;
}
.state-needs_attention {
  background: #f8deda;
  color: #923b2d;
}
.state-archived {
  background: #e7e9e8;
  color: #626966;
}
.employees-state,
.employees-empty {
  margin: 0;
  padding: 42px 24px;
  color: #6b7571;
  text-align: center;
}
.employees-empty {
  display: grid;
  min-height: 300px;
  place-content: center;
  justify-items: center;
}
.employees-empty strong {
  margin-top: 10px;
  color: #303b37;
}
.employees-empty p {
  margin: 5px 0 0;
  font-size: 13px;
}
.employees-state.error {
  color: #a23725;
}

.employee-drawer-layer {
  position: fixed;
  z-index: 110;
  inset: 0;
}
.employee-drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: rgb(17 24 21 / 42%);
  cursor: default;
  animation: employee-fade-in 160ms ease-out;
}
.employee-drawer {
  width: min(100%, 880px);
  height: 100dvh;
}
.employee-drawer {
  position: absolute;
  top: 0;
  right: 0;
  overflow: hidden;
  background: var(--theme-surface);
  box-shadow: -16px 0 42px rgb(18 28 24 / 18%);
  animation: employee-slide-in 210ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes employee-fade-in {
  from {
    opacity: 0;
  }
}
@keyframes employee-slide-in {
  from {
    transform: translateX(28px);
    opacity: 0.7;
  }
}
.employee-drawer-form {
  display: flex;
  height: 100%;
  flex-direction: column;
}
.employee-drawer-main {
  display: flex;
  min-height: 0;
  flex: 1;
}
.employee-summary-rail {
  display: flex;
  width: 236px;
  flex: 0 0 236px;
  flex-direction: column;
  border-right: 1px solid #dce1de;
  background: #f4f6f4;
}
.employee-identity {
  display: flex;
  min-height: 190px;
  align-items: center;
  flex-direction: column;
  padding: 28px 18px 20px;
  border-bottom: 1px solid #dce1de;
  text-align: center;
}
.employee-avatar {
  width: 58px;
  height: 58px;
  margin-bottom: 12px;
  font-size: 20px;
}
.employee-identity strong {
  max-width: 100%;
  overflow: hidden;
  margin-bottom: 4px;
  color: #202a27;
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.employee-identity > span:not(.employee-avatar, .employee-state) {
  margin-bottom: 10px;
  color: var(--theme-muted);
  font-size: 11px;
}
.employee-work-statuses {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin-top: 9px;
}
.employee-work-status {
  display: inline-flex;
  align-items: center;
  min-height: 23px;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 11px;
  font-weight: 800;
}
.employee-work-status.warning {
  background: #fff3cf;
  color: var(--theme-warning);
}
.employee-work-status.danger {
  background: #fde5e7;
  color: #9b2735;
}
.employee-section-links {
  padding: 12px 8px;
}
.employee-section-links button {
  display: flex;
  width: 100%;
  height: 38px;
  align-items: center;
  gap: 10px;
  border: 0;
  border-radius: 5px;
  padding: 0 10px;
  background: transparent;
  color: #59635f;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  text-align: left;
}
.employee-section-links button:hover {
  background: #e9eeeb;
}
.employee-section-links button.active {
  background: #dfe9e5;
  color: #145f4c;
}
.employee-section-links button[data-group-start="true"] {
  position: relative;
  margin-top: 13px;
}
.employee-section-links button[data-group-start="true"]::before {
  content: "";
  position: absolute;
  top: -7px;
  left: 0;
  right: 0;
  border-top: 1px solid #dce1de;
}
.employee-drawer-content {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}
/* The tab's title alone: no description line under it (EMP-001). */
.employee-section-header {
  display: flex;
  min-height: 56px;
  flex: 0 0 56px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 22px 8px 26px;
  border-bottom: 1px solid #dce1de;
}
.employee-section-header h2 {
  margin: 0;
  font-size: 19px;
  letter-spacing: 0;
}
.employee-section-scroll {
  min-height: 0;
