  padding: 24px 26px 36px;
  background: #fafbfa;
}
.employee-drawer-mobile-header {
  display: none;
}
.employee-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}
/* First, middle and last name on one row; the middle one is the short one. */
.employee-name-grid {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.7fr) minmax(0, 1fr);
  gap: inherit;
}
.employee-profile-sections,
.employee-access-sections {
  display: grid;
  gap: 28px;
}
.employee-profile-group,
.employee-access-group {
  display: grid;
  gap: 16px;
  padding-bottom: 28px;
  border-bottom: 1px solid #dfe4e1;
}
.employee-profile-group:last-child,
.employee-access-group:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}
.employee-profile-group > header,
.employee-access-group > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.employee-profile-group h3,
.employee-access-group h3 {
  margin: 0;
  color: #27312d;
  font-size: 14px;
}
.employee-profile-group header p,
.employee-access-group header p {
  margin: 4px 0 0;
  color: var(--theme-muted);
  font-size: 12px;
  line-height: 1.45;
}
.employee-profile-group > header > svg,
.employee-access-group > header > svg {
  flex: 0 0 auto;
  color: #78827e;
}
/* Every field that only shows a value looks the same, whatever locks it. */
.employee-field input[readonly] {
  background: #f2f5f3;
  color: #34403b;
  cursor: text;
}
.employee-readonly-field input[readonly]::placeholder {
  color: #8a938f;
}
.employee-address-grid .wide {
  grid-column: 1 / -1;
}
.employee-readonly-panel {
  grid-column: 1 / -1;
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid #d5dad7;
  border-radius: 6px;
  background: #f8faf9;
}
.employee-readonly-panel h3 {
  margin: 0;
  color: #27312d;
  font-size: 13px;
}
.employee-readonly-panel dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 18px;
  margin: 0;
}
.employee-readonly-panel div {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.employee-readonly-panel dt {
  color: #68726e;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}
.employee-readonly-panel dd {
  display: grid;
  gap: 2px;
  min-width: 0;
  margin: 0;
  color: #1e2824;
  font-size: 13px;
  overflow-wrap: anywhere;
}
.employee-readonly-panel dd span {
  color: #68726e;
}
.employee-form-stack {
  display: grid;
  gap: 20px;
}
.employee-field {
  display: grid;
  /* Fields on one row keep their inputs level when one grows a message. */
  align-content: start;
  gap: 7px;
  color: #424d48;
  font-size: 12px;
  font-weight: 750;
}
/* A button in a field's place sits on the inputs' line, not the labels'. */
.employee-field-action {
  align-content: end;
}
/* A state drawn inside the field, at its end (verified, invitation pending). */
.employee-field-control {
  position: relative;
  display: block;
}
.employee-field-control:has(.employee-field-mark) input {
  padding-right: 36px;
}
.employee-field-mark {
  position: absolute;
  top: 0;
  right: 11px;
  bottom: 0;
  display: flex;
  align-items: center;
}
.employee-field-mark.is-verified {
  color: var(--theme-success);
}
.employee-field-mark.is-pending {
  color: var(--theme-warning);
}
.employee-field input,
.employee-field textarea,
.employee-field select,
.employee-drawer-mobile-header select {
  width: 100%;
  border: 1px solid #cbd2ce;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #1e2824;
}
.employee-field input,
.employee-field select {
  height: 40px;
  padding: 0 11px;
}
.employee-field textarea {
  min-height: 100px;
  resize: vertical;
  padding: 10px 11px;
}
.employee-field input:disabled,
.employee-field textarea:disabled,
.employee-field select:disabled {
  background: #eff2f0;
  color: #727b77;
}
.employee-field small {
  color: var(--theme-muted);
  font-weight: 500;
}
.employee-field-helper {
  display: block;
  min-height: 15px;
}
.employee-toggle-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.employee-toggle-grid label {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  padding: 8px 10px;
  border: 1px solid #d5dad7;
  border-radius: 6px;
  background: var(--theme-surface);
  color: #424d48;
  font-size: 13px;
  font-weight: 750;
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    color 140ms ease;
}
.employee-work-mode.remote[data-selected="true"] {
  border-color: #d7a72c;
  background: #fff6da;
  color: #795000;
}
.employee-work-mode.off-schedule[data-selected="true"] {
  border-color: #da7f89;
  background: #fff0f1;
  color: #922b38;
}
.employee-work-mode.remote[data-selected="true"] input {
  accent-color: #b87900;
}
.employee-work-mode.off-schedule[data-selected="true"] input {
  accent-color: #b83c4d;
}
.employee-toggle-grid input {
  width: 16px;
  height: 16px;
  accent-color: #214f3f;
}
.employee-assignment-picker {
  margin: 0;
  border: 1px solid #d5dad7;
  border-radius: 6px;
  padding: 10px;
  background: var(--theme-surface);
}
.employee-assignment-picker legend {
  padding: 0 5px;
  color: #424d48;
  font-size: 12px;
  font-weight: 800;
}
.employee-assignment-picker > div {
  display: grid;
  min-height: 38px;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 4px 7px;
  border-bottom: 1px solid #edf0ee;
}
.employee-assignment-picker > div:last-of-type {
  border-bottom: 0;
}
/* The department a run of jobs sits under. */
.employee-assignment-group {
  display: block;
  padding: 14px 7px 4px;
  color: var(--theme-muted-strong);
  font-size: 12px;
  font-weight: 700;
}
