  padding-top: 4px;
}
.employee-assignment-picker label {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
}
.employee-assignment-picker label small {
  color: #8a928f;
}
.employee-assignment-picker .primary-choice {
  color: #68726e;
  font-size: 11px;
}
.employee-assignment-picker > p {
  margin: 8px;
  color: var(--theme-muted);
  font-size: 12px;
}
.employee-access-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  border-bottom: 1px solid #e0e4e2;
  color: #68726e;
  font-size: 13px;
}
.employee-access-status strong {
  color: #27312d;
}
.employee-access-state {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  border: 1px solid #d8deda;
  border-radius: 6px;
  padding: 13px 14px;
  background: var(--theme-surface-soft);
  color: #53605a;
}
.employee-access-state > svg {
  align-self: start;
  margin-top: 1px;
}
.employee-access-state strong,
.employee-access-empty strong {
  color: #27312d;
  font-size: 13px;
}
.employee-access-state p {
  margin: 3px 0 0;
  font-size: 12px;
  line-height: 1.45;
}
.employee-access-state.warning {
  border-color: #e7c86f;
  background: #fff8e3;
  color: #76581b;
}
.employee-access-state.danger {
  border-color: #e0a0a8;
  background: #fff1f2;
  color: #8e3440;
}
.employee-access-state.success {
  border-color: #8fc7b0;
  background: #edf8f3;
  color: #28634e;
}
.employee-access-empty {
  display: flex;
  min-height: 42px;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  color: var(--theme-muted);
  font-size: 12px;
}
.employee-access-empty span {
  flex: 1;
}
.employee-avatar-control {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}
.employee-avatar-control > img,
.employee-avatar-placeholder {
  width: 44px;
  height: 44px;
  border: 1px solid #d8deda;
  border-radius: 50%;
