  gap: 3px;
  min-width: 0;
}
.employee-avatar-control strong {
  color: #27312d;
  font-size: 13px;
}
.employee-avatar-control span,
.employee-avatar-control small {
  color: var(--theme-muted);
  font-size: 12px;
}
.employee-avatar-control small {
  color: #a23725;
}
.employee-access-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 0;
}
.employee-access-details > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.employee-access-details dt {
  color: var(--theme-muted);
  font-size: 11px;
  font-weight: 800;
}
.employee-access-details dd {
  min-width: 0;
  margin: 0;
  color: #27312d;
  font-size: 13px;
  font-weight: 700;
  overflow-wrap: anywhere;
}
.employee-linked-access-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 14px;
}
.employee-remove-access {
  color: #9b3442;
}
.employee-summary-panel {
  display: grid;
  min-height: 240px;
  place-content: center;
  justify-items: center;
  color: var(--theme-muted);
  text-align: center;
}
.employee-summary-panel strong {
  margin: 12px 0 5px;
  color: #2d3733;
  font-size: 15px;
}
.employee-summary-panel p {
  max-width: 360px;
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}
.employee-history {
  margin: 0;
  padding: 0;
  list-style: none;
}
.employee-history li {
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 10px;
  padding: 0 0 22px;
}
.employee-history li > span {
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 50%;
  background: #43806f;
  box-shadow: 0 0 0 4px #e2ece8;
}
.employee-history li div {
  display: grid;
  gap: 4px;
  font-size: 13px;
}
.employee-history small {
  color: var(--theme-muted);
}
.employee-panel-state {
  color: #68726e;
  text-align: center;
}
.employee-panel-state.error,
.employee-drawer-error {
  color: #a23725;
}
.employee-drawer-error {
  margin: 0;
  padding: 8px 24px;
  border-top: 1px solid #ecd1cb;
  background: #fff5f3;
  font-size: 12px;
}
.employee-drawer-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 20px;
  border-top: 1px solid #c9ded5;
  background: #edf7f2;
  color: #31594e;
  font-size: 12px;
  font-weight: 700;
}
.employee-drawer-notice a {
  color: #12654f;
}
.employee-pending-invite-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.employee-revoke-invite {
  width: fit-content;
}
.employee-drawer-footer {
  display: flex;
  min-height: 62px;
  flex: 0 0 62px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 20px;
  border-top: 1px solid #d8ddda;
  background: #f2f4f2;
}
.employee-drawer-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.employee-drawer-actions .nf-button {
  min-height: 38px;
  padding: 8px 13px;
  font-size: 13px;
}
.employee-create-role {
  width: min(210px, 32%);
  margin-left: auto;
}
.employee-create-role .employee-field {
  gap: 0;
}
.employee-create-role .employee-field > small {
  display: none;
}
.employee-create-role .employee-field select {
  height: 38px;
}
.employee-create-role .employee-field select[aria-invalid="true"] {
  border-color: var(--danger, #a13f30);
  box-shadow: 0 0 0 1px var(--danger, #a13f30);
}
.employee-invite-role-invalid-0 select {
  animation: employee-invite-role-pulse-a 520ms ease;
}
.employee-invite-role-invalid-1 select {
  animation: employee-invite-role-pulse-b 520ms ease;
}
@keyframes employee-invite-role-pulse-a {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-2px);
  }
  40% {
    transform: translateX(2px);
  }
  60% {
    transform: translateX(-1px);
  }
  80% {
    transform: translateX(1px);
  }
}
@keyframes employee-invite-role-pulse-b {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-2px);
  }
  40% {
    transform: translateX(2px);
  }
  60% {
    transform: translateX(-1px);
  }
  80% {
    transform: translateX(1px);
  }
}

.employee-drawer-create .employee-identity {
