}
.employee-drawer-create .employee-email-field {
  grid-column: 1 / -1;
}
.employee-drawer-create .employee-field:has(select[aria-label="Invite role"]) {
  grid-column: 1 / -1;
}
.employee-drawer-create .employee-field input,
.employee-drawer-create .employee-field select {
  min-height: 40px;
  font-size: 14px;
}
.employee-field-requirement {
  margin-left: 8px;
  font-size: 12px;
  font-weight: 400;
  color: var(--text-muted, #68746e);
}
.employee-field-error {
  color: var(--danger, #a13f30);
}
.employee-form-section-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}
.employee-create-invite-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--border, #dce1de);
}
.employee-create-invite-summary > div {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: 4px;
  overflow-wrap: anywhere;
}
.employee-create-invite-summary strong {
  font-size: 14px;
}
.employee-create-invite-summary span {
  font-size: 12px;
}
.employee-drawer-create .employee-assignment-picker label > span {
  overflow-wrap: anywhere;
  min-width: 0;
}
.employee-drawer-create .nf-button.secondary-button:disabled {
  opacity: 0.5;
}
.employee-drawer-create .employee-section-links button:disabled {
  opacity: 0.45;
  cursor: default;
}
.employee-create-steps {
  display: flex;
  flex: 1;
  gap: 8px;
}
.employee-create-steps button {
  min-height: 44px;
  padding: 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: inherit;
  font: inherit;
}
.employee-create-steps button[aria-current="step"] {
  border-bottom-color: currentColor;
  font-weight: 700;
}
.employee-create-steps button:disabled {
  opacity: 0.45;
}
@media (max-width: 640px) {
  .employee-drawer-create .employee-form-grid,
  .employee-name-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .employee-drawer-create .employee-field input,
  .employee-drawer-create .employee-field select {
    min-height: 44px;
    font-size: 16px;
  }
  .employee-drawer-create .employee-section-scroll {
    padding: 16px;
  }
  .employee-drawer-create .employee-toggle-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .employee-create-role {
    order: 3;
    width: 100%;
    margin-left: 0;
  }
  .employee-access-state {
    grid-template-columns: auto minmax(0, 1fr);
  }
  .employee-access-state .nf-button {
    grid-column: 1 / -1;
    width: 100%;
  }
  .employee-avatar-control {
    grid-template-columns: 44px minmax(0, 1fr);
  }
  .employee-avatar-control .nf-button {
    grid-column: 1 / -1;
    width: 100%;
  }
  .employee-access-empty {
    align-items: flex-start;
    flex-direction: column;
  }
  .employee-access-details {
    grid-template-columns: minmax(0, 1fr);
  }
  .employee-linked-access-controls {
    grid-template-columns: minmax(0, 1fr);
  }
  .employee-remove-access {
    width: 100%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .employee-drawer-create {
    animation: none;
  }
}
.employee-lifecycle-button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 36px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #a13f30;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
}
.employee-lifecycle-button:hover {
  background: #f9e7e3;
}
.employee-lifecycle-button.restore {
  color: #176048;
}
.employee-lifecycle-button.restore:hover {
  background: #dcede5;
}
.employee-termination-layer {
  position: fixed;
  z-index: 90;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
}
.employee-termination-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: rgba(20, 27, 24, 0.46);
  cursor: default;
}
.employee-termination-dialog {
  position: relative;
  width: min(460px, 100%);
  max-height: calc(100vh - 40px);
  overflow: auto;
  border: 1px solid #d5dbd8;
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 22px 60px rgba(15, 25, 20, 0.22);
}
.employee-termination-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px 14px;
  border-bottom: 1px solid #e1e5e3;
}
.employee-termination-dialog h2 {
  margin: 0;
  color: #26312c;
  font-size: 18px;
}
.employee-termination-dialog header p {
  margin: 4px 0 0;
  color: #68726e;
  font-size: 13px;
}
.employee-termination-dialog form {
  display: grid;
  gap: 14px;
  padding: 18px 20px 20px;
}
.employee-termination-dialog form > label {
  display: grid;
  gap: 6px;
  color: #4f5a55;
  font-size: 12px;
  font-weight: 700;
}
.employee-termination-dialog input,
.employee-termination-dialog select,
.employee-termination-dialog textarea {
  width: 100%;
  min-height: 40px;
  border: 1px solid #cbd2ce;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #26312c;
  font: inherit;
  font-weight: 500;
  padding: 8px 10px;
}
.employee-termination-dialog textarea {
  min-height: 76px;
  resize: vertical;
}
.employee-termination-warning {
  margin: 0;
  padding: 10px 12px;
  border-left: 3px solid #ba5a45;
  background: #fff4f1;
  color: #704035;
  font-size: 12px;
  line-height: 1.45;
}
.employee-termination-dialog form > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 2px;
}
.employee-dirty {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-right: 4px;
  color: #757f7b;
  font-size: 11px;
  font-weight: 700;
}
.employee-dirty i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #d38a2f;
}

@media (max-width: 900px) {
  .employees-toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .employee-search,
  .employee-column-picker .secondary-button.compact {
    width: 100%;
  }
  .employee-column-picker {
    width: 100%;
  }
  .employee-column-popover {
    right: auto;
    left: 0;
    width: min(100%, 320px);
  }
  .employee-table-wrap {
    overflow-x: auto;
  }
  .employee-table {
    min-width: 780px;
  }
}
@media (max-width: 640px) {
  .employees-page {
    padding: 20px 14px 36px;
  }
  .employees-header {
    align-items: stretch;
    flex-direction: column;
  }
  .employees-header .nf-button {
    width: 100%;
  }
  .employee-summary-rail,
  .employee-section-header {
    display: none;
  }
  .employee-drawer-mobile-header {
    display: grid;
    height: 58px;
    grid-template-columns: minmax(0, 1fr) 38px;
    align-items: center;
    gap: 10px;
    padding: 9px 12px;
    border-bottom: 1px solid #dce1de;
  }
  .employee-drawer-mobile-header select {
    height: 38px;
    padding: 0 10px;
  }
  .employee-section-scroll {
    padding: 20px 16px 28px;
  }
  .employee-form-grid {
    grid-template-columns: 1fr;
  }
  .employee-drawer-footer {
    min-height: 68px;
    padding: 9px 12px;
  }
  .employee-drawer-footer > div:first-child {
    display: none;
  }
  .employee-drawer-actions {
    width: 100%;
    justify-content: flex-end;
  }
  .employee-dirty {
    display: none;
  }
  .employee-drawer-actions .nf-button {
    flex: 1;
  }
  .employee-termination-layer {
    align-items: end;
    padding: 0;
  }
  .employee-termination-dialog {
    width: 100%;
    max-height: calc(100vh - 24px);
    border-radius: 8px 8px 0 0;
  }
}

.icon-button.danger {
  color: #a43f35;
}

* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-width: 320px;
}
button,
input,
select {
  font: inherit;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
h1,
h2,
p {
  margin-top: 0;
}
.eyebrow {
  margin-bottom: 10px;
  color: #9b3e28;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0;
}
.muted {
  color: #66706c;
  line-height: 1.55;
}
.text-button {
  display: inline-block;
  margin-top: 16px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--theme-accent-strong);
  font: inherit;
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}
/* The sign-in form in the prebiz stage; it carries its own spacing there. */
.sign-in-form {
  display: grid;
  gap: 16px;
  margin-top: 26px;
  max-width: 420px;
}
.form-error {
  margin: 0 0 14px;
  color: #a23725;
  font-size: 13px;
}
.auth-loading {
  min-height: 100vh;
  background: var(--theme-page);
}
.nf-button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 6px;
  padding: 10px 16px;
  background: var(--theme-accent);
  color: #fff;
  cursor: pointer;
  font-weight: 750;
}
.nf-button:hover {
  background: var(--theme-accent-strong);
}
.nf-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
/* After .nf-button on purpose: <Button className="secondary-button"> is a
   dismiss button (Cancel, Discard, Back) and must not come out green. */
.secondary-button {
  border: 1px solid var(--theme-muted);
  background: var(--theme-surface);
  color: var(--theme-accent-deep);
}
.secondary-button:hover {
  background: var(--theme-surface-muted);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.nf-button:focus-visible,
button:focus-visible,
a:focus-visible,
select:focus-visible {
  outline: 2px solid var(--theme-focus);
  outline-offset: 2px;
}
:root[data-escape-focus="true"] :focus {
  outline: none !important;
}
:root[data-escape-focus="true"] :is(input, select, textarea):focus,
:root[data-escape-focus="true"] .employee-table tbody tr:focus-visible {
  box-shadow: none !important;
}
:root[data-escape-focus="true"]
  :is(.employee-search, .job-color-control):focus-within {
  outline: none !important;
  box-shadow: none !important;
}
.app-shell {
  display: grid;
  grid-template-columns: 288px minmax(0, 1fr);
  height: 100dvh;
  overflow: hidden;
}
.app-shell[data-sidebar-collapsed="true"] {
  grid-template-columns: 64px minmax(0, 1fr);
}
.app-sidebar {
  display: flex;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border-right: 1px solid #d9ddda;
  background: var(--theme-surface);
  transition: width 180ms ease;
}
.app-shell[data-sidebar-collapsed="true"] .app-sidebar {
  overflow: visible;
}
.sidebar-tools {
  display: flex;
  height: 52px;
  flex: 0 0 52px;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
}
.organization-context-slot {
  min-width: 0;
}
.workspace-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
}

/* The workspace name becomes a control only when there is a second workspace
   or an invitation waiting; with one workspace it stays the plain name above. */
.workspace-switcher {
  position: relative;
  flex-grow: 1;
}
.workspace-switcher-trigger {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 36px;
  padding: 0 8px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--theme-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.workspace-switcher-trigger:hover,
.workspace-switcher-trigger[aria-expanded="true"] {
  border-color: var(--theme-border);
  background: var(--theme-surface);
}
.workspace-switcher-trigger .workspace-name {
  flex-grow: 1;
}
/* A number that means "you owe someone an answer", not "something is new". */
.workspace-switcher-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--theme-danger);
  color: var(--theme-on-accent);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.workspace-switcher-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
}
.workspace-switcher-mark .workspace-switcher-count {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 9px;
  height: 9px;
  padding: 0;
}
.workspace-switcher-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 40;
  width: 264px;
  padding: 8px;
  border: 1px solid var(--theme-border);
  border-radius: 10px;
  background: var(--theme-surface);
  box-shadow: 0 16px 40px rgb(22 35 30 / 14%);
}
.workspace-switcher-label {
  margin: 6px 0 4px;
  padding: 0 8px;
  color: var(--theme-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.workspace-switcher-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--theme-text);
  font: inherit;
  text-align: left;
}
button.workspace-switcher-item {
  cursor: pointer;
}
button.workspace-switcher-item:hover:not(:disabled) {
  background: var(--theme-surface-muted);
}
.workspace-switcher-item.is-current {
  background: var(--theme-selected);
}
.workspace-switcher-text {
  display: grid;
  gap: 1px;
  flex-grow: 1;
  min-width: 0;
}
.workspace-switcher-text strong {
  overflow: hidden;
  font-size: 13.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-switcher-text span {
  color: var(--theme-muted);
  font-size: 11.5px;
}
/* The menu is narrow, so its one action is sized for the row it sits in. */
.workspace-switcher-answer.pb-btn.pb-btn {
  min-height: 30px;
  padding: 0 11px;
  font-size: 12.5px;
}
.workspace-switcher-all {
  display: block;
  margin-top: 6px;
  padding: 9px 8px 4px;
  border-top: 1px solid var(--theme-border);
  color: var(--theme-accent);
  font-size: 12.5px;
  font-weight: 700;
  text-decoration: none;
}
.icon-button {
  display: inline-grid;
  width: 38px;
  height: 36px;
  flex: 0 0 38px;
  place-items: center;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #4b5551;
  cursor: pointer;
}
.icon-button:hover,
.nav-item:hover {
  background: var(--theme-surface-muted);
}
.mini-calendar {
  width: 264px;
  max-width: 100%;
  padding: 12px 0 0;
}
.calendar-month {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 28px;
  align-items: center;
  margin-bottom: 6px;
  text-align: center;
  font-size: 13.5px;
  line-height: 1.2;
}
.calendar-month strong span {
  color: #68736e;
  font-weight: 700;
}
.calendar-title-button {
  border: 0;
  border-radius: 4px;
  padding: 2px 4px;
  background: transparent;
  color: #29322f;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
}
.calendar-title-button.muted {
  color: #68736e;
  font-weight: 700;
}
.calendar-title-button:hover {
  background: #edf1ef;
}
.calendar-arrow {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #66706c;
  cursor: pointer;
}
.calendar-arrow:hover {
  background: #edf1ef;
}
.calendar-grid {
  display: grid;
  grid-template-columns: 20px repeat(7, 1fr);
  gap: 2px 0;
}
.calendar-grid.days-only {
  grid-template-columns: repeat(7, 1fr);
}
.calendar-grid .weekday {
  display: grid;
  height: 24px;
  place-items: center;
  color: #5f6a65;
  font-size: 10.5px;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1;
}
.calendar-row {
  display: contents;
}
.week-jump,
.calendar-day {
  position: relative;
  display: grid;
  height: 28px;
  place-items: center;
  border: 0;
  background: transparent;
  color: #35403c;
  cursor: pointer;
}
.week-jump {
  width: 20px;
  border-radius: 5px;
}
.week-jump span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #26302c;
  transition: transform 120ms ease;
}
.week-jump:hover {
  background: #eef2f0;
}
.week-jump:hover span {
  transform: scale(1.35);
}
.week-jump.active span {
  width: 8px;
  height: 8px;
  background: #b36a20;
}
.calendar-day {
  min-width: 0;
  border-radius: 0;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}
.calendar-day:hover {
  z-index: 2;
  background: #edf3f0;
}
.calendar-day.outside {
  color: #87918d;
  font-weight: 650;
}
.calendar-day.in-week {
  background: #f4d7a7;
  color: #272d2b;
}
.calendar-day.selected {
  z-index: 3;
  background: #d79d54;
  color: #17201d;
  box-shadow: inset 0 0 0 1px #28312e;
  font-weight: 800;
}
.calendar-picker-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  padding: 2px 0;
}
.calendar-picker-cell {
  display: grid;
  height: 34px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: #35403c;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
}
.calendar-picker-cell:hover {
  background: #edf3f0;
}
.calendar-picker-cell[aria-selected="true"] {
  border-color: #28312e;
  background: #d79d54;
  color: #17201d;
}
.today-indicator,
.date-marker {
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 12px;
  height: 2px;
  border-radius: 2px;
  background: #1d2525;
  transform: translateX(-50%);
}
.date-marker.important {
  background: #2d78a0;
}
.date-marker.closed {
  background: #b64e38;
}
.today-indicator + .date-marker {
  bottom: 5px;
}
.today-button {
  width: 100%;
  height: 28px;
  margin-top: 7px;
  border: 1px solid #d4d9d6;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #46514d;
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}
.today-button:hover {
  background: var(--theme-surface-muted);
}
.sidebar-nav {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 10px 8px;
}
.app-shell[data-sidebar-collapsed="true"] .sidebar-nav {
  overflow: visible;
}
.sidebar-nav-section-start {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid #e1e5e2;
}
.sidebar-nav-entry {
  position: relative;
}
.nav-item {
  display: flex;
  width: 100%;
  min-height: 40px;
  align-items: center;
  gap: 10px;
  margin-bottom: 4px;
  padding: 0 11px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #45504c;
  cursor: pointer;
  font-size: 14px;
  font-weight: 650;
  text-decoration: none;
  white-space: nowrap;
}
.nav-icon-frame {
  position: relative;
  z-index: 10;
  display: inline-flex;
  flex: 0 0 auto;
}
.nav-item svg {
  flex: 0 0 auto;
}
.nav-item.active {
  background: #e9f2ee;
  color: var(--theme-accent-strong);
}
.nav-item-has-children {
  padding-right: 36px;
}
.nav-group-toggle {
  position: absolute;
  top: 4px;
  right: 6px;
  display: inline-flex;
  width: 32px;
  height: 32px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #5f6965;
  cursor: pointer;
}
.nav-group-toggle:hover,
.nav-group-toggle:focus-visible {
