.schedule-publish-action[data-schedule-top-action-trigger="publish"][data-publication-tone="partial"],
.schedule-published-indicator[data-schedule-top-action-trigger="published"][data-publication-tone="partial"] {
  border-color: var(--theme-published-partial);
