  justify-content: center;
  gap: 6px;
}
.schedule-edit-banner,
.schedule-operation-error {
  display: flex;
  min-height: 42px;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border: 1px solid #bfd3ca;
  border-bottom: 0;
  background: var(--theme-selected);
}
.schedule-edit-banner {
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.schedule-edit-banner button,
.schedule-operation-error button {
  min-height: 30px;
