  display: inline-flex;
}
.schedule-save-menu-anchor > span {
  display: inline-flex;
}
.schedule-save-draft-menu {
  position: absolute;
  z-index: 95;
  top: calc(100% + 8px);
  right: 0;
  display: grid;
  width: min(380px, calc(100vw - 24px));
  max-height: min(620px, calc(100vh - 84px));
  overflow: hidden auto;
  color: var(--theme-text);
}
.schedule-save-draft-menu label {
  display: grid;
  gap: 6px;
