  min-height: 34px;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  padding: 6px 10px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
}
.schedule-save-menu-warning,
.schedule-save-menu-danger,
.schedule-save-menu-muted,
.schedule-save-menu-empty {
