/* Save and Save As are secondary actions (neutral text); the green one is
   Save and publish, on the right. */
.schedule-save-menu-actions {
  display: grid;
  grid-template-columns: auto auto 1fr;
  gap: 6px;
  padding: 12px 14px;
}
.schedule-save-menu-actions button {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  padding: 0 10px;
  background: var(--theme-surface);
  color: var(--theme-text);
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 500;
}
.schedule-save-menu-actions button:hover:not(:disabled) {
  background: var(--theme-surface-muted);
}
.schedule-save-menu-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.schedule-save-menu-actions .schedule-save-menu-publish-action {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
