  display: grid;
  grid-template-columns: minmax(0, 1fr) 26px;
  align-items: center;
  gap: 8px;
  margin: 0 6px;
  border-radius: 6px;
  padding: 5px 4px 5px 8px;
}
.schedule-save-menu-row[data-published="true"] {
  grid-template-columns: auto minmax(0, 1fr);
}
.schedule-save-menu-row:hover {
  background: var(--theme-surface-muted);
}
.schedule-save-menu-row span {
  display: grid;
  min-width: 0;
  gap: 2px;
}
.schedule-save-menu-row strong,
.schedule-save-menu-row small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.schedule-save-menu-row strong {
  color: var(--theme-text);
  font-size: 13px;
  font-weight: 500;
}
.schedule-save-menu-row small {
  color: var(--theme-muted);
  font-size: 12px;
}
.schedule-save-menu-row button {
  display: inline-flex;
  width: 26px;
  height: 26px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 5px;
  padding: 0;
  background: transparent;
  color: var(--theme-muted);
  cursor: pointer;
  opacity: 0;
}
.schedule-save-menu-row:is(:hover, :focus-within) button,
.schedule-save-menu-row button[data-confirming="true"] {
  opacity: 1;
}
@media (hover: none) {
  .schedule-save-menu-row button {
    opacity: 1;
  }
}
.schedule-save-menu-row button:hover {
  background: var(--theme-border-subtle);
  color: var(--theme-text);
}
.schedule-save-menu-row button[data-confirming="true"] {
  background: var(--theme-selected);
  color: var(--theme-accent);
}
.schedule-save-menu-published-chip {
  display: inline-flex !important;
  min-width: auto !important;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  color: var(--theme-success);
  font-size: 12px;
  font-weight: 500;
}
.schedule-save-menu-published-chip svg {
  width: 12px;
  height: 12px;
}
.schedule-save-menu-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 6px;
