/* On a phone the action buttons fill a row of their own; a menu anchored to
   its button's right edge ran off the left of the screen. Anchor it to the
   whole row instead. */
@media (max-width: 720px) {
  .schedule-draft-menu,
  .schedule-save-menu-anchor {
    position: static;
  }
  .schedule-draft-menu-panel,
  .schedule-save-draft-menu {
    left: 0;
    right: 0;
    width: auto;
  }
}
.schedule-operation-error {
