  transform: translateX(-50%);
  border: 1px solid #9ed7c3;
  border-radius: 6px;
  padding: 8px 12px;
  background: #e7f7ef;
  box-shadow: 0 10px 24px rgba(18, 33, 28, 0.16);
  color: #13513f;
  font-size: 12px;
  font-weight: 800;
  pointer-events: none;
}
.schedule-paste-status[data-blocked="true"] {
  border-color: #e0aaa3;
  background: #faebe8;
  color: #8d3228;
}
.schedule-grid-scroll {
  --schedule-location-header-height: 88px;
  --schedule-day-header-height: 49px;
  --schedule-filler-height: 0px;
  --schedule-filler-row-guide-height: 94px;
  --schedule-total-bottom-offset: 0px;
  --schedule-unassigned-sticky-top: calc(
    var(--schedule-location-header-height) + var(--schedule-day-header-height)
  );
  position: relative;
  width: 100%;
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
  scrollbar-width: none;
  border: 1px solid #cfd6d2;
  border-radius: 0;
  background: var(--theme-surface);
}
.schedule-grid-scroll::-webkit-scrollbar {
  display: none;
}
.schedule-horizontal-nav {
  position: sticky;
  z-index: 70;
  right: 0;
  bottom: 0;
  left: 0;
  height: 17px;
  border-top: 1px solid #cbd5e1;
  background: #f1f1f1;
}
.schedule-horizontal-nav-track {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #f1f1f1;
  cursor: default;
  outline: none;
  touch-action: none;
  user-select: none;
}
.schedule-horizontal-nav-rail {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 1px;
  transform: translateY(-50%);
  background: #d7d7d7;
}
.schedule-horizontal-nav-thumb {
  position: absolute;
  top: 1px;
  height: 15px;
  border: 1px solid #8d8d8d;
  background: #c1c1c1;
  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.55);
  cursor: default;
  touch-action: none;
  transition: background 0.12s ease;
  user-select: none;
}
.schedule-horizontal-nav-thumb:hover {
  background: #a8a8a8;
}
.schedule-horizontal-nav-thumb:active {
  background: #8f8f8f;
}
.schedule-grid-exact {
  position: relative;
  display: grid;
  width: max-content;
  min-width: 100%;
  align-items: stretch;
}
.schedule-grid-exact[data-schedule-fit-visible-columns="true"] {
  width: 100%;
}
.schedule-grid-exact > * {
  min-width: 0;
  border-right: var(--schedule-grid-line-width) solid
    var(--schedule-grid-line-color);
  border-bottom: var(--schedule-grid-line-width) solid
    var(--schedule-grid-line-color);
}
.schedule-grid-exact > [data-location-boundary="start"] {
  box-shadow: inset var(--schedule-location-boundary-width) 0 #8fa098;
}
.schedule-grid-sticky {
  position: sticky;
  left: 0;
  z-index: 2;
  /* Drawn inside the column so Monday's cards keep their 1px of air. */
  box-shadow: inset -1px 0 #cfd7d3;
}
.schedule-grid-exact > [data-schedule-pinned-cell="employee"] {
