  padding: var(--schedule-cell-edit-inset);
}
.schedule-cell[data-editing="false"] {
  padding: var(--schedule-cell-preview-inset);
  padding-bottom: var(--schedule-unassigned-line-width);
}
/* The location stripe sits inside the cell; cards start after it. */
.schedule-cell[data-editing="true"][data-location-boundary="start"] {
  padding-left: calc(
    var(--schedule-location-boundary-width) + var(--schedule-cell-edit-inset)
  );
}
.schedule-cell[data-editing="false"][data-location-boundary="start"] {
  padding-left: calc(
    var(--schedule-location-boundary-width) +
      var(--schedule-cell-preview-inset)
  );
}
.schedule-cell[data-editing="false"] > .schedule-shift-badge {
  padding-top: 4px;
  padding-bottom: 4px;
}
.schedule-cell[data-editing="false"] > .schedule-shift-badge:not(:last-child) {
  margin-bottom: var(--schedule-badge-preview-gap);
}
.schedule-cell[data-editing="true"] > .schedule-shift-badge:not(:last-child) {
  margin-bottom: var(--schedule-badge-edit-gap);
}
.schedule-cell[data-editing="false"]
  > .schedule-shift-badge[data-selected="true"],
.schedule-cell[data-editing="false"]
  > .schedule-shift-badge[data-current="true"] {
  z-index: 0;
}
.schedule-cell[data-editing="true"]:hover {
  background: #fffaf0;
}
.schedule-cell.schedule-unassigned-row-cell[data-editing="true"]:hover {
  background: var(--schedule-unassigned-row-background);
}
.schedule-cell[data-drop-target="true"] {
  background: #e8f3ef;
  outline: 2px solid #2b7e67;
  outline-offset: -2px;
}
/* A dragged shift's target cell (KARARLAR Schedule, 2026-10-06): green takes
   it, amber is a warning the drop asks about (availability orange), red is a
   real block. Each outline is at least 3:1 on its own fill. */
.schedule-cell[data-drop-status="allowed"] {
  background: var(--theme-success-soft);
  outline: 2px solid var(--theme-accent);
  outline-offset: -2px;
}
.schedule-cell[data-drop-status="blocked"] {
  background: var(--theme-danger-soft);
  outline: 2px solid var(--theme-danger);
  outline-offset: -2px;
}
.schedule-cell[data-drop-status="warning"] {
  background: var(--theme-warning-soft);
  outline: 2px solid var(--theme-availability);
  outline-offset: -2px;
}
.schedule-shift-drag-preview[data-status="warning"]
  .schedule-drag-blocked-reason {
  background: #fff4da;
  color: #754806;
  border-color: #c57b08;
}
.schedule-drop-review-status {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 120;
  padding: 8px 12px;
  background: var(--surface, #fff);
  color: var(--text, #17231e);
  border: 1px solid var(--border-color, #ccd4cf);
  border-radius: 4px;
}
.schedule-cell[data-paste-armed="true"] {
  cursor: copy;
  background: #f2faf6;
  box-shadow: inset 0 0 0 1px #8fcab8;
}
.schedule-cell[data-paste-armed="true"]:hover {
  background: #e3f5ec;
  box-shadow: inset 0 0 0 2px #2b7e67;
}
.schedule-cell[data-shift-editor-active-cell="true"] {
  background: #fff7e5;
  box-shadow:
    inset 0 0 0 2px #d99221,
    inset 0 0 0 999px rgba(217, 146, 33, 0.08);
}
.schedule-cell.schedule-unassigned-row-cell[data-shift-editor-active-cell="true"] {
  background: var(--schedule-unassigned-row-background);
}
.schedule-cell[data-shift-editor-active-cell="true"]::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(217, 146, 33, 0.55);
  border-radius: 5px;
}
.schedule-cell-add-action {
  z-index: 1;
  display: inline-flex;
  box-sizing: border-box;
  min-width: 32px;
  min-height: 28px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px dashed #d7bd86;
  border-radius: var(--schedule-badge-radius);
  background: rgba(255, 250, 240, 0.72);
  color: #8a5d10;
  cursor: pointer;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transition:
    background-color var(--schedule-motion-fast) ease,
    border-color var(--schedule-motion-fast) ease,
    color var(--schedule-motion-fast) ease,
    opacity var(--schedule-motion-fast) ease;
}
.schedule-cell[data-editing="true"]:hover > .schedule-cell-add-action,
.schedule-cell[data-editing="true"]:focus-within > .schedule-cell-add-action {
  opacity: 1;
  pointer-events: auto;
}
.schedule-cell-add {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-height: 100%;
  padding: 0 8px;
}
.schedule-cell-add-action:hover,
.schedule-cell-add-action[data-add-shift-active="true"] {
  border-color: #c88c2a;
  background: rgba(226, 173, 79, 0.11);
  color: #70470a;
  opacity: 1;
}
.schedule-cell-add-action:focus-visible {
  border-color: var(--schedule-focus-ring-color);
  outline: 2px solid var(--schedule-focus-ring-color);
  outline-offset: 1px;
  opacity: 1;
  pointer-events: auto;
}
.schedule-cell-add-another {
  position: relative;
  width: 100%;
  height: auto;
  min-height: var(--schedule-add-shift-lane-height);
  flex: 1 1 var(--schedule-add-shift-lane-height);
  padding: 0 8px;
}
.schedule-cell > .schedule-shift-badge {
  z-index: 1;
}
.schedule-cell-paste {
  position: relative;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  min-height: 24px;
  border: 1px dashed #aabbb4;
  border-radius: 3px;
  background: transparent;
  color: #60716a;
  font-size: 9px;
}
.schedule-cell[data-closed="true"] {
  background-color: #fbf1ef;
  background-image: repeating-linear-gradient(
    135deg,
    transparent 0 7px,
    rgba(155, 75, 60, 0.07) 7px 9px
  );
}
/* A marked day (KARARLAR Schedule, 2026-10-06): time off is a flat red cell
   that says "Time off"; an unavailable day draws nothing but its orange "!". */
.schedule-cell[data-availability-kind="time_off"] {
  background-color: var(--theme-time-off-soft);
}
.schedule-cell[data-availability-kind="time_off"]:not(:has(.schedule-shift-badge))::before {
  content: "Time off";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--theme-danger-text);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  pointer-events: none;
}
.schedule-availability-tip-dot {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 15px;
  height: 15px;
  border-radius: 999px;
  background: var(--theme-availability);
  color: var(--theme-on-accent);
  font-size: 10px;
  font-weight: 800;
}
.schedule-availability-tip-dot[data-kind="time_off"] {
  background: var(--theme-time-off);
}
.schedule-cell[data-overlap="true"] {
  box-shadow: inset 2px 0 0 #c45b43;
}
.schedule-shift-badge {
  --schedule-shift-selection-color: color-mix(
    in srgb,
    var(--shift-color) 58%,
    #173e34
  );
  position: relative;
  display: flex;
  box-sizing: border-box;
  width: 100%;
  height: var(--schedule-row-badge-height, 58px);
  min-height: var(--schedule-row-badge-height, 58px);
  flex-direction: column;
  justify-content: center;
  margin-bottom: 0;
  appearance: none;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--shift-color) 65%, #26332e);
  border-radius: var(--schedule-badge-radius);
  padding: 6px 8px;
  background: color-mix(in srgb, var(--shift-color) 13%, var(--theme-surface));
  color: #26312d;
  font: inherit;
  text-align: left;
  transform: translateY(0);
  transition:
    border-color var(--schedule-motion-state) ease,
    box-shadow var(--schedule-motion-state) ease,
    background var(--schedule-motion-state) ease;
}
.schedule-badge-width-measurer {
  position: absolute;
  left: 0;
  top: 0;
  z-index: -1;
  height: 0;
  max-width: none;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}
.schedule-badge-width-measure {
  display: inline-flex;
  width: max-content;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  border: 1px solid color-mix(in srgb, var(--shift-color) 65%, #26332e);
  border-radius: var(--schedule-badge-radius);
  padding: 6px 10px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.3;
  white-space: nowrap;
}
.schedule-badge-width-measure[data-has-markers="true"] {
  padding-right: 50px;
}
.schedule-badge-width-measure[data-has-stack="true"] {
  padding-right: 48px;
}
.schedule-badge-width-measure[data-has-markers="true"][data-has-stack="true"] {
  padding-right: 78px;
}
.schedule-badge-width-measure > span {
  display: block;
  width: max-content;
  margin: 0;
  white-space: nowrap;
}
.schedule-badge-width-measure > span:first-child {
  font-size: 12px;
  font-weight: 750;
  letter-spacing: -0.01em;
  line-height: 1.25;
}
.schedule-shift-badge[data-dragging="true"],
.schedule-shift-badge[data-shift-badge="true"] {
  cursor: grab;
}
.schedule-cell[data-editing="true"]
  > .schedule-shift-badge[data-shift-badge="true"]:not(
    [data-ghost="true"]
  ):hover {
  border-color: color-mix(in srgb, var(--shift-color) 78%, #26332e);
  background: color-mix(in srgb, var(--shift-color) 17%, var(--theme-surface));
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--shift-color) 24%, transparent);
}
.schedule-shift-badge:focus-visible {
  outline: 2px solid var(--schedule-focus-ring-color);
  outline-offset: 1px;
}
/* A ghost is the real card switched off: same frame and layout, one dead gray
   with a fine sparse hatch whatever its type, job or place. No opacity, so the
   text keeps AA (5.11:1 on the hatch line). */
.schedule-shift-badge[data-ghost="true"] {
  pointer-events: none;
  border-color: var(--schedule-ghost-edge);
  background: repeating-linear-gradient(
    135deg,
    var(--theme-border-subtle) 0 1px,
    var(--theme-surface-muted) 1px 5px
  );
  box-shadow: none;
}
.schedule-shift-badge[data-ghost="true"]
  :is(strong, .schedule-shift-labels, .schedule-shift-time, .schedule-shift-badge-markers) {
  color: var(--schedule-ghost-text);
}
.schedule-shift-badge[data-ghost="true"] .schedule-ghost-location {
  pointer-events: auto;
}
.schedule-shift-drag-preview {
  position: fixed;
  z-index: 90;
  pointer-events: none;
  filter: drop-shadow(0 14px 22px rgba(24, 34, 30, 0.22));
  opacity: 0.86;
}
.schedule-shift-drag-preview .schedule-shift-badge {
  margin: 0;
  transform: none;
}
.schedule-shift-drag-preview[data-status="blocked"] .schedule-shift-badge {
  filter: saturate(0.75);
  outline: 2px solid #c45b43;
}
.schedule-shift-drag-preview[data-copy="true"] .schedule-shift-badge {
  outline: 2px solid #2f80c5;
}
.schedule-shift-drag-preview[data-status="blocked"][data-copy="true"]
  .schedule-shift-badge {
  outline-color: #c45b43;
}
.schedule-shift-type-preset-drag-preview {
  position: fixed;
  z-index: 90;
  pointer-events: none;
  filter: drop-shadow(0 8px 14px rgba(24, 34, 30, 0.18));
  opacity: 0.8;
}
.schedule-shift-type-preset-drag-preview-card {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 100%;
  min-height: 28px;
  overflow: hidden;
  border: 1px solid
    var(
      --schedule-preset-chip-border,
      color-mix(in srgb, var(--shift-color) 64%, #26332e)
    );
  border-radius: 4px;
  padding: 0 8px;
  background: color-mix(in srgb, var(--shift-color) 14%, var(--theme-surface));
  color: #000;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
  box-shadow:
    inset 0 0 0 1px
      var(
        --schedule-preset-chip-hover-glow,
        color-mix(in srgb, var(--shift-color) 42%, #26332e)
      ),
    inset 0 0 12px
      var(
        --schedule-preset-chip-hover-glow-soft,
        color-mix(in srgb, var(--shift-color) 18%, transparent)
      );
}
.schedule-shift-type-preset-drag-preview[data-status="blocked"]
  .schedule-shift-type-preset-drag-preview-card {
  box-shadow: 0 0 0 2px rgba(248, 113, 113, 0.9);
}
.schedule-shift-type-preset-drag-preview[data-status="allowed"]
  .schedule-shift-type-preset-drag-preview-card {
  box-shadow: 0 0 0 2px rgba(52, 211, 153, 0.9);
}
.schedule-drag-copy-badge,
.schedule-drag-blocked-reason {
  position: absolute;
  right: -6px;
  border-radius: 4px;
  padding: 3px 6px;
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  line-height: 1;
  box-shadow: 0 8px 14px rgba(24, 34, 30, 0.18);
}
.schedule-drag-copy-badge {
  top: -7px;
  background: #2f80c5;
}
.schedule-drag-blocked-reason {
  bottom: -10px;
  max-width: 180px;
  background: #b94f38;
  white-space: nowrap;
}
.schedule-shift-badge[data-selected="true"],
.schedule-shift-badge[data-current="true"] {
  z-index: 1;
}
.schedule-shift-badge[data-selected="true"]::after {
  content: "✓";
  position: absolute;
  top: 5px;
  left: 5px;
  z-index: 2;
  display: grid;
  width: 14px;
  height: 14px;
  place-items: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--shift-color) 62%, #173e34);
  color: var(--theme-on-accent);
  font-size: 9px;
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.78);
}
.schedule-shift-badge[data-selected="true"]::before {
  content: none;
}
.schedule-shift-selection-ring {
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 2px var(--schedule-shift-selection-color);
  animation: schedule-shift-selection-ring-in 160ms ease-out;
}
.schedule-shift-badge[data-current="true"]
  .schedule-shift-selection-ring[data-multi-selected="false"] {
  box-shadow: inset 0 0 0 1px var(--schedule-current-ring-color);
}
.schedule-shift-badge[data-current="true"][data-selected="true"]
  .schedule-shift-selection-ring {
  box-shadow:
    inset 0 0 0 2px var(--schedule-shift-selection-color),
    inset 0 0 0 4px
      color-mix(in srgb, var(--schedule-current-ring-color) 42%, transparent);
}
@keyframes schedule-shift-selection-ring-in {
  from {
    opacity: 0.35;
  }
  to {
    opacity: 1;
  }
}
.schedule-shift-badge[data-publication-state="locked"] {
  opacity: 1;
  filter: saturate(0.9);
}
.schedule-shift-badge[data-publication-state="staged-removed"] {
  opacity: 0.62;
  filter: grayscale(0.75);
}
.schedule-shift-badge[data-publication-state="staged-removed"] strong,
.schedule-shift-badge[data-publication-state="staged-removed"] span,
.schedule-shift-badge[data-publication-state="staged-removed"] em {
  text-decoration: line-through;
}
.schedule-shift-badge[data-publication-state="unlocked-modified"]:not(
    [data-selected="true"]
  ) {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--shift-color) 72%, #176f59);
}
.schedule-shift-badge[data-dragging="true"] {
  cursor: grabbing;
  opacity: 0.54;
}
.schedule-context-menu {
