.schedule-quick-editor {
  position: fixed;
  z-index: 85;
  width: min(304px, calc(100vw - 16px));
  max-height: min(520px, calc(100dvh - 16px));
  overflow: auto;
  border: 1px solid rgba(184, 197, 191, 0.92);
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow:
    0 16px 34px rgba(24, 36, 31, 0.16),
    0 0 0 1px rgba(255, 255, 255, 0.72);
}
.schedule-quick-editor--floating {
  /* max-height comes from the inline style (top position + viewport, BL-199);
     overflow-y lets the body scroll under the sticky header and action bar. */
  overflow-x: hidden;
  overflow-y: auto;
  /* Focus scrolling must clear the sticky header (40px) and action bar
     (47px), or Tab stops on a field hidden under them (BL-199, measured). */
  scroll-padding-top: 48px;
  scroll-padding-bottom: 56px;
  scrollbar-width: none;
}
.schedule-quick-editor--floating::-webkit-scrollbar {
  width: 0;
  height: 0;
}
.schedule-quick-editor > header {
  position: sticky;
  top: 0;
  z-index: 3;
  display: flex;
  min-height: 40px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-bottom: 1px solid var(--theme-border);
  padding: 0 8px 0 12px;
  background: linear-gradient(180deg, #fbfdfc, #f5f8f6);
  cursor: move;
  user-select: none;
}
.schedule-quick-editor > header > span {
  display: grid;
  min-width: 0;
  gap: 1px;
}
.schedule-quick-editor > header strong {
  overflow: hidden;
  color: #26332e;
  font-size: 13.5px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.schedule-quick-editor > header small {
  overflow: hidden;
  color: #66736e;
  font-size: 10px;
  font-weight: 750;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.schedule-quick-editor > header button {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  place-items: center;
  border: 0;
  border-radius: 4px;
