  font-weight: 800;
  text-align: right;
}
.schedule-lock-dialog {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 12px;
  padding: 18px 18px 4px;
}
.schedule-lock-icon {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid #e5c991;
  border-radius: 8px;
  background: var(--theme-warning-soft);
  color: #8b611b;
}
.schedule-lock-dialog p {
  margin: 0;
  color: #34403b;
  font-size: 13px;
  line-height: 1.55;
}
.schedule-lock-dialog small {
  display: block;
  margin-top: 8px;
  color: #6b766f;
  font-size: 11px;
  line-height: 1.45;
}
.schedule-lock-dialog + .schedule-dialog-actions {
  padding: 0 18px 18px;
}
.schedule-edit-locked-dialog {
  position: relative;
  z-index: 1;
  display: grid;
  width: min(448px, calc(100vw - 32px));
  overflow: hidden;
  border: 1px solid #cfd8d3;
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 22px 45px rgba(24, 36, 31, 0.24);
}
.schedule-edit-locked-dialog > header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border-bottom: 1px solid var(--theme-border);
  padding: 16px 20px;
}
.schedule-edit-locked-dialog > header > span {
  display: inline-flex;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid #e5c991;
  border-radius: 8px;
  background: var(--theme-warning-soft);
  color: #8b611b;
}
.schedule-edit-locked-dialog h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 17px;
  font-weight: 800;
}
.schedule-edit-locked-dialog header p,
.schedule-edit-locked-body small {
  margin: 4px 0 0;
  color: #6b766f;
  font-size: 12px;
  line-height: 1.45;
}
.schedule-edit-locked-body {
  display: grid;
  gap: 12px;
  padding: 20px;
}
.schedule-edit-locked-body p {
  margin: 0;
  color: #34403b;
  font-size: 14px;
  line-height: 24px;
}
.schedule-edit-locked-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  border-top: 1px solid var(--theme-border);
  padding: 16px 20px;
  background: var(--theme-surface-soft);
}
.schedule-edit-locked-dialog > footer button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid #b9c7c0;
  border-radius: 5px;
  padding: 0 12px;
  background: var(--theme-surface);
  color: #26312d;
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
}
.schedule-edit-locked-dialog > footer button.primary {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
.schedule-edit-locked-refresh {
  width: 15px;
  height: 15px;
}
.schedule-timeout-dialog {
  position: relative;
  display: grid;
  width: min(calc(100vw - 32px), 412px);
  min-height: 158px;
  grid-template-columns: 104px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid #cfd8d3;
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 22px 45px rgba(24, 36, 31, 0.24);
}
.schedule-timeout-dialog aside {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-right: 1px solid var(--theme-border);
  padding: 16px 14px;
  background: #f4f6f4;
  text-align: center;
}
.schedule-timeout-dialog aside span {
  color: #69746f;
  font-size: 11px;
  font-weight: 800;
  line-height: 16px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.schedule-timeout-dialog aside strong {
  margin-top: 6px;
  color: #25312c;
  font-family:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    monospace;
  font-size: 40px;
  line-height: 42px;
}
.schedule-timeout-dialog aside em {
  color: #69746f;
  font-size: 12px;
  font-style: normal;
  font-weight: 700;
}
.schedule-timeout-dialog section {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  padding: 24px 22px;
}
.schedule-timeout-dialog h2 {
  margin: 0;
  color: #25312c;
  font-size: 17px;
}
.schedule-timeout-dialog p {
  margin: 6px 0 0;
  color: #64706a;
  font-size: 13px;
  line-height: 18px;
}
.schedule-timeout-error {
  border: 1px solid #fde68a;
  border-radius: 6px;
  background: #fffbeb;
  padding: 8px 10px;
  color: #713f12 !important;
  line-height: 18px;
}
.schedule-retroactive-dialog {
  position: relative;
  display: grid;
  width: min(calc(100vw - 32px), 548px);
  max-height: calc(100dvh - 36px);
  overflow: hidden;
  border: 1px solid #cfd8d3;
  border-radius: 8px;
  background: var(--theme-surface);
  box-shadow: 0 22px 45px rgb(24 36 31 / 24%);
}
.schedule-retroactive-dialog header {
  padding: 18px 20px 14px;
  border-bottom: 1px solid #e1e7e3;
}
.schedule-retroactive-dialog header > span {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 999px;
  background: #fff4e0;
  color: #a7620a;
}
.schedule-retroactive-dialog h2 {
  margin: 0;
  color: #25312c;
  font-size: 18px;
  line-height: 24px;
}
.schedule-retroactive-dialog p {
  margin: 6px 0 0;
  color: #5f6c66;
  font-size: 13px;
  line-height: 19px;
}
.schedule-retroactive-dialog ul {
  display: grid;
  max-height: 260px;
  gap: 8px;
  overflow: auto;
  margin: 0;
  padding: 14px 20px;
  list-style: none;
}
.schedule-retroactive-dialog li {
  display: grid;
  gap: 3px;
  border: 1px solid #dbe4df;
  border-radius: 6px;
  background: #f7f9f7;
  padding: 10px 12px;
}
.schedule-retroactive-dialog li span {
  color: #7b5b1f;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}
.schedule-retroactive-dialog li strong {
  color: #27332e;
  font-size: 13px;
  line-height: 18px;
}
.schedule-retroactive-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 14px 20px 18px;
  border-top: 1px solid #e1e7e3;
}
.schedule-retroactive-dialog footer button {
  min-height: 36px;
  border: 1px solid #c8d3ce;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #27332e;
  font-weight: 750;
}
.schedule-retroactive-dialog footer button.primary {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
.schedule-timeout-progress {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  background: #dce3df;
}
.schedule-timeout-progress span {
  display: block;
  height: 100%;
  background: #2787c9;
}
/* Quiet dialogs (Schedule: the Publish and Templates windows): the same style as
   the top-right menus. What needs attention comes first and the footer stays
   in view while the body scrolls. */
[data-schedule-quiet-dialog] .schedule-dialog-backdrop {
  background: rgb(15 23 42 / 28%);
}
[data-schedule-quiet-dialog] .schedule-dialog {
  display: flex;
  flex-direction: column;
  width: min(100%, 540px);
  overflow: hidden;
  border: 0;
  border-radius: 12px;
  box-shadow:
    0 0 0 1px rgb(15 23 42 / 6%),
    0 16px 40px -12px rgb(15 23 42 / 28%);
  font-size: 13px;
}
[data-schedule-quiet-dialog] .schedule-dialog > header {
  flex: 0 0 auto;
  min-height: 0;
  align-items: flex-start;
  gap: 12px;
  border-bottom: 0;
  padding: 18px 12px 4px 18px;
}
[data-schedule-quiet-dialog] .schedule-dialog > header .icon-button {
  color: var(--theme-muted);
}
.schedule-quiet-dialog-heading {
  display: grid;
  flex: 1 1 auto;
  min-width: 0;
  gap: 4px;
}
.schedule-quiet-dialog-heading h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 15px;
  font-weight: 600;
}
.schedule-quiet-dialog-heading p {
  margin: 0;
  color: var(--theme-muted);
  font-size: 13px;
  line-height: 1.45;
}
.schedule-publication-form {
  display: grid;
  flex: 1 1 auto;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  gap: 16px;
  overflow-y: auto;
  padding: 10px 18px 0;
}
.schedule-publication-form > *,
.schedule-publication-review > * {
  min-width: 0;
  max-width: 100%;
}
.schedule-publication-steps {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  color: var(--theme-muted);
  font-size: 12px;
  font-weight: 500;
}
.schedule-publication-steps span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.schedule-publication-steps span + span::before {
  color: var(--theme-border-strong);
  content: "/";
}
.schedule-publication-steps i {
  display: none;
}
.schedule-publication-steps span[data-active="true"] {
  color: var(--theme-text);
  font-weight: 600;
}
.schedule-publication-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: -8px 0 0;
  color: var(--theme-muted);
  font-size: 12px;
}
.schedule-publication-summary strong {
  color: var(--theme-text);
  font-weight: 500;
}
.schedule-publication-form > label,
.schedule-publication-locations legend,
.schedule-publication-departments legend {
  color: var(--theme-muted);
  font-size: 12px;
  font-weight: 500;
}
.schedule-publication-form > label {
  display: grid;
  gap: 6px;
}
.schedule-publication-form select,
.schedule-publication-form textarea {
  width: 100%;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  background: var(--theme-surface);
  color: var(--theme-text);
  font: inherit;
  font-size: 13px;
}
.schedule-publication-form select {
  min-height: 34px;
  padding: 0 10px;
}
.schedule-publication-locations {
  display: grid;
  gap: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-top: 1px solid var(--theme-border-subtle);
}
.schedule-publication-locations legend {
  width: 100%;
  padding: 0 0 6px;
}
.schedule-publication-location {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 2px;
  border-bottom: 1px solid var(--theme-border-subtle);
  cursor: pointer;
}
.schedule-publication-location:hover {
  background: var(--theme-surface-soft);
}
.schedule-publication-location input {
  width: 14px;
  height: 14px;
  margin-top: 2px;
  accent-color: var(--theme-accent);
}
.schedule-publication-location-body {
  display: grid;
  flex: 1;
  min-width: 0;
  gap: 4px;
}
.schedule-publication-location-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}
.schedule-publication-location-name {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.schedule-publication-location-name i {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 999px;
}
.schedule-publication-location strong {
  overflow: hidden;
  color: var(--theme-text);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.schedule-publication-location small {
  color: var(--theme-muted);
  font-size: 12px;
}
.schedule-publication-live-chip {
  flex: 0 0 auto;
}
.schedule-publication-location-delta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
}
.schedule-publication-location-delta small {
  position: relative;
  padding-left: 8px;
  font-weight: 500;
}
.schedule-publication-location-delta small::before {
  position: absolute;
  top: 50%;
  left: 0;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: currentColor;
  content: "";
  transform: translateY(-50%);
}
.schedule-publication-location-delta small[data-kind="new"] {
  color: var(--theme-success);
}
.schedule-publication-location-delta small[data-kind="updated"] {
  color: #1b6c9b;
}
.schedule-publication-location-delta small[data-kind="removed"] {
  color: var(--theme-danger);
}
.schedule-publication-location-delta small[data-kind="none"] {
  color: var(--theme-muted);
}
.schedule-publication-location-warning {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  max-width: 100%;
  border-left: 2px solid var(--theme-warning-border);
  padding: 2px 0 2px 8px;
  color: var(--theme-warning-text);
  font-size: 12px;
  line-height: 1.45;
}
[data-schedule-quiet-dialog] .schedule-dialog-actions {
  position: sticky;
  z-index: 2;
  bottom: 0;
  flex-wrap: nowrap;
  gap: 8px;
  max-width: none;
  margin: 4px -18px 0;
  border-top: 1px solid var(--theme-border-subtle);
  padding: 12px 18px;
  background: var(--theme-surface);
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button {
  min-height: 32px;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  padding: 0 12px;
  color: var(--theme-accent-deep);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transform: none;
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button:hover,
[data-schedule-quiet-dialog] .schedule-dialog-actions button:focus-visible {
  border-color: var(--theme-muted);
  background: var(--theme-surface-muted);
  transform: none;
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button:focus-visible {
  outline: 2px solid var(--theme-focus);
  outline-offset: 2px;
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button.primary {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button.primary:hover,
[data-schedule-quiet-dialog] .schedule-dialog-actions button.primary:focus-visible {
  border-color: var(--theme-accent-strong);
  background: var(--theme-accent-strong);
}
[data-schedule-quiet-dialog] .schedule-dialog-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.schedule-publication-preview-state {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  border: 1px solid #d8e0dc;
  border-radius: 6px;
  padding: 8px 10px;
  background: #f8fbfa;
  color: #64736b;
  font-size: 12px;
  font-weight: 800;
}
.schedule-publication-preview-state svg {
  animation: schedule-spin 0.85s linear infinite;
}
.schedule-publication-preview-state.error {
  justify-content: space-between;
  border-color: #efc6c6;
  background: #fff4f4;
  color: #9d2f2f;
}
.schedule-publication-preview-state.error button {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  gap: 6px;
  border: 1px solid #efc6c6;
  border-radius: 5px;
  padding: 0 9px;
  background: var(--theme-surface);
  color: #9d2f2f;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
}
.schedule-publication-preview-state.error button svg {
  animation: none;
}
.schedule-publication-departments {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  border: 0;
}
.schedule-publication-departments legend {
  padding: 0 0 6px;
}
.schedule-publication-departments > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.schedule-publication-departments label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid var(--theme-border-subtle);
  border-radius: 6px;
  background: var(--theme-surface-soft);
  color: var(--theme-text);
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
}
.schedule-publication-departments input {
  width: 14px;
  height: 14px;
  accent-color: var(--theme-accent);
}
.schedule-publication-departments small {
  color: var(--theme-danger);
  font-size: 12px;
}
.schedule-publication-recovery {
  margin: 0;
  border: 1px solid #efd7a6;
  border-radius: 8px;
  padding: 10px 12px;
  background: #fff8e7;
  color: #755112;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.45;
}
.schedule-publication-conflicts {
  display: grid;
  gap: 7px;
  border: 1px solid #f0cfc9;
  border-radius: 8px;
  padding: 10px;
  background: #fff4f2;
}
.schedule-publication-conflicts > div {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #8d3228;
  font-size: 13px;
}
.schedule-publication-conflicts p {
  margin: 0;
  color: #8d3228;
  font-size: 13px;
  line-height: 1.45;
}
.schedule-publication-conflict-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.schedule-publication-conflict-row p {
  flex: 1;
}
.schedule-publication-conflict-row button {
  border: 1px solid #d8a19a;
  border-radius: 8px;
  padding: 6px 9px;
  background: var(--theme-surface);
  color: #8d3228;
  font-size: 12px;
  font-weight: 750;
  white-space: nowrap;
}
.schedule-publication-review {
  display: grid;
  gap: 16px;
}
.schedule-finding-context,
.schedule-finding-reason-hint {
  color: #64716b;
  font-size: 11px;
  line-height: 1.45;
}
.schedule-publication-diff {
  display: grid;
  gap: 10px;
}
.schedule-publication-diff > section {
  display: grid;
  gap: 3px;
  padding-bottom: 11px;
  border-bottom: 1px solid #dde4e1;
}
.schedule-publication-diff > section > span,
.schedule-unpublish-summary span {
  color: #66736d;
  font-size: 12px;
}
.schedule-publication-diff dl {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  margin: 7px 0 0;
}
.schedule-publication-diff dl div {
  display: grid;
  gap: 2px;
  border-radius: 6px;
  padding: 7px;
  background: var(--theme-surface-soft);
  text-align: center;
}
.schedule-publication-diff dt {
  color: #6b7771;
  font-size: 10px;
}
.schedule-publication-diff dd {
  margin: 0;
  color: #25332d;
  font-size: 14px;
  font-weight: 800;
}
.schedule-publish-preflight-panel {
  display: grid;
  gap: 12px;
}
.schedule-publish-preflight-summary {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: 10px;
  align-items: flex-start;
  border-radius: 8px;
  padding: 10px 12px;
  background: var(--theme-surface-soft);
}
.schedule-publish-preflight-summary[data-ready="true"] {
  background: var(--theme-success-soft);
}
.schedule-publish-preflight-summary svg {
  margin-top: 1px;
  color: var(--theme-muted-strong);
}
.schedule-publish-preflight-summary[data-ready="true"] svg {
  color: var(--theme-accent);
}
.schedule-publish-preflight-summary div,
.schedule-publish-finding-row {
  display: grid;
  gap: 4px;
}
.schedule-publish-preflight-summary strong,
.schedule-publish-finding-row > strong {
  color: var(--theme-text);
  font-size: 13px;
  font-weight: 500;
}
.schedule-publish-preflight-summary span,
.schedule-publish-finding-row > small {
  color: var(--theme-muted-strong);
  font-size: 12px;
  line-height: 1.45;
}
/* A finding group is a left rule and its rows, not a tinted box. */
.schedule-publish-finding-group {
  display: grid;
  gap: 6px;
  border-left: 2px solid var(--theme-danger-border);
  padding: 2px 0 2px 12px;
}
.schedule-publish-finding-group.soft,
.schedule-publish-finding-group.risk {
  border-left-color: var(--theme-warning-border);
}
.schedule-publish-finding-group.note {
  border-left-color: var(--theme-border-strong);
}
.schedule-publish-finding-heading {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--theme-text);
  font-size: 13px;
}
.schedule-publish-finding-heading svg {
  color: var(--theme-danger);
}
.schedule-publish-finding-group.soft .schedule-publish-finding-heading svg,
.schedule-publish-finding-group.risk .schedule-publish-finding-heading svg {
  color: var(--theme-warning);
}
.schedule-publish-finding-group.note .schedule-publish-finding-heading svg {
  color: var(--theme-muted);
}
.schedule-publish-finding-note-copy {
  display: block;
  margin: 0;
  color: var(--theme-muted);
  font-size: 12px;
}
.schedule-publish-finding-row {
  padding: 4px 0;
}
.schedule-publish-finding-row > strong {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.schedule-publish-finding-row > strong em {
  border-radius: 999px;
  padding: 1px 6px;
