/* A shift with a manager's note (BL-199): an 11px ink triangle in the top
   left, clipped by the card's radius, on a 16px hover area that stays
   invisible. The note opens beside the card only for a mouse on that area. */
.schedule-shift-badge .schedule-shift-note-corner {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 2;
  width: 16px;
  height: 16px;
}
.schedule-shift-badge .schedule-shift-note-corner::before {
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  border-top: 11px solid var(--theme-note);
  border-right: 11px solid transparent;
  content: "";
}
.schedule-shift-note-card {
  position: fixed;
  z-index: 200;
  box-sizing: border-box;
  width: max-content;
  max-width: 272px;
  border: 1px solid var(--theme-border);
  border-left: 3px solid var(--theme-note);
  border-radius: 8px;
  padding: 8px 12px 9px 10px;
  background: var(--theme-surface);
  box-shadow: 0 10px 24px rgb(17 24 39 / 16%), 0 2px 6px rgb(17 24 39 / 8%);
  color: var(--theme-text-body);
  text-align: left;
  /* left is the note's centre; top comes measured, so it never leaves the screen. */
  transform: translateX(-50%);
  animation: schedule-shift-note-card-in 120ms ease-out;
}
/* The 8px between the shift card and its note belongs to the note, so the
   pointer never falls into a gap on its way across (WCAG 1.4.13). */
.schedule-shift-note-card::before {
  position: absolute;
  right: 0;
  left: 0;
  height: 10px;
  content: "";
}
.schedule-shift-note-card[data-side="below"]::before {
  top: -10px;
}
.schedule-shift-note-card[data-side="above"]::before {
  bottom: -10px;
}
.schedule-shift-note-card-head {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
  color: var(--theme-note);
  font-size: 11px;
  font-weight: 750;
  line-height: 1.2;
}
.schedule-shift-note-card p {
