  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  overflow-wrap: anywhere;
  white-space: pre-line;
}
/* A manager's note met while placing a shift (S2 B): the note card under the
   cell, asking once with the rule box's buttons. */
.schedule-note-confirm {
  display: grid;
  gap: 4px;
  width: 300px;
