}
.schedule-note-confirm footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 6px;
  border-top: 1px solid var(--theme-border-subtle);
  padding-top: 8px;
}
.schedule-note-confirm footer button {
  min-height: 31px;
  border: 1px solid #bac7c1;
  border-radius: 5px;
  padding: 0 11px;
  background: var(--theme-surface);
  color: #26312d;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
}
.schedule-note-confirm footer button.primary {
  border-color: var(--theme-accent);
  background: var(--theme-accent);
  color: var(--theme-on-accent);
}
.schedule-note-confirm footer button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.schedule-note-confirm footer button:focus-visible {
  outline: 2px solid var(--theme-focus);
  outline-offset: 2px;
}
@keyframes schedule-shift-note-card-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .schedule-shift-note-card {
    animation: none;
  }
}
/* The availability "!" (KARARLAR Schedule, 2026-10-06): an orange button in an
   empty cell's corner, on a clashing card and by the name; a press opens a small
   window with the date and hours. Hover grows it with a ring. */
.schedule-availability-mark {
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: var(--theme-availability);
  color: var(--theme-on-accent);
  font: 800 11px/1 inherit;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}
.schedule-availability-mark:hover,
