  line-height: 1.45;
}
.scheduling-setting-row p {
  margin: 5px 0 0;
  color: #75807b;
  font-size: 12px;
  line-height: 1.45;
}
.setting-control {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}
/* A number with its unit: the pair takes the select's width, so left edges line up. */
.setting-control:has(> .setting-unit) {
  justify-self: end;
  width: min(100%, 250px);
}
.setting-control > :is(select, input) {
  width: min(100%, 250px);
  height: 40px;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  padding: 0 10px;
  background: var(--theme-surface);
  color: var(--theme-text-body);
}
.setting-control:has(> .setting-unit) > input {
  flex: 1 1 0;
  min-width: 0;
}
.conflict-setting-controls {
  display: grid;
  width: min(100%, 250px);
  gap: 12px;
}
.conflict-setting-controls > select,
.conflict-minimum-field input {
  box-sizing: border-box;
  width: 100%;
  height: 40px;
  border: 1px solid var(--theme-muted);
  border-radius: 6px;
  padding: 0 10px;
  background: var(--theme-surface);
  color: var(--theme-text-body);
}
.conflict-minimum-field {
  display: grid;
  gap: 6px;
  color: #4f5c56;
  font-size: 12px;
  font-weight: 700;
}
.conflict-minimum-field small {
  color: #75807b;
  font-weight: 500;
}
.settings-segmented {
  display: grid;
  width: min(100%, 250px);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid #cbd3cf;
  border-radius: 6px;
}
.settings-segmented label {
  position: relative;
  display: grid;
  min-height: 40px;
  place-items: center;
  border-right: 1px solid #cbd3cf;
  color: #5d6863;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
}
.settings-segmented label:last-child {
  border-right: 0;
}
.settings-segmented label[data-selected="true"] {
  background: #e8f1ed;
  color: var(--theme-accent-strong);
}
.settings-segmented input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}
.shift-type-fields {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) 84px minmax(130px, 0.55fr) minmax(
      130px,
      0.55fr
    );
  gap: 16px;
  padding: 20px;
}

@media (max-width: 720px) {
  .app-shell,
  .app-shell[data-sidebar-collapsed="true"] {
    grid-template-columns: minmax(0, 1fr);
  }
  .app-sidebar {
    display: none;
  }
  .workspace-page {
    min-width: 760px;
    padding: 22px 20px;
  }
  .onboarding-content {
    width: min(100% - 40px, 660px);
    padding: 54px 0;
  }
  .onboarding-content h1 {
    font-size: 30px;
  }
  .account-shell {
    grid-template-columns: minmax(0, 1fr);
  }
  .account-sidebar {
    min-height: auto;
    border-right: 0;
    border-bottom: 1px solid #d9dfdc;
    padding: 14px;
  }
  .account-identity {
    margin-bottom: 14px;
  }
  .account-sidebar nav {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
  }
  .account-nav-item {
    justify-content: center;
  }
  .account-sidebar-footer {
    display: flex;
    margin-top: 10px;
  }
  .account-page {
    width: min(100% - 36px, 1320px);
    padding: 34px 0;
  }
  .organization-settings {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    align-content: start;
  }
  .settings-rail {
    min-height: auto;
    overflow: hidden;
    border-right: 0;
    border-bottom: 1px solid #d9dfdc;
    padding: 10px 14px;
  }
  .settings-rail-title {
    display: none;
  }
  .settings-rail nav {
    display: flex;
    gap: 4px;
    margin-top: 0;
    overflow-x: auto;
  }
  .settings-nav-group {
    display: flex;
    gap: 4px;
  }
  .settings-nav-group + .settings-nav-group {
    margin-top: 0;
  }
  .settings-nav-label {
    display: none;
  }
  .settings-nav-item {
    flex: 0 0 auto;
    margin: 0;
  }
  .settings-page {
    width: min(100% - 32px, 1040px);
    padding: 28px 0 42px;
  }
  .settings-page-header {
    grid-template-columns: 38px minmax(0, 1fr);
  }
  .account-page-header {
    grid-template-columns: minmax(0, 1fr);
  }
  .settings-header-action {
    grid-column: 1 / -1;
    width: 100%;
    margin-left: 0;
    justify-self: stretch;
  }
  .account-header-action {
    grid-column: 1 / -1;
    margin-left: 0;
  }
  .settings-header-action .nf-button {
    width: 100%;
  }
  .organization-form-row {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .shift-type-fields,
  .important-date-fields {
    grid-template-columns: 1fr;
  }
  .important-date-note-field {
    grid-column: auto;
  }
  .scheduling-setting-row {
    grid-template-columns: 1fr;
    gap: 13px;
  }
  .setting-control {
    justify-content: stretch;
  }
  .setting-control:has(> .setting-unit) {
    justify-self: stretch;
    width: auto;
  }
  .setting-control > select,
  .settings-segmented {
    width: 100%;
  }
  .form-field.field-wide {
    grid-column: auto;
  }
  .availability-page {
    width: min(100% - 24px, 1040px);
    padding: 28px 0 42px;
  }
  .page-header {
    align-items: stretch;
    flex-direction: column;
  }
  .document-fields {
    grid-template-columns: 1fr;
  }
  .document-description-field {
    grid-column: auto;
    grid-row: auto;
  }
  .document-formats {
    grid-template-columns: 1fr 1fr;
  }
  .retention-fields,
  .acknowledgement-fields {
    grid-template-columns: 1fr;
  }
  .retention-authority-field,
  .acknowledgement-fields .field-wide {
    grid-column: 1;
  }
  .template-preview dl {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .template-preview article {
    padding: 20px;
  }
  .support-section,
  .support-section-heading {
    align-items: stretch;
    flex-direction: column;
  }
  .support-section .nf-button {
    width: 100%;
  }
  .support-details {
    grid-template-columns: 1fr;
    gap: 16px;
  }
}

/* Phase 6B Schedule Requests */
.requests-page {
  color: var(--theme-text);
}
.requests-tabs {
  display: flex;
  gap: 24px;
  align-self: stretch;
}
.requests-tabs button {
  min-height: 58px;
  padding: 0 2px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--theme-muted);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.requests-tabs button.active {
  border-color: #216b50;
  color: #183e30;
}
.requests-tabs strong {
  display: inline-grid;
  min-width: 21px;
  height: 21px;
  margin-left: 5px;
  place-items: center;
  border-radius: 11px;
  background: #e2ebe7;
  color: #285a47;
  font-size: 11px;
}
.requests-toolbar {
  min-width: 0;
  display: grid;
  grid-template-columns: max-content minmax(220px, 1fr) minmax(170px, 220px);
  gap: 10px;
  margin-bottom: 14px;
}
.request-queue-toggle {
  display: flex;
  padding: 3px;
  border: 1px solid #ccd5d1;
  border-radius: 6px;
  background: #e9eeeb;
}
.request-queue-toggle button {
  min-height: 34px;
  padding: 0 12px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: #5b6862;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}
.request-queue-toggle button.active {
  background: var(--theme-surface);
  color: var(--theme-text);
  box-shadow: 0 1px 2px #17221e20;
}
.requests-search,
.requests-toolbar > select {
  min-width: 0;
  min-height: 42px;
  border: 1px solid #ccd5d1;
  border-radius: 5px;
  background: var(--theme-surface);
}
.requests-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  color: var(--theme-muted);
}
.requests-search input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 13px;
}
.requests-toolbar > select {
  padding: 0 10px;
  color: inherit;
  font: inherit;
  font-size: 13px;
}
.requests-workbench {
  min-height: 610px;
  display: grid;
  grid-template-columns: minmax(330px, 0.86fr) minmax(470px, 1.4fr);
  border: 1px solid #ccd5d1;
  background: var(--theme-surface);
}
.requests-list {
  min-width: 0;
  border-right: 1px solid #d8dedb;
  background: #fafbf9;
}
.request-row {
  width: 100%;
  min-height: 84px;
  padding: 13px 12px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) max-content 18px;
  align-items: center;
  gap: 9px;
  border: 0;
  border-bottom: 1px solid #e2e7e4;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.request-row:hover,
.request-row.selected {
  background: #edf3f0;
}
.request-row.selected {
  box-shadow: inset 3px 0 #2b7156;
}
.request-row-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid #d4ddd8;
  border-radius: 5px;
  background: var(--theme-surface);
  color: #3b6655;
}
.request-row-main {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.request-row-main strong,
.request-row-main span,
.request-row-main small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.request-row-main strong {
  font-size: 13px;
}
.request-row-main span {
  color: #47554f;
  font-size: 12px;
}
.request-row-main small {
  color: #75817c;
  font-size: 11px;
}
.request-status {
  width: max-content;
  max-width: 150px;
  padding: 3px 7px;
  border: 1px solid #ced8d3;
  border-radius: 4px;
  background: #f0f4f2;
  color: #4f5f58;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.status-pending,
.status-pending-manager-approval {
  border-color: #d9c78e;
  background: #fff8df;
  color: #785d12;
}
.status-approved {
  border-color: #a9cfbe;
  background: #e9f5ef;
  color: #286149;
}
.status-denied,
.status-rejected,
.status-revoked {
  border-color: #e0b8b3;
  background: var(--theme-danger-soft);
  color: #8b3730;
}
.status-partially-approved {
  border-color: #bfc5df;
  background: #f0f1f8;
  color: #505a80;
}
.request-conflict-count {
  grid-column: 3;
  display: inline-flex;
  align-items: center;
  justify-self: end;
  gap: 3px;
  color: #9a5b23;
  font-size: 11px;
  font-weight: 800;
}
.request-detail {
  min-width: 0;
  background: var(--theme-surface);
}
.request-detail-inner {
  min-width: 0;
  display: grid;
  gap: 22px;
  padding: 22px;
}
.request-detail-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) max-content max-content;
  align-items: center;
  gap: 12px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e0e5e2;
}
.request-detail-header small {
  color: #75817c;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.request-detail-header h2 {
  margin: 2px 0 0;
  font-size: 20px;
}
.request-mobile-close {
  display: none;
}
.request-facts {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.request-facts div {
  min-width: 0;
  display: grid;
  gap: 3px;
}
.request-facts dt,
.request-detail-inner section h2 {
  color: #718079;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.request-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 12px;
  font-weight: 650;
}
.request-detail-inner section {
  min-width: 0;
  display: grid;
  gap: 9px;
}
.request-detail-inner section h2,
.request-detail-inner section p {
  margin: 0;
}
.request-detail-inner section p {
  color: #4f5c56;
  font-size: 13px;
  line-height: 1.55;
}
.request-segments {
  border: 1px solid #dce2df;
}
.request-segments > div {
  min-height: 43px;
  padding: 7px 10px;
  display: grid;
  grid-template-columns: minmax(110px, 1fr) minmax(90px, 1fr) max-content;
  align-items: center;
  gap: 10px;
  border-bottom: 1px solid #e4e8e6;
  font-size: 12px;
}
.request-segments > div:last-child {
  border-bottom: 0;
}
.request-timeline {
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
  list-style: none;
}
.request-timeline li {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 8px;
  color: #617069;
}
.request-timeline li > div {
  display: grid;
  gap: 2px;
}
.request-timeline strong {
  color: #2d3934;
  font-size: 12px;
}
.request-timeline span {
  font-size: 11px;
}
.request-timeline p {
  margin-top: 4px !important;
}
.request-decisions {
  position: sticky;
  bottom: 0;
  padding-top: 14px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  border-top: 1px solid #dce2df;
  background: var(--theme-surface);
}
.requests-page .nf-button.danger {
  background: #a94139;
  color: var(--theme-on-accent);
}
.requests-page .nf-button.danger:hover {
  background: #91372f;
}
.view-only-note {
  padding: 9px 11px;
  border-left: 3px solid #80928a;
  background: var(--theme-surface-muted);
  color: #5c6a64;
  font-size: 12px;
}
.requests-empty {
  min-height: 190px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 5px;
  color: #78857f;
  text-align: center;
}
.requests-empty strong {
  color: #425049;
  font-size: 13px;
}
.requests-empty span {
  font-size: 12px;
}
.request-pagination {
  padding: 12px;
  display: flex;
  justify-content: center;
  gap: 8px;
  border-top: 1px solid #e2e7e4;
}
.detail-empty {
  min-height: 500px;
}
.request-dialog-backdrop {
  position: fixed;
  z-index: 80;
  inset: 0;
  padding: 18px;
  display: grid;
  place-items: center;
  background: #12191699;
}
.request-dialog {
  width: min(520px, 100%);
  max-height: calc(100vh - 36px);
  overflow: auto;
  padding: 18px;
  display: grid;
  gap: 18px;
  border-radius: 6px;
  background: var(--theme-surface);
  box-shadow: 0 18px 60px #10161340;
}
.request-dialog > header,
.request-dialog > footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.request-dialog h2 {
  margin: 2px 0 0;
  font-size: 18px;
}
.request-dialog small,
.decision-note > span {
  color: #74817b;
  font-size: 10px;
  font-weight: 750;
  text-transform: uppercase;
}
.decision-note {
  display: grid;
  grid-template-columns: minmax(0, 1fr) max-content;
  gap: 6px;
  font-size: 12px;
  font-weight: 750;
}
.decision-note textarea {
  grid-column: 1 / -1;
  resize: vertical;
  padding: 9px;
  border: 1px solid var(--theme-border-strong);
  border-radius: 4px;
  font: inherit;
}
.partial-decisions {
  display: grid;
  border: 1px solid #dce2df;
}
.partial-decisions label {
  min-height: 43px;
  padding: 7px 9px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #e3e8e5;
  font-size: 12px;
}
.partial-decisions label:last-child {
  border-bottom: 0;
}
.partial-decisions select {
  min-height: 32px;
  border: 1px solid var(--theme-border-strong);
  border-radius: 4px;
  background: var(--theme-surface);
}
@media (max-width: 1040px) {
  .requests-workbench {
    grid-template-columns: minmax(290px, 0.75fr) minmax(400px, 1fr);
  }
  .request-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 820px) {
  .requests-tabs {
    min-width: 0;
    gap: 0;
  }
  .requests-tabs button {
    min-width: 0;
    flex: 1;
    min-height: 46px;
  }
  .requests-toolbar {
    grid-template-columns: 1fr;
  }
  .request-queue-toggle button {
    flex: 1;
    justify-content: center;
  }
  .requests-workbench {
    min-height: 520px;
    display: block;
  }
  .requests-list {
    min-height: 500px;
    border-right: 0;
  }
  .request-detail {
    display: none;
  }
  .request-detail.open {
    position: fixed;
    z-index: 55;
    inset: 0;
    display: block;
    overflow: auto;
    background: var(--theme-surface);
  }
  .request-detail-inner {
    min-height: 100%;
    padding: 16px 14px 28px;
  }
  .request-mobile-close {
    display: grid;
  }
  .request-decisions {
    margin: auto -14px -28px;
    padding: 12px 14px calc(12px + env(safe-area-inset-bottom));
  }
  .request-decisions .nf-button {
    min-width: 0;
    flex: 1;
  }
}
@media (max-width: 460px) {
  .request-row {
    grid-template-columns: 32px minmax(0, 1fr) 16px;
  }
  .request-row > .request-status,
  .request-conflict-count {
    grid-column: 2;
    justify-self: start;
  }
  .request-row > svg {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
  .request-facts {
    grid-template-columns: 1fr;
  }
  .request-segments > div {
    grid-template-columns: 1fr max-content;
  }
  .request-segments > div > span:nth-child(2) {
    grid-column: 1;
  }
  .request-segments > div > .request-status {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
  .request-detail-header {
    grid-template-columns: minmax(0, 1fr) max-content;
  }
  .request-detail-header > .request-status {
    grid-column: 1;
  }
  .request-mobile-close {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
}

/* Phase 7 Employee Hub */
/* Same top-level page container contract as the main navigation pages
   (.workspace-page/.announcements-page group below). */
.employee-hub-page {
  box-sizing: border-box;
  min-width: 0;
  min-height: 100%;
  width: min(100% - 64px, 1320px);
  margin: 0 auto;
  padding: 30px 0 44px;
  background: #f4f6f4;
  color: #1c2925;
}
@media (max-width: 720px) {
  .employee-hub-page {
    width: 100%;
    padding: 16px 14px 34px;
  }
}
.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.hub-two-column {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(320px, 0.9fr);
  gap: 18px;
}
.hub-panel {
  min-width: 0;
  padding: 22px;
  border: 1px solid #d9dfdc;
  border-radius: 7px;
  background: var(--theme-surface);
}
.hub-panel h2 {
  margin: 0;
  font-size: 19px;
  letter-spacing: 0;
}
.hub-panel h3 {
  margin: 0;
  font-size: 15px;
  letter-spacing: 0;
}
.hub-panel .panel-heading {
  align-items: flex-start;
  margin-bottom: 20px;
}
.hub-panel .panel-heading p:not(.eyebrow) {
  margin: 5px 0 0;
  color: var(--theme-muted);
  font-size: 13px;
}
.shift-details {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.shift-details strong {
  font-size: 18px;
}
.shift-details span {
  color: #36443f;
  font-size: 14px;
}
.shift-details small {
  color: #78847f;
}
.hub-action-list {
  display: grid;
  gap: 10px;
}
.hub-action-list > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) max-content;
  gap: 3px 12px;
  padding: 12px;
  border: 1px solid #e1e6e3;
  border-radius: 6px;
}
.hub-action-list strong {
  font-size: 14px;
}
.hub-action-list span {
  color: #5d6964;
  font-size: 13px;
}
.hub-action-list small {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: center;
  padding: 4px 7px;
  border-radius: 4px;
  background: #edf5f1;
  color: var(--theme-success);
  text-transform: capitalize;
}
.hub-panel select,
.hub-panel input,
.hub-panel textarea {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1px solid #cbd3cf;
  border-radius: 5px;
  background: var(--theme-surface);
  color: inherit;
  font: inherit;
}
.avatar {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #dceee7;
  color: var(--theme-success);
  font-weight: 750;
}
.time-off-form {
  display: grid;
  gap: 14px;
}
.time-off-form label {
  display: grid;
  gap: 6px;
  color: #4d5a55;
  font-size: 13px;
  font-weight: 650;
}
.time-off-form textarea {
  min-height: 86px;
  resize: vertical;
}
.date-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.empty-inline {
  margin: 16px 0 4px;
}

@media (max-width: 900px) {
  .hub-two-column {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 620px) {
  .employee-hub-page {
    padding: 18px 12px 36px;
  }
  .hub-panel {
    padding: 16px;
  }
  .date-pair {
    grid-template-columns: 1fr;
  }
}

/* Phase 8 communication and operations */
.nav-unread {
  min-width: 20px;
  height: 20px;
  margin-left: auto;
  padding: 0 5px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: #b33a35;
  color: var(--theme-on-accent);
  font-size: 10px;
  font-weight: 800;
}
.nav-unread-collapsed {
  position: absolute;
  top: -7px;
  right: -10px;
  z-index: 20;
  min-width: 16px;
  height: 16px;
  margin-left: 0;
  padding: 0 4px;
  border: 2px solid #fff;
  border-radius: 999px;
  font-size: 9px;
  line-height: 1;
}
.workspace-page,
.availability-page,
.important-dates-page,
.employees-page,
.announcements-page,
.notifications-page,
.requests-page {
  box-sizing: border-box;
  min-width: 0;
  min-height: 100%;
  width: min(100% - 64px, 1320px);
  margin: 0 auto;
  padding: 30px 0 44px;
  background: #f4f6f4;
  color: #1c2925;
}
.employees-header,
.page-header,
.workspace-header-actions,
.widget-controls {
  display: flex;
  align-items: center;
}
.employees-header,
.page-header {
  min-height: 86px;
  justify-content: space-between;
  gap: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #d9dfdb;
}
.catalog-page-header {
  display: flex;
  min-height: 118px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin: 0 0 18px;
  padding: 32px 0 20px;
  border-bottom: 1px solid #d9dfdb;
}
.catalog-page-heading {
  min-width: 0;
}
.catalog-page-eyebrow {
  display: block;
  margin: 0 0 9px;
  color: #256b56;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.7px;
  line-height: 1;
  text-transform: uppercase;
}
.catalog-page-header h1 {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  color: #16211c;
  font-size: 38px;
  font-weight: 650;
  letter-spacing: 0;
  line-height: 1.15;
}
.catalog-page-title-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border-radius: 999px;
  background: #2d8c64;
  box-shadow: 0 0 0 6px rgb(45 140 100 / 11%);
}
.catalog-page-header p {
  max-width: 620px;
  margin: 9px 0 0;
  color: #56655d;
  font-size: 12px;
  line-height: 1.5;
}
.catalog-page-actions {
  display: flex;
  min-height: 40px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
}
.page-header .eyebrow {
  margin: 0 0 4px;
  color: #39715f;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}
.employees-header h1,
.page-header h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0;
}
.employees-header p,
.page-header p {
  display: block;
  margin-top: 6px;
  color: var(--theme-muted);
  font-size: 13px;
}
.workspace-header-actions {
  gap: 8px;
  justify-self: end;
}
.owner-setup-checklist {
  margin-top: 0;
  border: 1px solid #d6ded9;
  border-radius: 7px;
  background: var(--theme-surface);
}
.owner-setup-checklist > header {
  min-height: 58px;
  padding: 13px 16px;
  border-bottom: 1px solid #e4e8e5;
}
.owner-setup-checklist h2,
.owner-setup-checklist p {
  margin: 0;
}
.owner-setup-checklist h2 {
  font-size: 15px;
}
.owner-setup-checklist p {
  margin-top: 4px;
  color: var(--theme-muted);
  font-size: 12px;
}
.owner-setup-checklist-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
}
.owner-setup-checklist-item {
  display: grid;
  min-height: 64px;
  grid-template-columns: 22px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 10px;
  border: 0;
  border-right: 1px solid #e6ebe8;
  border-bottom: 1px solid #e6ebe8;
  padding: 11px 14px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  text-decoration: none;
}
.owner-setup-checklist-item:nth-child(3n) {
  border-right: 0;
}
.owner-setup-checklist-item:nth-last-child(-n + 3) {
  border-bottom: 0;
}
.owner-setup-checklist-item:hover {
  background: #f6f8f6;
}
.owner-setup-checklist-item strong,
.owner-setup-checklist-item small {
  display: block;
}
.owner-setup-checklist-item strong {
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.owner-setup-checklist-item small {
  margin-top: 3px;
  color: #708078;
  font-size: 11px;
}
.owner-setup-checklist-status {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border: 1px solid #c8d1cc;
  border-radius: 999px;
  color: var(--theme-accent);
}
.owner-setup-checklist-status[data-done="true"] {
  border-color: var(--theme-accent);
  background: #e8f2ee;
}
.workspace-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
  padding-top: 18px;
}
.catalog-page-header + .workspace-grid {
  padding-top: 0;
}
.workspace-widget {
  grid-column: span 6;
  min-height: 210px;
  overflow: hidden;
  border: 1px solid #d8dfdb;
  border-radius: 7px;
  background: var(--theme-surface);
}
.workspace-widget:nth-child(1),
.workspace-widget:nth-child(2),
.workspace-widget:nth-child(3) {
  grid-column: span 4;
}
.workspace-widget.is-hidden {
  opacity: 0.5;
  border-style: dashed;
}
.workspace-widget > header {
  min-height: 48px;
  padding: 0 15px;
  border-bottom: 1px solid #e4e8e5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.workspace-widget > header h2 {
  margin: 0;
  font-size: 14px;
}
.widget-controls {
  gap: 3px;
}
.workspace-metrics {
  min-height: 160px;
  padding: 20px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: center;
  gap: 16px;
}
.workspace-metrics > div {
  display: grid;
  gap: 4px;
}
.workspace-metrics strong,
.workspace-focus-number > strong {
  font-size: 30px;
  line-height: 1;
}
.workspace-metrics span,
.workspace-focus-number > span {
  color: var(--theme-muted);
  font-size: 12px;
}
.workspace-metrics .widget-link {
  grid-column: 1 / -1;
}
.workspace-focus-number {
  min-height: 160px;
  padding: 22px;
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 7px;
}
.workspace-feed {
  display: grid;
}
.workspace-todos {
  display: grid;
  gap: 10px;
}
.workspace-todo-form {
  padding: 12px 14px 2px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}
.workspace-todo-form input {
  width: 100%;
  min-height: 36px;
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  padding: 0 11px;
  color: #13201a;
  font: inherit;
}
.workspace-todo-form input:focus {
  border-color: #7da08f;
  outline: 2px solid rgb(125 160 143 / 24%);
  outline-offset: 1px;
}
.workspace-feed > a,
.workspace-feed > div {
  min-height: 54px;
  padding: 9px 14px;
  border-bottom: 1px solid #e8ebe9;
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 9px;
  color: inherit;
  text-decoration: none;
}
.workspace-feed > a:hover {
  background: #f4f8f6;
}
.workspace-feed > .workspace-todo-row {
  grid-template-columns: minmax(0, 1fr) 32px;
}
.workspace-todo-row > div {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 9px;
}
.workspace-feed span {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.workspace-feed strong {
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.workspace-feed small {
  color: #718078;
  font-size: 11px;
}
.widget-link {
  min-height: 38px;
  display: flex;
  align-items: center;
  gap: 7px;
  color: #1b6c55;
  font-size: 12px;
  font-weight: 750;
  text-decoration: none;
}
.widget-link > svg:last-child {
  margin-left: auto;
}
.workspace-quick-actions {
  padding: 14px 18px;
  display: grid;
  gap: 3px;
}
.workspace-empty {
  margin: 0;
  padding: 44px 18px;
  color: var(--theme-muted);
  text-align: center;
}
.workspace-state,
.communication-state {
  min-height: 100%;
  display: grid;
  place-items: center;
  background: #f4f6f4;
  color: #627069;
}
.workspace-error,
.communication-error {
  margin: 12px 0 0;
  padding: 10px 12px;
  border-radius: 5px;
  font-size: 12px;
}
.workspace-error,
.communication-error {
  background: #f9e8e6;
  color: #8c2e29;
}
.communication-filters {
  display: flex;
  align-items: center;
  gap: 3px;
}
.announcements-page > .communication-filters {
  margin: 16px 0;
}
.communication-filters button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--theme-muted);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
}
.communication-filters button[aria-selected="true"] {
  border-color: #27735b;
  color: #1c5f4b;
}
.notification-empty {
  min-height: 430px;
  display: grid;
  place-content: center;
  justify-items: center;
  color: #748079;
  text-align: center;
}
.notification-empty h2 {
  margin: 12px 0 3px;
  color: #2c3934;
  font-size: 16px;
}
.notification-empty p {
  margin: 0;
  font-size: 12px;
}
/* Notifications: a framed table like Employees → Documents; day groups are
   in-table sub-heading rows (KARARLAR "Notifications (gelen kutusu)"). On a
   phone the table scrolls sideways inside its frame, the page does not. */
.notification-table {
  min-width: 720px;
}
/* Column shares (KARARLAR Genel → "Liste sayfalarının ortak dili"):
   select 44, Notification 58%, Category 16%, Received 14%, delete 56. */
.notification-table .notification-select-cell {
  width: 44px;
  padding: 0 0 0 14px;
}
.notification-table .notification-category-cell {
  width: 16%;
}
.notification-table .notification-received-cell {
  width: 14%;
}
.notification-table .notification-actions-cell {
  width: 56px;
}
.notification-select-cell input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--theme-accent);
  cursor: pointer;
}
.notification-table tbody tr[data-selected="true"] {
  background: var(--theme-selected);
}
.notification-selected-count {
  margin-left: auto;
  color: var(--theme-text-secondary);
  font-size: 13px;
  white-space: nowrap;
}
.notifications-page.list-page .catalog-toolbar-filter-row {
  gap: 14px;
}
.notification-title-link {
  color: inherit;
  text-decoration: none;
}
.notification-title-link:hover strong {
  text-decoration: underline;
}
.notification-table-state {
  margin: 0;
  padding: 24px 14px;
  color: var(--theme-text-secondary);
  font-size: 13px;
}
.notification-delete {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
}
.notification-table tbody tr {
  height: auto;
  cursor: default;
}
.notification-table tbody td {
  padding: 12px 14px;
  vertical-align: top;
}
.notification-table tbody td.notification-select-cell {
  padding: 14px 0 0 14px;
}
.notification-table tbody td.notification-actions-cell {
  padding: 4px 12px;
}
.notification-table .notification-main-cell,
.notification-table .notification-category-cell {
  white-space: normal;
}
.notification-main-cell strong {
  display: block;
  color: var(--theme-text);
  font-size: 13px;
  font-weight: 650;
}
.notification-main-cell p {
  margin: 3px 0 0;
  color: var(--theme-text-secondary);
  font-size: 13px;
  line-height: 1.45;
}
.notifications-page.list-page .notification-table .notification-day-row th {
  position: static;
  height: auto;
  padding: 6px 14px;
  border-bottom: 1px solid var(--theme-border-subtle);
  background: var(--theme-surface-soft);
  color: var(--theme-muted-strong);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
}
.notification-table tbody tr.notification-day-row:hover,
.notification-table tbody tr.notification-detail-row:hover {
  background: transparent;
}
.notification-table tbody tr.notification-detail-row td {
  padding: 0 14px 14px 58px;
  white-space: normal;
}
.notification-table-wrap > .catalog-table-empty {
  min-height: 320px;
}
/* Phone: the opened shift details stay in view while the row scrolls. */
@media (max-width: 720px) {
  .notification-table tbody tr.notification-detail-row td {
    padding-left: 14px;
  }
  .notifications-page .notification-detail-row .notification-shift-details {
    position: sticky;
    left: 0;
    max-width: calc(100vw - 58px);
  }
}
.notification-load-more {
  display: flex;
  margin: 20px auto 0;
}

@media (max-width: 980px) {
  .owner-setup-checklist-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .owner-setup-checklist-item:nth-child(3n) {
    border-right: 1px solid #e6ebe8;
  }
  .owner-setup-checklist-item:nth-child(2n) {
    border-right: 0;
  }
  .owner-setup-checklist-item:nth-last-child(-n + 3) {
    border-bottom: 1px solid #e6ebe8;
  }
  .owner-setup-checklist-item:nth-last-child(-n + 2) {
    border-bottom: 0;
  }
  .workspace-widget,
  .workspace-widget:nth-child(1),
  .workspace-widget:nth-child(2),
  .workspace-widget:nth-child(3) {
    grid-column: span 6;
  }
}
@media (max-width: 720px) {
  .workspace-page,
  .availability-page,
  .important-dates-page,
  .employees-page,
  .announcements-page,
  .notifications-page,
  .requests-page {
    padding: 16px 14px 34px;
  }
  .workspace-header-actions {
    width: 100%;
    justify-self: stretch;
  }
  .workspace-grid {
    grid-template-columns: 1fr;
  }
  .owner-setup-checklist-list {
    grid-template-columns: 1fr;
  }
  .owner-setup-checklist-item,
  .owner-setup-checklist-item:nth-child(2n),
  .owner-setup-checklist-item:nth-child(3n),
  .owner-setup-checklist-item:nth-last-child(-n + 2),
  .owner-setup-checklist-item:nth-last-child(-n + 3) {
    border-right: 0;
    border-bottom: 1px solid #e6ebe8;
  }
  .owner-setup-checklist-item:last-child {
    border-bottom: 0;
  }
  .workspace-widget,
  .workspace-widget:nth-child(1),
  .workspace-widget:nth-child(2),
  .workspace-widget:nth-child(3) {
    grid-column: 1;
  }
  .communication-filters {
    width: 100%;
    overflow-x: auto;
  }
}

/* Phase 9 public trust pages */
