.public-data-list {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid #dce2de;
}
.public-data-list > div {
  min-width: 0;
  padding: 18px 18px 18px 0;
  border-bottom: 1px solid #dce2de;
}
.public-data-list > div:nth-child(odd) {
  border-right: 1px solid #dce2de;
}
.public-data-list > div:nth-child(even) {
  padding-left: 18px;
}
.public-data-list dt {
  margin-bottom: 6px;
  font-weight: 800;
}
.public-data-list dd {
  margin: 0;
}
.public-inline-link {
  margin-top: 18px;
  font-size: 14px;
}
.public-inline-link:hover,
.public-contact-link:hover {
  color: #9b3e28;
}
.public-contact-link {
  width: fit-content;
  margin-top: 18px;
  padding: 10px 13px;
  border: 1px solid #9ebcaf;
  border-radius: 6px;
  background: var(--theme-surface);
  font-size: 14px;
}
.public-choice-status {
  max-width: 760px;
  padding: 18px 0;
  border-block: 1px solid #b9d1c7;
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 13px;
  align-items: start;
}
.public-choice-status > span {
  width: 10px;
  height: 10px;
  margin-top: 5px;
  border-radius: 50%;
  background: #248663;
}
.public-choice-status strong {
  display: block;
  margin-bottom: 4px;
}
.public-choice-status p {
  margin: 0;
}
.public-trust-footer {
  width: min(1120px, calc(100% - 40px));
  min-height: 128px;
  margin: 0 auto;
  padding: 28px 0;
  border-top: 1px solid #dce2de;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 32px;
}
.public-trust-footer > div {
  display: grid;
  gap: 5px;
}
.public-trust-footer p {
  margin: 0;
  color: #66736e;
  font-size: 13px;
}
.public-trust-footer nav {
  max-width: 600px;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 14px 22px;
}
/* The separator runs the width of the stage; the links sit centred under it. */
.sign-in-trust-links {
  margin-top: 32px;
  padding-top: 18px;
  border-top: 1px solid var(--theme-border-subtle);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 14px;
}
.sign-in-trust-links a {
  /* 24px touch target (WCAG 2.5.8); the negative margin keeps the row height as it was. */
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  margin: -4px 0;
  color: var(--theme-muted-strong);
  font-size: 12px;
  text-decoration: none;
}
.sign-in-trust-links a:hover {
  color: var(--theme-accent);
}

@media (max-width: 760px) {
  .public-trust-header-inner {
    width: 100%;
    min-height: 0;
    padding: 12px 14px 0;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 10px 16px;
  }
  .public-trust-header nav {
    grid-column: 1 / -1;
    grid-row: 2;
    overflow-x: auto;
    gap: 20px;
  }
  .public-trust-header nav a {
    min-height: 42px;
    white-space: nowrap;
  }
  .public-trust-main {
    width: min(100% - 28px, 960px);
    padding: 38px 0 64px;
  }
  .public-document {
    gap: 26px;
  }
  .public-document-heading {
    grid-template-columns: 40px minmax(0, 1fr);
    gap: 13px;
  }
  .public-document-icon {
    width: 40px;
    height: 40px;
  }
  .public-document-heading h1 {
    font-size: 32px;
  }
  .public-document-heading div > div {
    font-size: 15px;
  }
  .public-document-status {
    grid-template-columns: 1fr auto;
    align-items: start;
  }
  .public-document-status span {
    grid-column: 1 / -1;
    grid-row: 2;
  }
  .public-data-list {
    grid-template-columns: 1fr;
  }
  .public-data-list > div,
  .public-data-list > div:nth-child(even) {
    padding: 16px 0;
    border-right: 0;
  }
  .public-trust-footer {
    width: calc(100% - 28px);
    min-height: 0;
    flex-direction: column;
  }
  .public-trust-footer nav {
    justify-content: flex-start;
  }
}
.current-user-avatar { width: 24px; height: 24px; flex: 0 0 24px; object-fit: cover; border-radius: 50%; display: inline-grid; place-items: center; background: var(--surface-muted, #edf1ee); color: var(--text-primary, #183c30); font-size: 10px; font-weight: 700; }

.jobs-settings-page,
.job-assignment-drawer {
  --job-bg: #fff;
  --job-subtle: #f7f9f8;
  --job-hover: #f0f5f2;
  --job-border: #e1e7e3;
  --job-text: #24382f;
  --job-muted: #647168;
  --job-accent: #256b56;
  --job-soft: #e8f2ed;
  --job-error: #a53936;
  color: var(--job-text);
}
.shift-catalog-header-actions {
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 24px;
}
.shift-catalog-header-actions .job-primary-button {
  flex: 0 0 auto;
  width: auto;
}
.shift-catalog-shell .requests-tabs button,
.acknowledgement-page .requests-tabs button {
  font-size: 13px;
  font-weight: 700;
}
.shift-catalog-panel > .shift-catalog-settings-page {
  width: 100%;
  margin: 0;
  padding: 0 0 60px;
}
.shift-catalog-panel > .shift-catalog-settings-page > .settings-page-header {
  margin-top: 0;
}
.jobs-settings-page button,
.job-assignment-drawer button {
  font: inherit;
  cursor: pointer;
}
.jobs-settings-page button:disabled,
.job-assignment-drawer button:disabled {
  cursor: default;
  opacity: 0.45;
}
.jobs-settings-page :is(button, input, select, summary):focus-visible,
.job-assignment-drawer :is(button, input, select):focus-visible {
  outline: 2px solid var(--job-accent);
  outline-offset: 3px;
}
.jobs-settings-page
  :is(
    .job-count-button,
    .job-group-toggle,
    .job-text-button,
    [role="tab"]
  ):is(:focus, :focus-visible) {
  outline: none;
  box-shadow: none;
}
.catalog-delete-action {
  margin: 0;
  font-size: 12px;
}
.catalog-delete-trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: 6px;
  color: var(--job-error);
  background: transparent;
  font-size: 12px !important;
  font-weight: 500 !important;
}
.catalog-delete-trigger:hover {
  background: color-mix(in srgb, var(--job-error) 8%, transparent);
  border-color: color-mix(in srgb, var(--job-error) 18%, transparent);
}
.catalog-delete-confirm {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--job-error) 24%, var(--job-border));
  border-radius: 6px;
  background: color-mix(in srgb, var(--job-error) 5%, var(--job-bg));
}
.catalog-delete-copy {
  display: grid;
  gap: 4px;
  flex: 1 1 240px;
  min-width: 0;
}
.catalog-delete-copy strong {
  color: var(--job-text);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.catalog-delete-copy span {
  color: var(--job-muted);
  font-size: 12px;
  line-height: 1.5;
}
.catalog-delete-copy [role="alert"] {
  color: var(--job-error);
}
.catalog-delete-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.catalog-delete-confirm-button {
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid #a53936;
  border-radius: 6px;
  color: var(--theme-on-accent);
  background: #a53936;
  font-size: 12px !important;
  font-weight: 600 !important;
}
.catalog-delete-confirm-button:hover {
  background: #8c2e2b;
}
.catalog-delete-copy .catalog-delete-options {
  display: grid;
  gap: 8px;
  padding: 8px 0 0;
  border: 0;
  margin: 0;
}
.catalog-delete-options legend {
  padding: 6px 0;
  color: var(--job-text);
}
.catalog-delete-options label {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--job-text);
}
.catalog-delete-options input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: var(--job-error);
}
.job-catalog-editor .catalog-delete-options input[type="radio"] {
  width: 14px;
  height: 14px;
  min-height: 14px;
  margin: 0;
  padding: 0;
  flex: 0 0 14px;
}
.job-primary-button,
.job-secondary-button,
.job-small-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--job-border);
  border-radius: 6px;
  font-size: 12px !important;
  font-weight: 650 !important;
  white-space: nowrap;
  background: var(--job-bg);
  color: var(--job-text);
}
.job-primary-button {
  background: #286d57;
  color: white;
  border-color: #286d57;
}
.job-primary-button:hover:not(:disabled) {
  background: #205943;
}
.job-secondary-button:hover:not(:disabled),
.job-small-button:hover:not(:disabled) {
  background: var(--job-hover);
}
.job-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  min-width: 32px;
  height: 32px;
  background: transparent;
  color: var(--job-muted);
  border: 0;
  border-radius: 5px;
  padding: 0;
}
.job-icon-button:hover:not(:disabled) {
  background: var(--job-hover);
  color: var(--job-text);
}
.job-create-actions {
  display: flex;
  gap: 8px;
}
.jobs-settings-page .job-sort-button {
  display: flex;
  align-items: center;
  gap: 5px;
  background: none;
  border: 0;
  padding: 0;
  color: inherit;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  min-width: 0;
  white-space: nowrap;
}
.jobs-settings-page .job-sort-button:hover,
.jobs-settings-page .job-sort-button[aria-pressed="true"] {
  color: var(--job-text);
}
.job-column-headings .job-sort-button:nth-child(3) {
  justify-content: flex-end;
}
.job-row-menu.job-create-menu {
  z-index: 12;
}
.job-row-menu.job-create-menu > summary {
  width: auto;
  height: 36px;
  min-width: 88px;
  padding: 0 12px;
  gap: 7px;
  border-radius: 6px;
  background: #286d57;
  color: #fff;
}
.job-row-menu.job-create-menu > summary:hover {
  background: #205943;
}
.job-row-menu.job-create-menu[open] > summary,
.job-row-menu.job-create-menu > summary:hover {
  color: var(--theme-on-accent);
  background: #205943;
}
.job-create-menu .job-menu-popover button {
  display: flex;
  align-items: center;
  gap: 9px;
}
.job-catalog-toolbar:not(.catalog-toolbar) {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin: 20px 0 16px;
}
.document-catalog-toolbar .job-archive-filter {
  margin-left: auto;
}
.jobs-settings-page .toolbar-filter-select {
  border-color: var(--job-border);
  background: var(--job-bg);
  color: var(--job-text);
}
.job-view-control {
  display: inline-flex;
  align-items: center;
  padding: 3px;
  gap: 2px;
  border: 1px solid var(--job-border);
  border-radius: 7px;
  background: var(--job-subtle);
}
.job-view-control button {
  padding: 7px 12px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--job-muted);
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.job-view-control button[aria-selected="true"],
.job-view-control button[aria-pressed="true"] {
  background: var(--job-bg);
  color: var(--job-text);
  box-shadow: 0 1px 3px #10251a16;
}
.job-search {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 180px;
  border: 1px solid var(--job-border);
  border-radius: 6px;
  background: var(--job-bg);
  color: var(--job-muted);
  padding: 0 10px;
  min-height: 36px;
  flex: 1;
  max-width: 360px;
}
.job-search:focus-within {
  border-color: var(--job-accent);
}
.jobs-settings-page .job-search input,
.job-assignment-drawer .job-search input {
  background: transparent;
  border: 0;
  outline: none;
  box-shadow: none;
  padding: 0;
  min-width: 0;
  height: 34px;
  width: 100%;
  font-size: 12px;
  color: var(--job-text);
}
.job-search button {
  border: 0;
  background: none;
  color: var(--job-muted);
  display: flex;
  padding: 2px;
}
.job-archive-filter {
  display: flex;
  gap: 7px;
  align-items: center;
  font-size: 12px;
  color: var(--job-muted);
  margin-left: auto;
  white-space: nowrap;
}
.job-archive-filter input,
.job-employee-row input {
  accent-color: #286d57;
  width: 15px;
  height: 15px;
  margin: 0;
  flex-shrink: 0;
}
.job-catalog {
  border: 1px solid var(--job-border);
  border-radius: 8px;
  background: var(--job-bg);
  min-width: 0;
}
.job-catalog-caption {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
  font-size: 11px;
  color: var(--job-muted);
  border-bottom: 1px solid var(--job-border);
}
.job-text-button {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 5px;
  min-height: 28px;
  background: none;
  border: 0;
  color: var(--job-muted);
  font-size: 11px !important;
  padding: 0;
}
.job-text-button:hover {
  color: var(--job-accent);
}
.job-catalog-row,
.job-column-headings {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(100px, 1fr) 86px 32px;
  align-items: center;
  gap: 12px;
  padding: 0 14px;
  min-height: 48px;
  border-bottom: 1px solid var(--job-border);
}
.job-column-headings {
  min-height: 34px;
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--job-muted);
  background: var(--job-subtle);
}
.job-column-headings.catalog-column-headings {
  min-height: 40px;
  height: 40px;
  padding: 0 14px;
  background: #f3f5f3;
  color: #68726e;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0;
}
.job-catalog-row:last-child {
  border-bottom: 0;
}
.job-catalog-row:hover {
  background: var(--job-hover);
}
.job-row-identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  min-height: 46px;
  padding: 0;
  background: none;
  border: 0;
  text-align: left;
  color: var(--job-text);
  width: 100%;
}
.job-row-name {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 600;
  min-width: 0;
}
.job-name-stack {
  min-width: 0;
}
.job-color-dot {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex: 0 0 9px;
  box-shadow: 0 0 0 1px #182f2014;
}
.job-department-cell {
  font-size: 12px;
  color: var(--job-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.job-count-button {
  display: inline-flex;
  gap: 7px;
  align-items: center;
  justify-content: flex-start;
  border: 0;
  background: none;
  font-size: 12px !important;
  color: var(--job-muted);
  padding: 0;
  min-height: 32px;
}
.job-count-button:hover {
  color: var(--job-accent);
}
.job-archived-label {
  font-size: 10px;
  color: var(--job-muted);
  background: var(--job-subtle);
  padding: 3px 6px;
  border-radius: 4px;
  white-space: nowrap;
}
.job-catalog-row[data-archived="true"] .job-row-identity {
  color: var(--job-muted);
}
.job-department-columns {
  grid-template-columns: minmax(0, 1fr) 72px 86px 32px;
}
.job-mobile-meta {
  display: none;
}
.job-group + .job-group {
  border-top: 1px solid var(--job-border);
}
.job-group-heading {
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 14px;
  background: var(--job-subtle);
}
.job-group-toggle {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1;
  min-width: 0;
  min-height: 46px;
  background: none;
  border: 0;
  padding: 0;
  color: var(--job-text);
  text-align: left;
}
.job-group-toggle > svg {
  flex-shrink: 0;
}
.job-group-count {
  font-size: 11px;
  font-weight: 400;
  color: var(--job-muted);
  white-space: nowrap;
}
.job-group-people {
  display: flex;
  gap: 6px;
  align-items: center;
  font-size: 12px;
  color: var(--job-muted);
  min-width: 44px;
}
.job-group-add {
  font-size: 11px !important;
  white-space: nowrap;
}
.job-nested-row {
  grid-template-columns: minmax(0, 1fr) 86px 32px;
  padding-left: 55px;
}
.job-group-empty {
  font-size: 12px;
  color: var(--job-muted);
  padding: 16px 54px;
  margin: 0;
}
.job-row-menu {
  position: relative;
  flex-shrink: 0;
}
.job-row-menu > summary {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  cursor: pointer;
  color: var(--job-muted);
  list-style: none;
  border-radius: 5px;
}
.job-row-menu > summary::-webkit-details-marker {
  display: none;
}
.job-row-menu[open] > summary,
.job-row-menu > summary:hover {
  background: var(--job-hover);
  color: var(--job-text);
}
.job-menu-popover {
  position: absolute;
  right: 0;
  top: 34px;
  z-index: 120;
  min-width: 176px;
  padding: 5px;
  background: var(--job-bg);
  border: 1px solid var(--job-border);
  border-radius: 7px;
  box-shadow: 0 10px 28px #14251b24;
}
.job-menu-popover button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 8px 9px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--job-text);
  font-size: 12px;
}
.job-menu-popover button:hover:not(:disabled) {
  background: var(--job-hover);
}
.job-menu-popover .job-danger-text {
  color: var(--job-error);
}
.job-catalog-editor {
  font-family: inherit;
  font-size: 13px;
  line-height: 1.5;
  font-weight: 400;
  background: var(--job-bg);
  border: 1px solid var(--job-border);
  border-radius: 8px;
  max-width: 720px;
  margin: 0 0 18px;
  box-shadow: 0 3px 12px #183c2310;
}
.job-editor-title {
  display: flex;
  justify-content: space-between;
  align-items: start;
  padding: 16px;
  border-bottom: 1px solid var(--job-border);
}
.job-editor-title h2 {
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  margin: 0 0 5px;
}
.job-editor-title p,
.job-hint {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--job-muted);
  margin: 0;
}
.job-catalog-editor fieldset {
  border: 0;
  margin: 0;
  padding: 16px;
  display: grid;
  gap: 16px;
  min-width: 0;
}
.job-field > span,
.job-field > label,
.job-section-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 7px;
}
.job-name-color {
  display: flex;
  gap: 8px;
  align-items: center;
}
.job-name-color > input {
  flex: 1;
  min-width: 0;
}
.job-catalog-editor
  input:not([type="color"], [type="checkbox"], [type="radio"]),
.job-catalog-editor select,
.job-assignment-drawer select {
  min-height: 36px;
  padding: 7px 10px;
  background: var(--job-bg);
  color: var(--job-text);
  border: 1px solid var(--job-border);
  border-radius: 5px;
  font: inherit;
  font-size: 12px;
  box-sizing: border-box;
  min-width: 0;
  width: 100%;
}
.job-catalog-editor .job-color-control {
  position: relative;
  display: block;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  border-radius: 6px;
  border: 3px solid var(--job-bg);
  outline: 1px solid var(--job-border);
  overflow: hidden;
  cursor: pointer;
}
.job-catalog-editor
  input:not([type="color"], [type="checkbox"], [type="radio"]),
.job-catalog-editor select {
  font-size: 13px;
  font-weight: 400;
  line-height: 1.5;
}
.job-catalog-editor input::placeholder {
  color: var(--job-muted);
  opacity: 1;
  font-weight: 400;
}
.job-catalog-editor
  :is(.job-primary-button, .job-secondary-button, .job-small-button) {
  font-size: 12px !important;
  font-weight: 600 !important;
}
.job-catalog-editor .job-color-control:focus-within {
  outline: 2px solid var(--job-accent);
}
.job-catalog-editor .job-color-control input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  border: 0;
  padding: 0;
}
.job-draft-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 32px 64px;
  gap: 8px;
  align-items: center;
  margin-bottom: 8px;
}
.job-draft-row > .job-icon-button {
  justify-self: end;
}
.job-section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.job-section-label span + span {
  font-weight: 400;
  color: var(--job-muted);
}
.job-editor-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--job-border);
}
.job-editor-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-left: auto;
}

.policy-footer-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.policy-footer-confirm {
  flex: 1 1 auto;
  min-width: min(100%, 360px);
}
.policy-footer-actions .catalog-delete-trigger {
  height: 36px;
}
.job-editor-footer .catalog-delete-action {
  flex: 1 1 auto;
  min-width: 0;
}
.job-editor-footer .catalog-delete-confirm {
  width: 100%;
}
.job-shift-times {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.shift-default-time-label {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
}
.shift-default-info {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.shift-default-info-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: 1px solid var(--job-border);
  border-radius: 999px;
  background: var(--job-bg);
  color: var(--job-muted);
}
.shift-default-info-trigger:hover,
.shift-default-info-trigger:focus-visible {
  border-color: color-mix(in srgb, var(--job-accent) 44%, var(--job-border));
  color: var(--job-accent);
}
.shift-default-info-popover {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  z-index: 180;
  width: min(320px, 80vw);
  padding: 10px 11px;
  border: 1px solid var(--job-border);
  border-radius: 6px;
  background: var(--job-bg);
  color: var(--job-text);
  box-shadow: 0 12px 28px #14251b24;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.45;
  text-transform: none;
  transform: translateX(-50%);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.shift-default-info:hover .shift-default-info-popover,
.shift-default-info:focus-within .shift-default-info-popover {
  opacity: 1;
  visibility: visible;
}
.shift-catalog-settings-page
  .job-catalog-editor
  > :is(.settings-state, .form-error, [role="alert"]) {
  margin: 0 16px 16px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--job-muted);
}
.shift-catalog-settings-page .job-catalog-editor > .settings-state {
  background: var(--job-subtle);
  padding: 12px;
  border-radius: 6px;
}
.shift-catalog-settings-page .job-catalog-editor > .settings-state p {
  margin: 6px 0 0;
}
.shift-catalog-settings-page
  .job-catalog-editor
  > :is(.form-error, [role="alert"]) {
  color: var(--job-error);
}
.shift-catalog-settings-page .job-catalog-editor > .job-secondary-button {
  margin: 0 16px 16px;
}
.job-error {
  font-size: 12px;
  line-height: 1.5;
  color: var(--job-error);
  padding: 12px 16px;
  margin: 0;
}
.job-error button {
  background: none;
  border: 0;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
  margin-left: 7px;
}
.job-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
  padding: 48px 20px;
  color: var(--job-muted);
  font-size: 13px;
}
.job-empty-state h2,
.job-empty-state h3 {
  color: var(--job-text);
  font-size: 15px;
  margin: 0;
}
.job-empty-state p {
  margin: 0;
  font-size: 12px;
}
.job-assignment-drawer {
  position: relative;
  width: min(640px, 100%);
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--job-bg);
  box-shadow: -12px 0 40px #10221a18;
  min-width: 0;
}
.job-drawer-header {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 24px;
  border-bottom: 1px solid var(--job-border);
}
.job-drawer-heading {
  display: flex;
  gap: 13px;
  min-width: 0;
  align-items: center;
}
.job-drawer-heading > div {
  min-width: 0;
}
.job-drawer-job-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 44px;
  height: 44px;
  background: var(--job-subtle);
  border: 1px solid var(--job-border);
  border-radius: 9px;
}
.job-drawer-heading p {
  font-size: 11px;
  color: var(--job-muted);
  margin: 0 0 4px;
}
.job-drawer-heading h2 {
  font-size: 20px;
  line-height: 1.3;
  margin: 0 0 5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.job-drawer-heading > div > span {
  font-size: 11px;
  color: var(--job-muted);
}
.job-drawer-controls {
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--job-border);
}
.job-drawer-intro {
  display: flex;
  gap: 12px;
  align-items: baseline;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.job-drawer-intro h3 {
  font-size: 13px;
  margin: 0;
}
.job-drawer-intro p {
  font-size: 11px;
  margin: 0;
  color: var(--job-muted);
}
.job-drawer-search-row {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}
.job-drawer-search-row > .job-search {
  max-width: none;
}
.job-drawer-search-row > select {
  width: 156px;
}
.job-drawer-filter-row {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
}
.job-drawer-filter-row > select {
  width: 125px;
  font-size: 11px;
}
.job-employee-list {
  overflow-y: auto;
  flex: 1;
  min-height: 0;
  overscroll-behavior: contain;
}
.job-employee-row {
  display: flex;
  gap: 10px;
  align-items: center;
  min-height: 64px;
  padding: 10px 24px;
  border-bottom: 1px solid var(--job-border);
  box-sizing: border-box;
  cursor: pointer;
}
.job-employee-row:hover {
  background: var(--job-hover);
}
.job-employee-row[data-pending="true"] {
  background: var(--job-soft);
  box-shadow: inset 3px 0 var(--job-accent);
}
.job-employee-row[data-disabled="true"] {
  cursor: default;
}
.job-employee-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--job-subtle);
  border: 1px solid var(--job-border);
  width: 30px;
  height: 30px;
  border-radius: 50%;
  flex: 0 0 30px;
  font-size: 12px;
  color: var(--job-muted);
}
.job-employee-identity {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  min-width: 0;
}
.job-employee-identity strong {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}
.job-employee-identity > span {
  font-size: 10px;
  color: var(--job-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.job-employee-identity small {
  font-size: 10px;
  color: var(--job-muted);
}
.job-employee-meta {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 5px;
  flex-shrink: 0;
}
.job-primary-tag {
  font-size: 9px;
  border: 1px solid var(--job-border);
  border-radius: 4px;
  padding: 2px 5px;
  color: var(--job-muted);
}
.job-drawer-pagination {
  padding: 8px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--job-border);
  color: var(--job-muted);
  font-size: 11px;
}
.job-drawer-pagination > div {
  display: flex;
  gap: 4px;
}
.job-save-notice {
  padding: 10px 24px;
  font-size: 12px;
  color: var(--job-accent);
  background: var(--job-soft);
}
.job-discard-backdrop {
  position: absolute;
  inset: 0;
  background: #10221966;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.job-discard-dialog {
  background: var(--job-bg);
  border: 1px solid var(--job-border);
  border-radius: 10px;
  padding: 24px;
  box-shadow: 0 12px 40px #0003;
}
.job-discard-dialog h3 {
  font-size: 16px;
  margin: 0 0 10px;
}
.job-discard-dialog p {
  color: var(--job-muted);
  font-size: 12px;
  margin: 0 0 20px;
}
.job-discard-dialog > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
@media (max-width: 1100px) {
  .job-catalog-toolbar:not(.catalog-toolbar) .job-search {
    order: 3;
    max-width: none;
    flex-basis: 100%;
  }
  .job-group-count {
    display: none;
  }
}
@media (max-width: 720px) {
  .job-primary-button,
  .job-secondary-button,
  .job-small-button,
  .job-icon-button,
  .job-row-menu > summary,
  .job-view-control button,
  .job-text-button,
  .job-count-button {
    min-height: 44px;
  }
  .job-icon-button,
  .job-row-menu > summary {
    min-width: 36px;
    width: 36px;
  }
  .job-create-actions {
    flex-wrap: wrap;
  }
  .job-catalog-toolbar:not(.catalog-toolbar) {
    gap: 10px;
  }
  .job-view-control button {
    padding: 7px 10px;
  }
  .job-archive-filter {
    font-size: 11px;
  }
  .job-catalog-row,
  .job-column-headings {
    grid-template-columns: minmax(0, 1fr) 50px 36px;
    gap: 8px;
    padding: 4px 10px;
  }
  .job-department-cell,
  .job-column-headings:not(.job-department-columns) > span:nth-child(2) {
    display: none;
  }
  .job-department-columns {
    grid-template-columns: minmax(0, 1fr) 35px 42px 36px;
  }
  .job-column-headings {
    font-size: 9px;
  }
  .job-mobile-meta {
    display: block;
    color: var(--job-muted);
    font-size: 10px;
    font-weight: 400;
    margin-top: 3px;
  }
  .job-text-button > .job-mobile-meta {
    display: none;
  }
  .job-row-name {
    font-size: 12px;
  }
  .job-group-heading {
    gap: 5px;
    padding: 0 10px;
  }
  .job-group-toggle {
    gap: 6px;
  }
  .job-group-people {
    min-width: 30px;
    font-size: 11px;
    gap: 4px;
  }
  .job-group-add > span {
    display: none;
  }
  .job-group-add {
    width: 28px;
    justify-content: center;
  }
  .job-nested-row {
    padding-left: 30px;
  }
  .job-group-empty {
    padding: 16px 30px;
  }
  .job-catalog-editor
    input:not([type="color"], [type="checkbox"], [type="radio"]),
  .job-catalog-editor select,
  .job-assignment-drawer select {
    min-height: 44px;
    font-size: 14px;
  }
  .job-search {
    min-height: 44px;
  }
  .jobs-settings-page .job-search input,
  .job-assignment-drawer .job-search input {
    height: 42px;
    font-size: 13px;
  }
  .job-draft-row {
    grid-template-columns: minmax(0, 1fr) 32px 56px;
  }
  .job-drawer-header {
    padding: 20px 16px;
  }
  .job-drawer-controls {
    padding: 16px;
  }
  .job-drawer-search-row {
    flex-wrap: wrap;
  }
  .job-drawer-search-row > .job-search {
    flex-basis: 100%;
  }
  .job-drawer-search-row > select {
    width: 100%;
  }
  .job-drawer-filter-row {
    gap: 8px;
  }
  .job-drawer-filter-row .job-view-control button {
    padding: 6px 8px;
    font-size: 11px;
  }
  .job-drawer-filter-row > select {
    width: 110px;
    font-size: 11px;
  }
  .job-employee-row {
    padding: 10px 16px;
    gap: 8px;
  }
  .job-employee-avatar {
    display: none;
  }
  .job-employee-meta {
    max-width: 82px;
  }
  .job-drawer-pagination {
    padding: 6px 16px;
  }
  .job-drawer-job-icon {
    flex-basis: 38px;
    height: 38px;
  }
  .job-drawer-heading h2 {
    font-size: 18px;
  }
  .job-count-button > svg {
    width: 12px;
  }
  .job-row-menu .job-menu-popover button {
    min-height: 44px;
  }
  .job-menu-popover {
    top: 44px;
  }
}

.job-catalog-editor .location-catalog-fields {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.location-catalog-fields > :first-child,
.location-catalog-fields .field-wide {
  grid-column: 1/-1;
}
.locations-catalog-settings-page .location-catalog-row {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr) 130px 140px 32px;
}
.location-catalog-address.location-catalog-cell {
  margin-top: 0;
}
.locations-catalog-settings-page .location-address-meta {
  display: none;
}
/* Narrow content: address moves under the name. */
@media (max-width: 1100px) {
  .locations-catalog-settings-page .location-catalog-row {
    grid-template-columns: minmax(0, 1fr) 100px 90px 32px;
  }
  .locations-catalog-settings-page .location-address-col {
    display: none;
  }
  .locations-catalog-settings-page .location-address-meta {
    display: block;
  }
}
.job-field input[aria-invalid="true"] {
  border-color: var(--job-error);
  box-shadow: 0 0 0 1px var(--job-error);
}
.location-field-error {
  color: var(--job-error);
  font-size: 12px;
}
.locations-catalog-settings-page .job-catalog-row {
  min-height: 64px;
}
.location-catalog-marker {
  flex-shrink: 0;
  color: var(--job-muted);
}
.location-catalog-address {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--job-muted);
  font-size: 12px;
  font-weight: 400;
  margin-top: 3px;
}
.location-catalog-zone {
  color: var(--job-muted);
  font-size: 12px;
}
.locations-catalog-settings-page .job-catalog-editor > .form-error {
  margin: 0 16px 16px;
  color: var(--job-error);
  font-size: 12px;
}
@media (max-width: 720px) {
  .locations-catalog-settings-page .location-catalog-row {
    grid-template-columns: minmax(0, 1fr) 44px;
  }
  .location-catalog-zone,
  .location-catalog-cell {
    display: none;
  }
  .job-catalog-editor .location-catalog-fields {
    grid-template-columns: minmax(0, 1fr);
  }
  .locations-catalog-settings-page .location-catalog-row.job-column-headings {
    display: none;
  }
}
@media (max-width: 720px) {
  .jobs-settings-page:not(.locations-catalog-settings-page)
    .job-column-headings {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr)) 32px;
    gap: 4px;
  }
  .jobs-settings-page .job-sort-button {
    min-height: 44px;
  }
}

.shift-catalog-settings-page .shift-catalog-columns {
  grid-template-columns: minmax(0, 1fr) 32px;
}
.shift-catalog-settings-page .shift-catalog-columns.has-times {
  grid-template-columns:
    minmax(0, 1.5fr) minmax(110px, 0.75fr) minmax(130px, 0.75fr)
    32px;
}
@media (max-width: 720px) {
  .shift-catalog-header-actions {
    flex-wrap: wrap;
    gap: 12px;
    width: 100%;
    justify-content: space-between;
  }
  .shift-catalog-settings-page .shift-catalog-columns.has-times {
    grid-template-columns: minmax(0, 1fr) 44px;
  }
  .shift-catalog-settings-page .job-column-headings.has-times {
    grid-template-columns: repeat(3, minmax(0, 1fr)) 32px;
  }
  .shift-catalog-time {
    display: none;
  }
  .catalog-delete-buttons {
    width: 100%;
  }
  .catalog-delete-buttons button {
    flex: 1;
    min-height: 44px;
  }
}
.shift-catalog-settings-page .job-column-headings .job-sort-button {
  justify-content: flex-start;
}
.acknowledgement-page .acknowledgement-catalog-row {
  grid-template-columns:
    minmax(0, 1.5fr) minmax(180px, 0.85fr) minmax(130px, 0.65fr)
    32px;
}
/* Column shares from KARARLAR Genel → "Liste sayfalarının ortak dili". */
.document-catalog-settings-page .document-catalog-row {
  grid-template-columns:
    minmax(184px, 26fr) minmax(0, 44fr) minmax(88px, 14fr)
    minmax(120px, 16fr) 32px;
}
/* Two settings sidebars leave the catalog under ~500px below this width, so
   Description yields before the columns collide. */
@media (max-width: 1200px) {
  .document-catalog-settings-page .document-catalog-row {
    grid-template-columns:
      minmax(0, 1fr) minmax(88px, 0.4fr) minmax(120px, 0.6fr)
      32px;
  }
  .document-catalog-settings-page .document-description-cell {
    display: none;
  }
}

.document-catalog-settings-page .job-catalog-row,
.acknowledgement-page .job-catalog-row {
  min-height: 60px;
}
.document-catalog-settings-page .job-catalog-editor,
.acknowledgement-page .job-catalog-editor {
  max-width: 760px;
  border-color: color-mix(in srgb, var(--job-border) 86%, var(--job-accent));
  box-shadow: 0 8px 22px rgb(23 45 33 / 7%);
}
.acknowledgement-page .job-catalog-editor {
  max-width: 860px;
}
.document-catalog-settings-page .job-editor-title,
.acknowledgement-page .job-editor-title {
  padding: 12px 14px 11px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--job-soft) 58%, var(--job-bg)),
    var(--job-bg)
  );
}
.document-catalog-settings-page .job-editor-title h2,
.acknowledgement-page .job-editor-title h2 {
  font-size: 14px;
  font-weight: 650;
  margin-bottom: 3px;
}
.document-catalog-settings-page .job-editor-title p,
.acknowledgement-page .job-editor-title p {
  max-width: 620px;
}
.document-catalog-settings-page .job-column-headings .job-sort-button,
.acknowledgement-page .job-column-headings .job-sort-button {
  justify-content: flex-start;
}
.document-catalog-settings-page {
  --document-marker-size: 32px;
  --document-marker-gap: 10px;
}
.document-catalog-settings-page
  .job-column-headings.document-catalog-row
  > :first-child {
  padding-left: calc(var(--document-marker-size) + var(--document-marker-gap));
}
.document-catalog-marker {
  display: grid;
  width: var(--document-marker-size, 32px);
  height: var(--document-marker-size, 32px);
  flex: 0 0 var(--document-marker-size, 32px);
  place-items: center;
  border-radius: 6px;
  background: var(--job-soft);
  color: var(--job-accent);
}
.document-catalog-description {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--job-muted);
  font-size: 12px;
  font-weight: 400;
  margin-top: 3px;
}
.document-catalog-fields,
.retention-fields,
.acknowledgement-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 14px;
}
.acknowledgement-fields {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.retention-fields,
.acknowledgement-fields {
  margin: 0;
}
.document-catalog-fields .field-wide,
.retention-authority-field,
.acknowledgement-fields .field-wide {
  grid-column: 1 / -1;
}
.document-catalog-fields .document-description-field {
  grid-column: 2;
  grid-row: 1 / span 2;
}
.document-catalog-settings-page .job-field,
.acknowledgement-page .job-field {
  min-width: 0;
}
.document-catalog-settings-page .job-field > span,
.acknowledgement-page .job-field > span {
  color: var(--job-text);
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 5px;
}
.jobs-settings-page .job-catalog-editor textarea {
