/* DOC-TABLE: the one look of the list pages — Settings → Documents,
   Employees → Documents, Announcements, Important Dates, Notifications and
   Availability (KARARLAR Genel → "Liste sayfalarının ortak dili"). A page
   joins by adding `list-page` to its section; nothing else reads these rules.
   Selectors carry `.list-page` twice where a page's own stylesheet (loaded
   later) would otherwise win at the same weight. */

/* Page skeleton, desktop: heading block 142 + 18, tab row 40 + 10, filter row
   36 + 16, then the table. A tab, a filter or an empty list never moves
   anything above the table. */
.list-page.list-page > .catalog-page-header {
  box-sizing: border-box;
  height: 142px;
  min-height: 142px;
  flex: 0 0 auto;
  align-items: center;
  margin: 0 0 18px;
  padding: 32px 0 20px;
}
.list-page.list-page > .catalog-page-header p {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.list-page.list-page .catalog-toolbar {
  display: grid;
  gap: 10px;
  margin: 0 0 16px;
}

/* Tabs: underlined, on a 1 px line. */
.list-page.list-page .catalog-toolbar-status-row {
  height: 40px;
  min-height: 40px;
  align-items: stretch;
  border-bottom: 1px solid var(--theme-border);
}
.list-page.list-page .catalog-status-tabs {
  flex-wrap: nowrap;
  gap: 6px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: none;
}
.list-page.list-page .catalog-toolbar .catalog-status-tabs button {
  height: 40px;
  gap: 6px;
  margin-bottom: -1px;
  padding: 8px 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: none;
  box-shadow: none;
  color: var(--theme-muted);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}
.list-page.list-page .catalog-toolbar .catalog-status-tabs button.active {
  border-bottom-color: var(--theme-accent);
  color: var(--theme-text);
  font-weight: 600;
}
.list-page.list-page .catalog-toolbar .catalog-status-tabs button:focus-visible {
  outline: 2px solid var(--theme-focus);
  outline-offset: -2px;
}
.list-page.list-page .catalog-toolbar-status-row .weekly-team-count {
  align-self: center;
  color: var(--theme-text-secondary);
  font-size: 13px;
}

/* Filter row: 36 high; the search takes every pixel left, up to the table's
   right edge or the button at the end. */
.list-page.list-page .catalog-toolbar-filter-row {
  height: 36px;
  min-height: 36px;
  gap: 10px;
}
.list-page.list-page .catalog-toolbar-filter-row .toolbar-filter-select {
  box-sizing: border-box;
  width: 200px;
  max-width: none;
  height: 36px;
  min-height: 36px;
  flex: 0 0 200px;
  padding: 0 10px;
  border: 1px solid var(--theme-border-control);
  border-radius: 6px;
  background-color: var(--theme-surface);
  color: var(--theme-text);
  font-size: 13px;
}
.list-page.list-page
  .catalog-toolbar-filter-row
  .toolbar-filter-select.list-filter-narrow {
