/* Option 03: compact filter menus. Inter comes from the app root (styles.css). */
.schedule-topbar-filter {
  --filter-surface: #fff;
  --filter-text: #23312b;
  --filter-muted: var(--theme-muted);
  --filter-border: #dfe5e1;
  --filter-soft: #f5f7f5;
  --filter-accent: #376554;
  --filter-selected: #edf4ef;
}
/* Specificity keeps this component independent of legacy global menu rules. */
:root .schedule-topbar-filter[data-filter-id] .schedule-topbar-filter-menu {
  top: calc(100% + 7px);
  display: flex;
  flex-direction: column;
  width: 270px;
  max-width: calc(100vw - 24px);
  max-height: min(520px, 64vh);
  min-height: 0;
  gap: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--filter-border);
  border-radius: 5px;
  background: var(--filter-surface);
  color: var(--filter-text);
  box-shadow: 0 8px 22px #0b211f25;
  font:
    400 13px var(--theme-font-sans);
  transform-origin: top left;
}
.schedule-topbar-filter[open] .schedule-topbar-filter-menu {
  animation: schedule-filter-reveal 120ms ease-out;
}
.schedule-topbar-filter-heading,
.schedule-topbar-filter-footer {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 13px;
}
.schedule-topbar-filter-heading {
  border-bottom: 1px solid var(--filter-border);
}
.schedule-topbar-filter-heading strong {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.15px;
}
.schedule-topbar-filter-heading > span {
  font:
    400 10px var(--theme-font-sans);
  color: var(--filter-muted);
}
.schedule-topbar-filter-all-section,
.schedule-topbar-filter-top-content {
  flex: 0 0 auto;
  padding: 6px;
  border-bottom: 1px solid var(--filter-border);
}
.schedule-topbar-filter-top-content {
  padding: 0;
}
.schedule-topbar-filter-list {
  min-height: 0;
  max-height: 327px;
  padding: 5px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--filter-border) transparent;
}
.schedule-topbar-filter-footer {
  gap: normal;
  padding: 8px 12px;
  background: var(--filter-soft);
  color: var(--filter-muted);
  font:
    400 9px var(--theme-font-sans);
  border-top: 1px solid var(--filter-border);
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  button {
  width: 100%;
  min-height: 29px;
  gap: 10px;
  border: 0;
  border-radius: 2px;
  padding: 5px 9px;
  background: transparent;
  color: var(--filter-text);
  font:
    400 12px/1.4 var(--theme-font-sans);
  transition:
    background 120ms,
    color 120ms;
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  button[data-selected="true"]:not(.schedule-topbar-filter-group-button) {
  background: var(--filter-selected);
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  button:hover {
  background: var(--filter-soft);
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  button:focus-visible {
  outline: 2px solid var(--filter-accent);
  outline-offset: 3px;
}
.schedule-topbar-filter-list
  > .schedule-topbar-filter-item
  + .schedule-topbar-filter-item,
.schedule-topbar-filter-group-items
  > .schedule-topbar-filter-item
  + .schedule-topbar-filter-item {
