  border: 1px solid var(--filter-border);
  border-radius: 2px;
  background: transparent;
  color: transparent;
  font:
    400 9px/1 var(--theme-font-sans);
}
:root
  .schedule-topbar-filter[data-filter-id]
  [aria-checked="true"]
  .schedule-topbar-filter-check {
  background: var(--filter-accent);
  border-color: var(--filter-accent);
  color: var(--filter-surface);
}
:root
  .schedule-topbar-filter[data-filter-id]
  [aria-checked="mixed"]
  .schedule-topbar-filter-check {
  background: var(--filter-selected);
  border-color: var(--filter-accent);
  color: var(--filter-accent);
}
:root .schedule-topbar-filter[data-filter-id] .schedule-topbar-filter-label {
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: 1.4;
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  .schedule-topbar-filter-all {
  font-weight: 400;
}
.schedule-topbar-filter-group + .schedule-topbar-filter-group {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid var(--filter-border);
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  .schedule-topbar-filter-group-button {
  min-height: 28px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.07em;
  color: var(--filter-muted);
  background: transparent;
}
.schedule-topbar-filter-group-count {
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0;
}
.schedule-topbar-filter-group-items {
  margin-left: 15px;
  padding-left: 6px;
  border-left: 1px solid var(--filter-border);
}
:root
  .schedule-topbar-filter[data-filter-id]
  .schedule-topbar-filter-menu
  .schedule-grid-view-mode-toggle {
  min-height: 38px;
  padding: 11px 16px;
  font-size: 11px;
  font-weight: 500;
  line-height: normal;
}
.schedule-topbar-filter .schedule-grid-view-mode-toggle > svg {
  display: none;
}
:root .schedule-topbar-filter[data-filter-id] .schedule-filter-layout-switch {
  position: relative;
  flex: 0 0 28px;
  width: 28px;
  height: 16px;
  border-radius: 10px;
  background: var(--filter-border);
}
.schedule-filter-layout-switch::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  background: var(--filter-surface);
  border-radius: 50%;
  transition: transform 160ms;
}
:root
  .schedule-topbar-filter[data-filter-id]
  [aria-pressed="true"]
  .schedule-filter-layout-switch {
  background: var(--filter-accent);
}
[aria-pressed="true"] > .schedule-filter-layout-switch::after {
  transform: translateX(12px);
}
@keyframes schedule-filter-reveal {
  from {
    opacity: 0.4;
    clip-path: inset(0 0 15% 0);
  }
  to {
    opacity: 1;
    clip-path: inset(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .schedule-topbar-filter[open] .schedule-topbar-filter-menu {
    animation: none;
  }
  :root
    .schedule-topbar-filter[data-filter-id]
    .schedule-topbar-filter-menu
    button,
  .schedule-filter-layout-switch::after {
    transition: none;
  }
}

/* NoAccessState: the shared "you may not" screen. Tokens only.
   Same box as the Schedule's loading/error state, centered. */
.no-access {
  display: flex;
  min-height: 220px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin: 20px;
  border: 1px solid var(--theme-border);
  border-radius: 6px;
  padding: 28px 20px;
  background: var(--theme-surface);
  color: var(--theme-muted);
  text-align: center;
}
.no-access h2 {
  margin: 0;
  color: var(--theme-text);
  font-size: 16px;
  line-height: 1.35;
}
.no-access p {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
}
.no-access .no-access-help {
  color: var(--theme-text-body);
}
.no-access-icon {
  display: inline-flex;
  width: 44px;
  height: 44px;
  flex: none;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--theme-surface-muted);
  color: var(--theme-text-body);
}
.no-access-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.no-access .nf-button {
  text-decoration: none;
}

@media (max-width: 720px) {
  .no-access {
    margin: 12px;
  }
}
